INSERT INTO calculus (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('What is the derivative of f(x) = x³?', '3x²', '3x', 'x²', '2x³', '3x²', 'Power rule: d/dx(xⁿ) = nxⁿ⁻¹. So d/dx(x³) = 3x².', 720, 'Calculus'),
('What is the integral of f(x) = 2x?', 'x² + C', '2x² + C', 'x + C', '2 + C', 'x² + C', 'The antiderivative of 2x is x² + C. Verify by differentiating: d/dx(x²) = 2x.', 720, 'Calculus'),
('What is the limit of (sin x)/x as x approaches 0?', '1', '0', 'undefined', 'infinity', '1', 'This is a fundamental limit. As x→0, (sin x)/x → 1. It can be proven using the squeeze theorem.', 740, 'Calculus'),
('What is the derivative of f(x) = e^x?', 'e^x', 'xe^(x-1)', 'e^(x-1)', 'ln(x)', 'e^x', 'The exponential function e^x is its own derivative. This is what makes e special.', 730, 'Calculus'),
('Using the chain rule, what is d/dx[sin(x²)]?', '2x·cos(x²)', 'cos(x²)', '2x·sin(x²)', 'cos(2x)', '2x·cos(x²)', 'Chain rule: d/dx[f(g(x))] = f''(g(x))·g''(x). Here f = sin, g = x², so result is cos(x²)·2x.', 820, 'Calculus'),
('What is the derivative of f(x) = ln(x)?', '1/x', 'x', 'ln(x)/x', 'e^x', '1/x', 'The derivative of the natural log is d/dx[ln(x)] = 1/x for x > 0.', 780, 'Calculus'),
('Evaluate: ∫ x·eˣ dx', 'xe^x - e^x + C', 'xe^x + C', 'e^x + C', 'x²e^x/2 + C', 'xe^x - e^x + C', 'Integration by parts: ∫u·dv = uv - ∫v·du. Let u=x, dv=eˣdx. Then du=dx, v=eˣ. Result: xeˣ - eˣ + C.', 980, 'Calculus'),
('What is the derivative of f(x) = x·sin(x)?', 'sin(x) + x·cos(x)', 'x·cos(x)', 'cos(x)', 'sin(x) - x·cos(x)', 'sin(x) + x·cos(x)', 'Product rule: d/dx[u·v] = u''v + uv''. Here u=x, v=sin(x), so result = sin(x) + x·cos(x).', 850, 'Calculus'),
('Using L''Hôpital''s rule, evaluate lim(x→0) (1 - cos x)/x²', '1/2', '0', '1', 'undefined', '1/2', 'Both numerator and denominator → 0. Apply L''Hôpital twice: (sin x)/(2x) → (cos x)/2 → 1/2.', 1050, 'Calculus'),
('What is the Taylor series expansion of e^x around x=0?', '1 + x + x²/2! + x³/3! + ...', '1 + x + x² + x³ + ...', 'x - x³/3! + x⁵/5! - ...', '1 - x²/2! + x⁴/4! - ...', '1 + x + x²/2! + x³/3! + ...', 'The Maclaurin series of eˣ is Σ xⁿ/n! = 1 + x + x²/2! + x³/3! + ... converges for all x.', 1250, 'Calculus'),
('Solve the differential equation dy/dx = y, with y(0) = 1', 'y = e^x', 'y = x', 'y = ln(x)', 'y = x²/2', 'y = e^x', 'Separating variables: dy/y = dx → ln|y| = x + C → y = Ae^x. With y(0)=1: A=1, so y=eˣ.', 1150, 'Calculus'),
('What does the Fundamental Theorem of Calculus state (Part 1)?', 'If F(x) = ∫ₐˣ f(t)dt, then F''(x) = f(x)', 'Every continuous function has an antiderivative', '∫ₐᵇ f(x)dx = F(b) - F(a)', 'Differentiation and integration are unrelated', 'If F(x) = ∫ₐˣ f(t)dt, then F''(x) = f(x)', 'Part 1 of the FTC states that the derivative of the integral function F(x) = ∫ₐˣ f(t)dt is f(x), connecting differentiation and integration.', 1400, 'Calculus');
INSERT INTO discretemath (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('How many elements are in the power set of a set with 3 elements?', '8', '6', '9', '3', '8', 'The power set of a set with n elements has 2ⁿ elements. For n=3: 2³ = 8.', 720, 'DiscreteMath'),
('What is the result of A ∩ B if A = {1,2,3} and B = {2,3,4}?', '{2,3}', '{1,2,3,4}', '{1,4}', '{1,2,3}', '{2,3}', 'Intersection (∩) contains only elements in BOTH sets. A and B share 2 and 3.', 720, 'DiscreteMath'),
('In propositional logic, what is the truth value of "P AND (NOT P)"?', 'Always false', 'Always true', 'Depends on P', 'Undefined', 'Always false', 'P ∧ ¬P is a contradiction — it is always false regardless of the truth value of P.', 740, 'DiscreteMath'),
('How many ways can you choose 3 items from 7 distinct items (order doesn''t matter)?', '35', '21', '210', '42', '35', 'Combination formula: C(7,3) = 7!/(3!·4!) = 35. Order doesn''t matter, so we use combinations.', 820, 'DiscreteMath'),
('What is the base case for proving by induction that 1+2+...+n = n(n+1)/2?', 'n=1: 1 = 1(2)/2 = 1 ✓', 'n=0: 0 = 0', 'n=2: 3 = 2(3)/2 ✓', 'n=1: 1 = 1²', 'n=1: 1 = 1(2)/2 = 1 ✓', 'For mathematical induction, the base case n=1 gives: LHS=1, RHS=1(1+1)/2=1. Both sides equal 1, so base case holds.', 880, 'DiscreteMath'),
('In a simple graph with 5 vertices, what is the maximum number of edges?', '10', '5', '20', '15', '10', 'A complete graph Kₙ has n(n-1)/2 edges. For n=5: 5(4)/2 = 10.', 950, 'DiscreteMath'),
('What recurrence relation describes the Fibonacci sequence?', 'F(n) = F(n-1) + F(n-2)', 'F(n) = 2·F(n-1)', 'F(n) = F(n-1)·F(n-2)', 'F(n) = F(n-1) + n', 'F(n) = F(n-1) + F(n-2)', 'Fibonacci: each term is the sum of the two preceding terms. F(1)=1, F(2)=1, F(n)=F(n-1)+F(n-2).', 900, 'DiscreteMath'),
('What is the chromatic number of a complete graph K₄?', '4', '3', '6', '2', '4', 'In K₄ every vertex connects to every other vertex. No two adjacent vertices can share a color, so you need 4 distinct colors.', 1150, 'DiscreteMath'),
('Which problem is NP-complete?', 'Boolean satisfiability (SAT)', 'Sorting a list', 'Finding shortest path', 'Binary search', 'Boolean satisfiability (SAT)', 'SAT was the first problem proven NP-complete (Cook''s theorem, 1971). Many other NP-complete problems are reduced from SAT.', 1450, 'DiscreteMath'),
('What does Euler''s formula V - E + F = 2 apply to?', 'Connected planar graphs', 'All graphs', 'Trees only', 'Bipartite graphs', 'Connected planar graphs', 'Euler''s formula V-E+F=2 holds for any connected planar graph, where V=vertices, E=edges, F=faces (including the outer face).', 1300, 'DiscreteMath');
INSERT INTO linearalgebra (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('What is the dot product of vectors (1,2) and (3,4)?', '11', '5', '7', '14', '11', 'Dot product: (1)(3) + (2)(4) = 3 + 8 = 11.', 720, 'LinearAlgebra'),
('What is the determinant of the 2×2 matrix [[1,2],[3,4]]?', '-2', '2', '-10', '10', '-2', 'For [[a,b],[c,d]], det = ad - bc = (1)(4) - (2)(3) = 4 - 6 = -2.', 750, 'LinearAlgebra'),
('A matrix multiplied by its inverse equals which matrix?', 'The identity matrix', 'The zero matrix', 'The transpose', 'The original matrix', 'The identity matrix', 'By definition, A·A⁻¹ = I, where I is the identity matrix (1s on diagonal, 0s elsewhere).', 780, 'LinearAlgebra'),
('If λ is an eigenvalue of matrix A with eigenvector v, which equation holds?', 'Av = λv', 'Av = v/λ', 'A + v = λ', 'det(A) = λ', 'Av = λv', 'The eigenvalue equation is Av = λv: multiplying A by eigenvector v just scales v by the eigenvalue λ.', 900, 'LinearAlgebra'),
('What is the rank of a matrix?', 'The number of linearly independent rows (or columns)', 'The number of rows', 'The determinant', 'The trace', 'The number of linearly independent rows (or columns)', 'Rank = dimension of the column space = number of linearly independent rows = number of pivots in row echelon form.', 920, 'LinearAlgebra'),
('What does it mean for a set of vectors to be linearly independent?', 'No vector can be written as a linear combination of the others', 'All vectors are unit vectors', 'All vectors are orthogonal', 'The vectors span all of Rⁿ', 'No vector can be written as a linear combination of the others', 'Linear independence means c₁v₁ + c₂v₂ + ... = 0 implies all cᵢ = 0. No vector is "redundant".', 950, 'LinearAlgebra'),
('What is the trace of the matrix [[3,1],[2,4]]?', '7', '10', '5', '-2', '7', 'The trace is the sum of diagonal elements: 3 + 4 = 7.', 820, 'LinearAlgebra'),
('In Gram-Schmidt orthogonalization, what is the goal?', 'Convert a basis into an orthonormal basis', 'Find eigenvalues', 'Invert a matrix', 'Compute the determinant', 'Convert a basis into an orthonormal basis', 'Gram-Schmidt takes a set of linearly independent vectors and produces an orthonormal set spanning the same subspace.', 1100, 'LinearAlgebra'),
('What does the singular value decomposition (SVD) of a matrix A yield?', 'A = UΣVᵀ where U,V are orthogonal and Σ is diagonal', 'A = LU where L is lower triangular', 'A = QR where Q is orthogonal', 'A = PDP⁻¹ where D is diagonal', 'A = UΣVᵀ where U,V are orthogonal and Σ is diagonal', 'SVD decomposes any m×n matrix as A=UΣVᵀ. The diagonal entries of Σ are singular values. Fundamental in data science/PCA.', 1500, 'LinearAlgebra'),
('If Ax = b has no solution, the least-squares solution minimises which quantity?', '||Ax - b||²', '||x||²', 'det(A)', 'trace(A)', '||Ax - b||²', 'The least-squares solution x̂ = (AᵀA)⁻¹Aᵀb minimises the squared residual ||Ax-b||², finding the best approximate solution.', 1350, 'LinearAlgebra');
INSERT INTO statistics (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('What is the mean of the dataset {2, 4, 6, 8, 10}?', '6', '5', '7', '8', '6', 'Mean = (2+4+6+8+10)/5 = 30/5 = 6.', 710, 'Statistics'),
('What is the probability of rolling a 6 on a fair die?', '1/6', '1/3', '1/2', '1/4', '1/6', 'A fair die has 6 equally likely outcomes. P(rolling 6) = 1/6 ≈ 0.167.', 710, 'Statistics'),
('For independent events A and B, P(A and B) equals what?', 'P(A) × P(B)', 'P(A) + P(B)', 'P(A) + P(B) - P(A or B)', 'P(A|B)', 'P(A) × P(B)', 'For independent events, knowing B gives no information about A, so P(A∩B) = P(A)·P(B).', 780, 'Statistics'),
('What does standard deviation measure?', 'How spread out values are from the mean', 'The middle value in a dataset', 'The most frequent value', 'The range of a dataset', 'How spread out values are from the mean', 'Standard deviation is the square root of variance. Small SD = data clustered near mean; large SD = data widely spread.', 770, 'Statistics'),
('In a normal distribution, approximately what percentage of data falls within 1 standard deviation of the mean?', '68%', '95%', '99.7%', '50%', '68%', 'The empirical rule: ~68% within 1σ, ~95% within 2σ, ~99.7% within 3σ of the mean.', 850, 'Statistics'),
('What is Bayes'' theorem?', 'P(A|B) = P(B|A)·P(A) / P(B)', 'P(A|B) = P(A) + P(B)', 'P(A|B) = P(A) / P(B)', 'P(A|B) = P(B|A)', 'P(A|B) = P(B|A)·P(A) / P(B)', 'Bayes'' theorem updates probability based on new evidence. P(A|B) = P(B|A)·P(A)/P(B) where P(A) is the prior.', 1000, 'Statistics'),
('In hypothesis testing, what does a p-value represent?', 'Probability of observing results this extreme assuming H₀ is true', 'Probability that H₀ is true', 'Probability that H₁ is true', 'The significance level', 'Probability of observing results this extreme assuming H₀ is true', 'The p-value is the probability of obtaining a test statistic at least as extreme as observed, assuming the null hypothesis is true.', 1050, 'Statistics'),
('What is the Central Limit Theorem?', 'Sample means approach a normal distribution as sample size increases', 'All populations are normally distributed', 'Large samples always have small variance', 'The mean equals the median for all distributions', 'Sample means approach a normal distribution as sample size increases', 'CLT: regardless of population distribution, the distribution of sample means approaches N(μ, σ²/n) as n → ∞.', 1150, 'Statistics'),
('What does maximum likelihood estimation (MLE) do?', 'Finds parameters that maximise the probability of observed data', 'Minimises the sum of squared errors', 'Finds the median of the posterior distribution', 'Minimises the number of parameters', 'Finds parameters that maximise the probability of observed data', 'MLE finds θ̂ = argmax L(θ|data) where L is the likelihood function — the parameter values under which the data is most probable.', 1400, 'Statistics'),
('What distinguishes a Type I error from a Type II error?', 'Type I: rejecting a true H₀. Type II: failing to reject a false H₀', 'Type I: accepting H₁. Type II: accepting H₀', 'Type I: small sample error. Type II: large sample error', 'Type I is worse than Type II always', 'Type I: rejecting a true H₀. Type II: failing to reject a false H₀', 'Type I error (false positive) = α = significance level. Type II error (false negative) = β. Power = 1 - β.', 1100, 'Statistics');
INSERT INTO anatomy (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('How many chambers does the human heart have?', '4', '2', '3', '6', '4', 'The heart has 4 chambers: right atrium, right ventricle, left atrium, and left ventricle.', 710, 'Anatomy'),
('Which bone is the longest in the human body?', 'Femur', 'Humerus', 'Tibia', 'Fibula', 'Femur', 'The femur (thigh bone) is the longest, strongest bone in the body, running from the hip to the knee.', 710, 'Anatomy'),
('Which lobe of the brain is primarily responsible for vision?', 'Occipital lobe', 'Frontal lobe', 'Parietal lobe', 'Temporal lobe', 'Occipital lobe', 'The occipital lobe, at the back of the brain, contains the primary visual cortex and processes visual information.', 760, 'Anatomy'),
('What is the anatomical term for the palm-side of the hand?', 'Palmar', 'Dorsal', 'Lateral', 'Medial', 'Palmar', 'Palmar (or volar) refers to the anterior surface of the hand. Dorsal refers to the back of the hand.', 770, 'Anatomy'),
('How many cranial nerves are there in the human nervous system?', '12', '10', '8', '14', '12', 'There are 12 pairs of cranial nerves (CN I–XII), emerging directly from the brain and brainstem, not the spinal cord.', 850, 'Anatomy'),
('The mitral valve is located between which two heart chambers?', 'Left atrium and left ventricle', 'Right atrium and right ventricle', 'Left ventricle and aorta', 'Right ventricle and pulmonary artery', 'Left atrium and left ventricle', 'The mitral (bicuspid) valve controls blood flow from the left atrium to the left ventricle. The tricuspid valve is on the right side.', 900, 'Anatomy'),
('Which structure passes through the carpal tunnel?', 'Median nerve', 'Ulnar nerve', 'Radial nerve', 'Axillary nerve', 'Median nerve', 'The carpal tunnel contains the median nerve and 9 flexor tendons. Compression causes carpal tunnel syndrome.', 1020, 'Anatomy'),
('The Circle of Willis is a structure found where in the body?', 'Base of the brain', 'Heart', 'Kidney', 'Liver', 'Base of the brain', 'The Circle of Willis is an arterial circle at the base of the brain connecting the carotid and vertebrobasilar systems, providing collateral blood flow.', 1150, 'Anatomy'),
('What is the name of the tough outer membrane that surrounds the brain?', 'Dura mater', 'Arachnoid mater', 'Pia mater', 'Periosteum', 'Dura mater', 'The dura mater is the outermost of the three meninges. Deep to it: arachnoid mater, then pia mater (touching the brain surface).', 1050, 'Anatomy'),
('Where does lymphatic drainage from the right arm and right side of the thorax ultimately drain into?', 'Right subclavian vein', 'Left subclavian vein', 'Superior vena cava', 'Right jugular vein', 'Right subclavian vein', 'The right lymphatic duct drains into the right subclavian vein. The thoracic duct (left side) drains everything else into the left subclavian vein.', 1350, 'Anatomy');
INSERT INTO microbiology (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('What does Gram staining differentiate?', 'Bacteria with thick vs thin peptidoglycan cell walls', 'Viruses from bacteria', 'Aerobic from anaerobic bacteria', 'Spore-forming from non-spore-forming bacteria', 'Bacteria with thick vs thin peptidoglycan cell walls', 'Gram-positive bacteria retain crystal violet (appear purple) due to thick peptidoglycan. Gram-negative bacteria lose it and stain pink with safranin.', 720, 'Microbiology'),
('What is binary fission?', 'Asexual reproduction by splitting into two cells', 'Sexual reproduction in bacteria', 'A form of budding', 'Viral replication', 'Asexual reproduction by splitting into two cells', 'Binary fission is how most bacteria reproduce: the cell duplicates its DNA, grows, and divides into two identical daughter cells.', 720, 'Microbiology'),
('Which type of RNA carries amino acids to the ribosome during translation?', 'tRNA (transfer RNA)', 'mRNA (messenger RNA)', 'rRNA (ribosomal RNA)', 'snRNA', 'tRNA (transfer RNA)', 'tRNA has an anticodon that matches mRNA codons and carries the corresponding amino acid to the ribosome for protein synthesis.', 800, 'Microbiology'),
('What is the lytic cycle in bacteriophage replication?', 'Phage replicates and lyses the host cell', 'Phage DNA integrates into host chromosome', 'Host cell becomes dormant', 'Phage exits without killing the host', 'Phage replicates and lyses the host cell', 'In the lytic cycle: phage injects DNA → host replicates phage → new phages lyse the cell. Contrast with lysogenic cycle where phage DNA integrates.', 880, 'Microbiology'),
('What mechanism do bacteria use to become resistant to beta-lactam antibiotics?', 'Producing beta-lactamase enzymes', 'Increasing membrane permeability', 'Decreasing ribosome number', 'Changing their DNA sequence randomly', 'Producing beta-lactamase enzymes', 'Beta-lactamase cleaves the beta-lactam ring of antibiotics like penicillin, inactivating them. MRSA uses an altered penicillin-binding protein instead.', 1050, 'Microbiology'),
('What is a biofilm?', 'A structured community of bacteria embedded in a self-produced matrix', 'A thin film of viral particles', 'A bacterial toxin layer', 'A laboratory growth medium', 'A structured community of bacteria embedded in a self-produced matrix', 'Biofilms form on surfaces and medical devices. Bacteria in biofilms are up to 1000× more resistant to antibiotics than planktonic cells.', 1100, 'Microbiology'),
('What is horizontal gene transfer?', 'Transfer of genes between organisms in the same generation', 'Gene transfer from parent to offspring', 'Mutation caused by radiation', 'Gene expression regulation', 'Transfer of genes between organisms in the same generation', 'HGT occurs via conjugation (plasmid transfer), transformation (uptake of free DNA), or transduction (phage-mediated). Key driver of antibiotic resistance spread.', 1300, 'Microbiology'),
('What is the mechanism of action of CRISPR-Cas9?', 'Guide RNA directs Cas9 nuclease to cut specific DNA sequences', 'Cas9 methylates target DNA', 'Guide RNA blocks gene transcription', 'Cas9 inserts random mutations', 'Guide RNA directs Cas9 nuclease to cut specific DNA sequences', 'CRISPR-Cas9: sgRNA (guide RNA) hybridises to target DNA, directing Cas9 to make a double-strand break. The cell repairs it, enabling gene editing.', 1500, 'Microbiology'),
('Which bacterial structure protects against phagocytosis?', 'Capsule', 'Flagellum', 'Pilus', 'Ribosome', 'Capsule', 'The polysaccharide capsule prevents opsonisation and phagocytosis by macrophages. Encapsulated bacteria (e.g. S. pneumoniae) are more virulent.', 980, 'Microbiology'),
('What is quorum sensing?', 'Cell-density-dependent gene regulation via signalling molecules', 'Bacterial response to temperature', 'Synchronised cell division', 'Nutrient-sensing pathway', 'Cell-density-dependent gene regulation via signalling molecules', 'Bacteria secrete autoinducers that accumulate with population density. Once a threshold is reached, coordinated behaviours (biofilm, virulence) are triggered.', 1250, 'Microbiology');
INSERT INTO molecularbiology (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('What are the four bases found in DNA?', 'Adenine, Thymine, Guanine, Cytosine', 'Adenine, Uracil, Guanine, Cytosine', 'Adenine, Thymine, Guanine, Uracil', 'Adenine, Thymine, Cytosine, Serine', 'Adenine, Thymine, Guanine, Cytosine', 'DNA contains A, T, G, C. RNA replaces Thymine with Uracil. Base pairing: A-T (2 H-bonds), G-C (3 H-bonds).', 710, 'MolecularBiology'),
('What enzyme synthesises a new DNA strand during replication?', 'DNA polymerase', 'RNA polymerase', 'Helicase', 'Ligase', 'DNA polymerase', 'DNA polymerase extends the new strand by adding nucleotides complementary to the template (5''→3'' direction). It needs a primer to start.', 730, 'MolecularBiology'),
('What is the central dogma of molecular biology?', 'DNA → RNA → Protein', 'RNA → DNA → Protein', 'Protein → RNA → DNA', 'DNA → Protein → RNA', 'DNA → RNA → Protein', 'The central dogma: DNA is transcribed to mRNA, which is translated into protein. Reverse transcriptase (retroviruses) can go RNA→DNA.', 740, 'MolecularBiology'),
('What is the role of a promoter in gene expression?', 'It is a DNA sequence where RNA polymerase binds to initiate transcription', 'It increases translation speed', 'It stabilises mRNA', 'It codes for a regulatory protein', 'It is a DNA sequence where RNA polymerase binds to initiate transcription', 'Promoters (e.g. TATA box) are upstream of genes. Transcription factors bind the promoter to recruit RNA polymerase and initiate transcription.', 850, 'MolecularBiology'),
('What is alternative splicing?', 'Different combinations of exons are joined to produce multiple proteins from one gene', 'Introns are retained in mature mRNA', 'DNA is spliced into the chromosome', 'Different genes are transcribed together', 'Different combinations of exons are joined to produce multiple proteins from one gene', 'Alternative splicing allows one gene to produce multiple protein isoforms. ~95% of human multi-exon genes are alternatively spliced.', 1000, 'MolecularBiology'),
('What is the function of telomerase?', 'It extends telomeres at chromosome ends to prevent shortening', 'It repairs double-strand breaks', 'It methylates DNA', 'It removes RNA primers', 'It extends telomeres at chromosome ends to prevent shortening', 'Without telomerase, chromosomes shorten with each division. Telomerase adds TTAGGG repeats. It is active in stem cells and cancer cells.', 1150, 'MolecularBiology'),
('What is epigenetic modification?', 'Heritable changes in gene expression without altering the DNA sequence', 'Mutations in the coding sequence', 'Changes in protein folding', 'Recombination during meiosis', 'Heritable changes in gene expression without altering the DNA sequence', 'Epigenetics includes DNA methylation (gene silencing) and histone modification (chromatin remodelling). These are heritable through cell division.', 1200, 'MolecularBiology'),
('What is a missense mutation?', 'A nucleotide change that results in a different amino acid', 'A mutation that creates a stop codon', 'Deletion of a single nucleotide', 'Insertion of extra nucleotides', 'A nucleotide change that results in a different amino acid', 'Missense: codon changes to specify a different amino acid. Contrast: nonsense (stop codon), silent (same amino acid), frameshift (reading frame shift).', 950, 'MolecularBiology'),
('What is the role of chaperone proteins?', 'They assist in correct protein folding and prevent aggregation', 'They degrade misfolded proteins', 'They transport proteins across membranes', 'They regulate gene transcription', 'They assist in correct protein folding and prevent aggregation', 'Chaperones (e.g. HSP70) bind unfolded proteins, preventing inappropriate interactions and allowing correct folding. Important under stress conditions.', 1300, 'MolecularBiology'),
('What is the significance of the Shine-Dalgarno sequence in bacteria?', 'It is an mRNA sequence that aligns the ribosome for translation initiation', 'It is a DNA regulatory element', 'It marks the end of a gene', 'It codes for the start methionine', 'It is an mRNA sequence that aligns the ribosome for translation initiation', 'The Shine-Dalgarno sequence (5''-AGGAGG-3'') is complementary to the 16S rRNA. It positions the ribosome at the start codon (AUG) in prokaryotes.', 1450, 'MolecularBiology');
INSERT INTO physiology (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('What is cardiac output?', 'Heart rate × stroke volume', 'Systolic pressure × heart rate', 'Blood volume / time', 'Heart rate / stroke volume', 'Heart rate × stroke volume', 'CO = HR × SV. A resting HR of 70 bpm × SV of 70 mL = ~4.9 L/min. Increases dramatically during exercise.', 730, 'Physiology'),
('Which ion is responsible for triggering the action potential in neurons?', 'Sodium (Na⁺)', 'Potassium (K⁺)', 'Calcium (Ca²⁺)', 'Chloride (Cl⁻)', 'Sodium (Na⁺)', 'During depolarisation, voltage-gated Na⁺ channels open and Na⁺ rushes into the cell, raising membrane potential from -70mV toward +30mV.', 750, 'Physiology'),
('What is the primary function of the kidney''s glomerulus?', 'Filtration of blood plasma', 'Reabsorption of glucose', 'Secretion of hydrogen ions', 'Concentration of urine', 'Filtration of blood plasma', 'The glomerulus is a capillary network in the Bowman''s capsule. High pressure forces plasma (minus large proteins) into the tubule at ~180L/day.', 800, 'Physiology'),
('What does the Frank-Starling law of the heart describe?', 'Increased ventricular filling leads to increased stroke volume', 'Heart rate decreases when blood pressure rises', 'Cardiac output is constant regardless of filling', 'Stroke volume decreases with exercise', 'Increased ventricular filling leads to increased stroke volume', 'Frank-Starling: the more the ventricle is stretched (preload), the stronger the contraction and the greater the stroke volume. Automatic output matching.', 980, 'Physiology'),
('What is the Henderson-Hasselbalch equation used for?', 'Calculating blood pH from bicarbonate and CO₂ levels', 'Calculating cardiac output', 'Measuring renal clearance', 'Determining lung compliance', 'Calculating blood pH from bicarbonate and CO₂ levels', 'pH = pKa + log([HCO₃⁻]/[H₂CO₃]). Normal pH = 6.1 + log(24/1.2) = 7.4. Essential for acid-base analysis.', 1100, 'Physiology'),
('During exercise, how does the oxygen-haemoglobin dissociation curve shift?', 'Right shift (Bohr effect) — favouring O₂ release to tissues', 'Left shift — favouring O₂ binding', 'No shift', 'Vertical shift', 'Right shift (Bohr effect) — favouring O₂ release to tissues', 'Exercise raises CO₂, temperature, and 2,3-DPG, decreasing haemoglobin''s O₂ affinity. The curve shifts right, releasing more O₂ to working muscles.', 1150, 'Physiology'),
('What is the primary mechanism of countercurrent multiplication in the kidney?', 'Active NaCl transport out of the ascending loop creates an osmotic gradient', 'Water is pumped out of the descending loop', 'Urea is concentrated in the cortex', 'ADH drives active transport of water', 'Active NaCl transport out of the ascending loop creates an osmotic gradient', 'The thick ascending limb pumps NaCl into the medullary interstitium (impermeably to water), creating hyperosmolarity that concentrates urine in the collecting duct.', 1350, 'Physiology'),
('What causes the QRS complex on an ECG?', 'Ventricular depolarisation', 'Atrial depolarisation', 'Ventricular repolarisation', 'Atrial repolarisation', 'Ventricular depolarisation', 'P wave = atrial depolarisation. QRS = ventricular depolarisation (largest because ventricles are biggest). T wave = ventricular repolarisation.', 950, 'Physiology'),
('Which hormone primarily regulates blood calcium levels?', 'Parathyroid hormone (PTH)', 'Insulin', 'Cortisol', 'ADH', 'Parathyroid hormone (PTH)', 'PTH is released when Ca²⁺ drops. It increases Ca²⁺ by: bone resorption, renal Ca²⁺ reabsorption, and activating vitamin D (gut absorption).', 1020, 'Physiology'),
('What is the pulmonary capillary wedge pressure (PCWP) an estimate of?', 'Left atrial pressure', 'Right atrial pressure', 'Pulmonary artery pressure', 'Aortic pressure', 'Left atrial pressure', 'PCWP is measured by wedging a catheter in a pulmonary artery. With flow stopped, it equilibrates with left atrial pressure — a key measure of left heart function.', 1500, 'Physiology');
INSERT INTO analyticalchemistry (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('What is the pH of a solution with [H⁺] = 1×10⁻⁷ M?', '7', '3', '11', '14', '7', 'pH = -log[H⁺] = -log(10⁻⁷) = 7. This is neutral pH at 25°C (pure water).', 720, 'AnalyticalChemistry'),
('In a titration, what is the equivalence point?', 'The point where moles of titrant exactly equal moles of analyte', 'The point of maximum indicator colour change', 'The midpoint of the titration', 'The point where pH = 7', 'The point where moles of titrant exactly equal moles of analyte', 'At the equivalence point, stoichiometric amounts of acid and base have reacted completely. The endpoint (indicator colour change) approximates this.', 750, 'AnalyticalChemistry'),
('What does Beer-Lambert law relate?', 'Absorbance to concentration and path length (A = εlc)', 'Wavelength to photon energy', 'pH to concentration', 'Refractive index to concentration', 'Absorbance to concentration and path length (A = εlc)', 'A = εlc where ε = molar absorptivity, l = path length (cm), c = concentration (mol/L). Basis of spectrophotometry.', 850, 'AnalyticalChemistry'),
('What is the stationary phase in gas chromatography (GC)?', 'A non-volatile liquid coating inside the column', 'The carrier gas', 'The sample injected', 'The detector', 'A non-volatile liquid coating inside the column', 'In GC, the stationary phase is a high-boiling liquid coated on the column. The mobile phase is an inert carrier gas (He, N₂). Separation is by volatility/polarity.', 920, 'AnalyticalChemistry'),
('What does a mass spectrometer measure?', 'The mass-to-charge ratio (m/z) of ions', 'Absorbance at UV wavelengths', 'The pKa of a compound', 'Electrochemical potential', 'The mass-to-charge ratio (m/z) of ions', 'Mass spec ionises molecules, separates ions by m/z, and detects them. The molecular ion peak gives molecular weight; fragmentation pattern gives structure.', 1050, 'AnalyticalChemistry'),
('In ¹H NMR spectroscopy, what does chemical shift (δ) indicate?', 'The electronic environment of a proton', 'The number of protons', 'Coupling between protons', 'The molecular weight', 'The electronic environment of a proton', 'Chemical shift reflects electron density around a proton. Deshielded protons (near electronegative groups) have higher δ (downfield). Referenced to TMS at 0 ppm.', 1150, 'AnalyticalChemistry'),
('What is the principle behind inductively coupled plasma mass spectrometry (ICP-MS)?', 'Sample is atomised in argon plasma, ions are separated by m/z for elemental analysis', 'Sample absorbs UV light proportional to concentration', 'Sample reacts with reagents to produce coloured product', 'Ions migrate in an electric field based on size', 'Sample is atomised in argon plasma, ions are separated by m/z for elemental analysis', 'ICP-MS: plasma (6000-8000K) atomises and ionises the sample. Ions enter the mass spectrometer and are detected by m/z. Detects elements at parts-per-trillion levels.', 1400, 'AnalyticalChemistry'),
('What is Karl Fischer titration used to measure?', 'Water content in a sample', 'Acid content', 'Metal ion concentration', 'Dissolved oxygen', 'Water content in a sample', 'Karl Fischer titration specifically measures water content. It uses iodine, SO₂, pyridine (or imidazole), and methanol. The reaction stoichiometrically consumes water.', 1200, 'AnalyticalChemistry'),
('What is a buffer solution?', 'A solution that resists pH change when acid or base is added', 'A solution of known pH', 'A neutral (pH 7) solution', 'A saturated salt solution', 'A solution that resists pH change when acid or base is added', 'A buffer contains a weak acid and its conjugate base (or weak base/conjugate acid). It works best when pH ≈ pKa (Henderson-Hasselbalch equation).', 820, 'AnalyticalChemistry'),
('What is the detection limit in analytical chemistry?', 'The lowest concentration reliably distinguished from blank signal', 'The highest concentration measurable', 'The concentration giving 100% recovery', 'The precision of repeated measurements', 'The lowest concentration reliably distinguished from blank signal', 'LOD = 3σ/slope of calibration, where σ is the standard deviation of blank measurements. The limit of quantification (LOQ) is typically 10σ/slope.', 1300, 'AnalyticalChemistry');
INSERT INTO biochemistry (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('What type of bond links amino acids in a protein?', 'Peptide bond', 'Hydrogen bond', 'Ionic bond', 'Disulfide bond', 'Peptide bond', 'A peptide bond forms between the carboxyl group of one amino acid and the amino group of the next, releasing water (condensation reaction).', 720, 'Biochemistry'),
('What is the first step of glycolysis?', 'Phosphorylation of glucose to glucose-6-phosphate', 'Conversion of pyruvate to acetyl-CoA', 'Production of NADH', 'Cleavage of fructose-1,6-bisphosphate', 'Phosphorylation of glucose to glucose-6-phosphate', 'Hexokinase phosphorylates glucose using ATP → glucose-6-phosphate. This traps glucose in the cell (can''t cross membrane) and commits it to glycolysis.', 780, 'Biochemistry'),
('What is the net ATP yield from one glucose molecule in glycolysis?', '2 ATP', '36 ATP', '4 ATP', '1 ATP', '2 ATP', 'Glycolysis produces 4 ATP but uses 2, giving a net of 2 ATP per glucose. It also produces 2 NADH and 2 pyruvate.', 780, 'Biochemistry'),
('What is the role of coenzyme A (CoA) in metabolism?', 'It carries acyl groups (like acetyl) to metabolic reactions', 'It transfers phosphate groups', 'It donates electrons in the electron transport chain', 'It catalyses oxidation reactions directly', 'It carries acyl groups (like acetyl) to metabolic reactions', 'CoA has a thiol (-SH) group that forms a high-energy thioester bond with acetyl groups. Acetyl-CoA enters the Krebs cycle and is key for fatty acid metabolism.', 920, 'Biochemistry'),
('What is the Michaelis constant (Km) a measure of?', 'The substrate concentration at which reaction rate is half-maximal', 'Maximum reaction velocity', 'Enzyme concentration', 'Product inhibition strength', 'The substrate concentration at which reaction rate is half-maximal', 'Km = [S] when V = Vmax/2. Low Km = high enzyme affinity for substrate. Derived from the Michaelis-Menten equation: V = Vmax[S]/(Km + [S]).', 1050, 'Biochemistry'),
('Where does the electron transport chain occur in eukaryotic cells?', 'Inner mitochondrial membrane', 'Outer mitochondrial membrane', 'Cytoplasm', 'Nucleus', 'Inner mitochondrial membrane', 'Complexes I-IV are embedded in the inner mitochondrial membrane. They use NADH/FADH₂ from the Krebs cycle to pump protons, driving ATP synthase.', 980, 'Biochemistry'),
('What is the function of ubiquitin?', 'It tags proteins for proteasomal degradation', 'It activates transcription', 'It transports oxygen', 'It catalyses ATP hydrolysis', 'It tags proteins for proteasomal degradation', 'Ubiquitin is a small protein that is covalently attached to target proteins. Polyubiquitination signals the 26S proteasome to degrade the protein.', 1150, 'Biochemistry'),
('What is feedback inhibition?', 'A metabolic pathway''s end product inhibits an early enzyme in the pathway', 'Substrate inhibits its own enzyme', 'Product activates its biosynthetic enzyme', 'A hormone inhibits cellular metabolism', 'A metabolic pathway''s end product inhibits an early enzyme in the pathway', 'Classic example: isoleucine inhibits threonine deaminase (first enzyme in its synthesis). This prevents overproduction — an elegant regulatory mechanism.', 1020, 'Biochemistry'),
('What is the primary structure of a protein?', 'The amino acid sequence', 'Alpha helices and beta sheets', 'The 3D folded shape', 'Quaternary assembly of subunits', 'The amino acid sequence', 'The four levels: primary (sequence), secondary (local folding: helices/sheets), tertiary (overall 3D fold), quaternary (multi-subunit assembly).', 750, 'Biochemistry'),
('What role does FAD play in the Krebs cycle?', 'It accepts electrons (is reduced to FADH₂) in the succinate dehydrogenase reaction', 'It donates electrons to NAD⁺', 'It transfers acetyl groups', 'It hydrolyses GTP', 'It accepts electrons (is reduced to FADH₂) in the succinate dehydrogenase reaction', 'Succinate dehydrogenase converts succinate → fumarate and reduces FAD to FADH₂. FADH₂ then donates electrons to Complex II of the electron transport chain.', 1200, 'Biochemistry');
INSERT INTO inorganicchemistry (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('In the periodic table, which group contains the alkali metals?', 'Group 1', 'Group 2', 'Group 17', 'Group 18', 'Group 1', 'Group 1 alkali metals (Li, Na, K, Rb, Cs, Fr) have 1 valence electron, are highly reactive, and readily form +1 ions.', 710, 'InorganicChemistry'),
('What is the oxidation state of oxygen in H₂O?', '-2', '+2', '0', '-1', '-2', 'In most compounds, oxygen has an oxidation state of -2. Exceptions: peroxides (-1), superoxides (-1/2), and OF₂ (+2).', 740, 'InorganicChemistry'),
('What is a coordination compound?', 'A compound with a central metal ion bonded to ligands', 'A compound containing only ionic bonds', 'A covalent compound with no metal', 'A compound formed under high pressure', 'A compound with a central metal ion bonded to ligands', 'Coordination compounds have a metal centre (often transition metal) surrounded by ligands (Lewis bases donating electron pairs). Example: [Fe(CN)₆]³⁻.', 850, 'InorganicChemistry'),
('What does Crystal Field Theory explain?', 'The splitting of d-orbital energies in metal complexes due to ligand interactions', 'The bonding in ionic crystals', 'The arrangement of atoms in a unit cell', 'The energy of atomic orbitals', 'The splitting of d-orbital energies in metal complexes due to ligand interactions', 'CFT: ligands create an electric field that splits d-orbitals into sets. The splitting energy (Δ) determines whether complexes are high-spin or low-spin.', 1050, 'InorganicChemistry'),
('What is a chelate?', 'A ligand that binds to a metal through two or more donor atoms', 'A metal with multiple oxidation states', 'An inorganic polymer', 'A high-spin complex', 'A ligand that binds to a metal through two or more donor atoms', 'Chelating ligands (e.g. EDTA, en) form rings with the metal. The chelate effect makes them thermodynamically more stable than monodentate analogues.', 1000, 'InorganicChemistry'),
('Which law describes the relationship between oxidation and reduction in electrochemistry?', 'Faraday''s law of electrolysis', 'Hess''s law', 'Le Chatelier''s principle', 'Raoult''s law', 'Faraday''s law of electrolysis', 'Faraday''s law: mass deposited = (M × I × t)/(n × F). F = 96485 C/mol. Relates charge passed to moles of substance oxidised/reduced.', 1100, 'InorganicChemistry'),
('What is the trans effect in square planar complexes?', 'A trans ligand directs substitution to occur at the position opposite it', 'Two ligands on the same side have stronger bonds', 'Trans isomers are more stable', 'A ligand stabilises the opposite ligand', 'A trans ligand directs substitution to occur at the position opposite it', 'The trans effect: strong trans-directing ligands (CO, CN⁻, H⁻) labilise ligands opposite to them. Used in synthesis to control isomer formation (e.g. cisplatin synthesis).', 1350, 'InorganicChemistry'),
('What characterises a superacid?', 'An acid stronger than 100% sulfuric acid (H₀ < -12)', 'An acid with pKa below zero', 'A polyprotic acid', 'An acid that fully dissociates in water', 'An acid stronger than 100% sulfuric acid (H₀ < -12)', 'Superacids (e.g. fluoroantimonic acid H₂F⁺SbF₆⁻) have Hammett acidity function H₀ < -12. They can protonate nearly any molecule, including weak bases.', 1500, 'InorganicChemistry'),
('What is the Born-Haber cycle used for?', 'Calculating lattice energies of ionic compounds', 'Predicting reaction rates', 'Determining molecular geometry', 'Calculating bond dissociation energies', 'Calculating lattice energies of ionic compounds', 'The Born-Haber cycle applies Hess''s law to ionic compound formation, allowing calculation of lattice energy (which can''t be measured directly) from measurable quantities.', 1200, 'InorganicChemistry'),
('In which hybridisation state is the central atom of a tetrahedral molecule?', 'sp³', 'sp²', 'sp', 'dsp²', 'sp³', 'sp³ hybridisation: one s and three p orbitals mix to give four equivalent hybrid orbitals pointing to tetrahedral corners (109.5°). Example: CH₄, NH₃.', 800, 'InorganicChemistry');
INSERT INTO organicchemistry (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('What functional group is present in an aldehyde?', '-CHO (carbonyl at the end of a chain)', '-COOH', '-OH', '-NH₂', '-CHO (carbonyl at the end of a chain)', 'Aldehydes have a carbonyl group (C=O) at the terminal carbon (R-CHO). Ketones have the carbonyl in the middle (R-CO-R).', 720, 'OrganicChemistry'),
('What type of isomers have the same molecular formula but different connectivity?', 'Constitutional isomers', 'Enantiomers', 'Diastereomers', 'Conformational isomers', 'Constitutional isomers', 'Constitutional (structural) isomers differ in how atoms are connected. Stereoisomers have the same connectivity but different spatial arrangement.', 740, 'OrganicChemistry'),
('In an SN2 reaction, what happens to the stereochemistry at the carbon?', 'Inversion (Walden inversion)', 'Retention of configuration', 'Racemisation', 'No change', 'Inversion (Walden inversion)', 'SN2: the nucleophile attacks from the back of the leaving group. The configuration at the chiral centre inverts — like an umbrella flipping in the wind.', 880, 'OrganicChemistry'),
('Which reagent converts a primary alcohol to an aldehyde (not overoxidised to acid)?', 'PCC (pyridinium chlorochromate)', 'KMnO₄', 'K₂Cr₂O₇', 'LiAlH₄', 'PCC (pyridinium chlorochromate)', 'PCC in CH₂Cl₂ oxidises primary alcohols to aldehydes and stops there. KMnO₄ and K₂Cr₂O₇ continue to carboxylic acids.', 950, 'OrganicChemistry'),
('What is Markovnikov''s rule?', 'In addition to an alkene, H adds to the carbon with more H atoms already attached', 'Elimination occurs at the more substituted carbon', 'Reactions prefer the less stable carbocation', 'Addition occurs anti to the bulky group', 'In addition to an alkene, H adds to the carbon with more H atoms already attached', 'Markovnikov''s rule: H+ adds to the less substituted carbon, forming the more stable (more substituted) carbocation. Product: H on the C with more H''s.', 900, 'OrganicChemistry'),
('In electrophilic aromatic substitution, which group is ortho/para directing and activating?', '-OH (hydroxyl)', '-NO₂ (nitro)', '-COOH (carboxyl)', '-CF₃ (trifluoromethyl)', '-OH (hydroxyl)', 'Electron-donating groups (OH, NH₂, OR) activate the ring and direct to ortho/para positions. Electron-withdrawing groups (NO₂, COOH) deactivate and direct to meta.', 1000, 'OrganicChemistry'),
('What is the product of ozonolysis of 2-butene (CH₃CH=CHCH₃) followed by reductive workup?', 'Two molecules of acetaldehyde (CH₃CHO)', 'Butanone and formaldehyde', 'Butanoic acid', 'Two molecules of acetic acid', 'Two molecules of acetaldehyde (CH₃CHO)', 'Ozonolysis cleaves double bonds. 2-Butene (CH₃CH=CHCH₃) gives two CH₃CHO (acetaldehyde) molecules with reductive workup (Zn/H₂O or DMS).', 1100, 'OrganicChemistry'),
('What is a Diels-Alder reaction?', 'A [4+2] cycloaddition between a diene and a dienophile', 'An SN1 reaction of dienes', 'A 1,2-elimination', 'A nucleophilic addition to a ketone', 'A [4+2] cycloaddition between a diene and a dienophile', 'Diels-Alder is a concerted [4+2] pericyclic reaction. A conjugated diene (4π) reacts with a dienophile (2π) to form a cyclohexene. Stereospecific: syn addition.', 1250, 'OrganicChemistry'),
('What determines the R/S designation of a chiral centre?', 'Priority of substituents by atomic number (CIP rules), then direction of decreasing priority', 'Whether the molecule rotates plane-polarised light right or left', 'The number of substituents', 'Whether the isomer is more stable', 'Priority of substituents by atomic number (CIP rules), then direction of decreasing priority', 'CIP rules: assign priority 1-4 by atomic number. With lowest priority pointing away, if 1→2→3 is clockwise = R; anticlockwise = S. Independent of optical rotation.', 1150, 'OrganicChemistry'),
('What is retrosynthesis?', 'Working backwards from target molecule to simpler precursors', 'Synthesising a molecule in reverse conditions', 'Hydrolysing complex molecules', 'Analysing spectral data to identify structures', 'Working backwards from target molecule to simpler precursors', 'Retrosynthetic analysis (Corey): disconnect bonds in the target to reveal synthons, then find real reagents. The arrow (⇒) means "can be made from". Key skill in synthetic planning.', 1400, 'OrganicChemistry');
INSERT INTO astrophysics (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('What is the closest star to Earth (other than the Sun)?', 'Proxima Centauri', 'Alpha Centauri A', 'Barnard''s Star', 'Sirius', 'Proxima Centauri', 'Proxima Centauri is ~4.24 light-years away. It is a red dwarf and part of the Alpha Centauri triple star system.', 710, 'Astrophysics'),
('What type of star is our Sun?', 'G-type main-sequence star (yellow dwarf)', 'Red giant', 'White dwarf', 'Neutron star', 'G-type main-sequence star (yellow dwarf)', 'The Sun is a G2V star: spectral type G, luminosity class V (main sequence). Surface temperature ~5778K. It will become a red giant in ~5 billion years.', 720, 'Astrophysics'),
('What does Hubble''s law state?', 'Galaxies recede from us at a speed proportional to their distance', 'All galaxies are moving toward a central point', 'The universe is static', 'Stars move in proportion to their mass', 'Galaxies recede from us at a speed proportional to their distance', 'v = H₀ × d, where H₀ ≈ 70 km/s/Mpc. This is evidence for the expanding universe and the Big Bang.', 820, 'Astrophysics'),
('What is a pulsar?', 'A rapidly rotating neutron star emitting beams of electromagnetic radiation', 'An exploding white dwarf', 'A type of variable star', 'A black hole emitting jets', 'A rapidly rotating neutron star emitting beams of electromagnetic radiation', 'Pulsars are neutron stars with strong magnetic fields. They emit beams from their magnetic poles; as they rotate, we detect regular pulses (like a lighthouse).', 950, 'Astrophysics'),
('What is the Chandrasekhar limit?', 'The maximum mass (~1.4 M☉) of a stable white dwarf', 'The minimum mass for a star to fuse hydrogen', 'The radius of a neutron star', 'The luminosity at which radiation pressure exceeds gravity', 'The maximum mass (~1.4 M☉) of a stable white dwarf', 'Above ~1.4 solar masses, electron degeneracy pressure cannot support a white dwarf against gravity. It will collapse to a neutron star or explode as a Type Ia supernova.', 1150, 'Astrophysics'),
('What observational evidence supports the existence of dark matter?', 'Flat galaxy rotation curves inconsistent with visible mass', 'Galaxies rotating too slowly', 'The cosmic microwave background', 'Type Ia supernova brightness', 'Flat galaxy rotation curves inconsistent with visible mass', 'Stars at the outer edge of galaxies orbit as fast as inner stars. Newtonian gravity predicts slower speeds without extra unseen mass. Dark matter explains this flat rotation curve.', 1250, 'Astrophysics'),
('What are gravitational waves?', 'Ripples in spacetime caused by accelerating massive objects', 'Electromagnetic radiation from pulsars', 'Sound waves in the interstellar medium', 'Waves caused by stellar magnetic fields', 'Ripples in spacetime caused by accelerating massive objects', 'Predicted by Einstein''s GR (1916), first directly detected by LIGO in 2015 from a binary black hole merger. They stretch and compress spacetime as they pass.', 1300, 'Astrophysics'),
('What is the cosmic microwave background (CMB)?', 'Thermal radiation from 380,000 years after the Big Bang, now at ~2.7K', 'Radiation emitted by the Milky Way''s centre', 'Radiation from quasars', 'X-ray radiation from galaxy clusters', 'Thermal radiation from 380,000 years after the Big Bang, now at ~2.7K', 'The CMB was released when the universe cooled enough for protons and electrons to combine (recombination). Detected by Penzias & Wilson (1965), confirming the Big Bang.', 1200, 'Astrophysics'),
('What is the Schwarzschild radius?', 'The radius within which an object becomes a black hole (event horizon)', 'The radius at which a star ignites fusion', 'The radius of the photon sphere', 'The orbital radius of the innermost stable orbit', 'The radius within which an object becomes a black hole (event horizon)', 'r_s = 2GM/c². For the Sun: ~3 km. If the Sun were compressed to this radius, it would form a black hole. Nothing inside r_s can escape.', 1400, 'Astrophysics'),
('What powers a quasar?', 'Accretion of matter onto a supermassive black hole', 'Fusion of elements heavier than iron', 'Rapid stellar formation', 'Collision of two neutron stars', 'Accretion of matter onto a supermassive black hole', 'Quasars are the most luminous objects in the universe, powered by matter falling into supermassive black holes (10⁸-10¹⁰ M☉). The accretion disc emits enormous energy.', 1350, 'Astrophysics');
INSERT INTO electromagnetics (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('What is Ohm''s law?', 'V = IR (voltage = current × resistance)', 'P = IV', 'I = V²/R', 'V = I/R', 'V = IR (voltage = current × resistance)', 'Ohm''s law: V=IR. A voltage of 10V across a 5Ω resistor produces 2A of current. Applies to ohmic (linear) conductors.', 710, 'Electromagnetics'),
('What is Coulomb''s law?', 'The force between two charges is proportional to the product of charges and inversely proportional to r²', 'Force is proportional to the sum of charges', 'Force is proportional to distance', 'Charges attract regardless of sign', 'The force between two charges is proportional to the product of charges and inversely proportional to r²', 'F = kq₁q₂/r², where k = 8.99×10⁹ N·m²/C². Like charges repel, unlike attract. Analogous to Newton''s law of gravitation.', 730, 'Electromagnetics'),
('What does Faraday''s law of electromagnetic induction state?', 'EMF is induced equal to the rate of change of magnetic flux', 'A current-carrying conductor experiences a force in a magnetic field', 'Moving charges produce magnetic fields', 'Electric fields are created by stationary charges', 'EMF is induced equal to the rate of change of magnetic flux', 'ε = -dΦ/dt. A changing magnetic flux through a loop induces an EMF. The negative sign (Lenz''s law) means the induced current opposes the change.', 850, 'Electromagnetics'),
('What are Maxwell''s equations?', 'Four equations describing how electric and magnetic fields are generated and interact', 'Equations governing quantum electrodynamics', 'Laws of thermodynamics in electromagnetic form', 'Equations for electromagnetic wave speed in media', 'Four equations describing how electric and magnetic fields are generated and interact', 'Maxwell''s 4 equations: Gauss''s law (E), Gauss''s law (B), Faraday''s law, Ampere-Maxwell law. Together they predict electromagnetic waves travelling at c.', 980, 'Electromagnetics'),
('What is the skin effect?', 'At high frequencies, current flows mainly near the conductor surface', 'Conductors heat up at high voltages', 'Resistance decreases with increasing frequency', 'Magnetic fields penetrate deeper at high frequencies', 'At high frequencies, current flows mainly near the conductor surface', 'Skin depth δ = √(2ρ/ωμ). At high frequencies, current is confined to a thin surface layer. This increases effective resistance and is why HF cables use stranded wire.', 1150, 'Electromagnetics'),
('What is a standing wave ratio (SWR) of 1 in a transmission line?', 'Perfect impedance matching — no reflections', 'Maximum reflection', 'Total mismatch', 'Half power reflection', 'Perfect impedance matching — no reflections', 'SWR = (1+|Γ|)/(1-|Γ|) where Γ is reflection coefficient. SWR=1 means Γ=0 (no reflection, all power delivered). SWR>1 means some power is reflected back.', 1250, 'Electromagnetics'),
('What is the Biot-Savart law used to calculate?', 'Magnetic field produced by a current-carrying conductor', 'Electric field from a charge distribution', 'EMF induced by a changing flux', 'Force on a charge in a field', 'Magnetic field produced by a current-carrying conductor', 'dB = (μ₀/4π)(I dl × r̂)/r². Integrating over a conductor gives the total B field. Analogous to Coulomb''s law but for magnetic fields from currents.', 1050, 'Electromagnetics'),
('What is a waveguide?', 'A structure that guides electromagnetic waves along a path with low loss', 'A device that amplifies radio waves', 'An antenna that radiates in all directions', 'A passive filter circuit', 'A structure that guides electromagnetic waves along a path with low loss', 'Waveguides are hollow metal tubes (rectangular or circular) that confine EM waves by total internal reflection. They have a cutoff frequency below which propagation is impossible.', 1300, 'Electromagnetics'),
('What is the relationship between electric field E and electric potential V?', 'E = -∇V (E is the negative gradient of V)', 'V = -∇E', 'E = ∇²V', 'V = ∇ × E', 'E = -∇V (E is the negative gradient of V)', 'Electric field is the negative gradient of potential: E = -∇V. This means E points in the direction of decreasing potential, from high to low V.', 950, 'Electromagnetics'),
('What is antenna gain?', 'The ratio of an antenna''s radiation intensity in a direction to an isotropic radiator', 'The amplification provided by an amplifier connected to an antenna', 'The total radiated power', 'The bandwidth of the antenna', 'The ratio of an antenna''s radiation intensity in a direction to an isotropic radiator', 'Antenna gain G = 4πU(θ,φ)/P_total vs. isotropic. A high-gain antenna focuses radiation in a specific direction (directivity × efficiency). Measured in dBi.', 1400, 'Electromagnetics');
INSERT INTO quantummechanics (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('What does the Heisenberg uncertainty principle state?', 'Position and momentum cannot both be precisely known simultaneously', 'Energy and time are always conserved', 'A particle cannot have zero energy', 'Quantum states collapse upon measurement', 'Position and momentum cannot both be precisely known simultaneously', 'ΔxΔp ≥ ℏ/2. This is not a measurement limitation but a fundamental property of quantum systems. Precise position means completely uncertain momentum and vice versa.', 730, 'QuantumMechanics'),
('What is wave-particle duality?', 'Quantum objects exhibit both wave and particle properties depending on observation', 'Waves can carry particles', 'Particles create waves when moving', 'Light is purely a wave', 'Quantum objects exhibit both wave and particle properties depending on observation', 'Demonstrated by the double-slit experiment: electrons create interference patterns (wave) but are detected as discrete hits (particle). De Broglie: λ = h/p.', 750, 'QuantumMechanics'),
('What is the physical meaning of |ψ|² in quantum mechanics?', 'The probability density of finding a particle at a given location', 'The energy of the particle', 'The momentum of the particle', 'The wavelength of the particle', 'The probability density of finding a particle at a given location', 'The Born interpretation: |ψ(x)|² gives the probability density. The probability of finding a particle between x and x+dx is |ψ(x)|²dx. The wave function must be normalised.', 850, 'QuantumMechanics'),
('What are the quantum numbers describing an electron in an atom?', 'n (principal), l (angular momentum), mₗ (magnetic), mₛ (spin)', 'n, m, s, p', 'Energy, momentum, spin, charge', 'x, y, z, spin', 'n (principal), l (angular momentum), mₗ (magnetic), mₛ (spin)', 'n=1,2,3... (shell), l=0 to n-1 (subshell: s,p,d,f), mₗ=-l to +l (orbital orientation), mₛ=±½ (spin). No two electrons can share all four (Pauli exclusion).', 880, 'QuantumMechanics'),
('What does the Pauli exclusion principle state?', 'No two fermions can occupy the same quantum state simultaneously', 'Particles cannot exceed the speed of light', 'Energy is conserved in quantum systems', 'Observable quantities come in discrete values', 'No two fermions can occupy the same quantum state simultaneously', 'Electrons (fermions, spin-½) cannot share all four quantum numbers. This gives atoms their structure and explains the periodic table and matter''s solidity.', 920, 'QuantumMechanics'),
('What is quantum tunnelling?', 'A particle penetrating through a potential energy barrier classically forbidden', 'Particles jumping between energy levels', 'A particle''s spin flipping', 'Quantum particles moving faster than light', 'A particle penetrating through a potential energy barrier classically forbidden', 'Tunnelling probability ∝ e^(-2κd) where κ = √(2m(V-E))/ℏ. Explains alpha decay, STM, and tunnel diodes. The particle has no classical path through the barrier.', 1100, 'QuantumMechanics'),
('What is quantum entanglement?', 'Two particles sharing a quantum state such that measuring one instantly determines the other', 'Two particles occupying the same position', 'A particle splitting into two', 'Particles attracting each other at a quantum level', 'Two particles sharing a quantum state such that measuring one instantly determines the other', 'Entangled particles have correlated states regardless of separation. Measuring one collapses the joint state. Einstein called it "spooky action at a distance." Confirmed by Bell test experiments.', 1200, 'QuantumMechanics'),
('What does the time-independent Schrödinger equation describe?', 'Stationary states (energy eigenstates) of a quantum system', 'Time evolution of all quantum systems', 'Relativistic quantum mechanics', 'The collapse of the wave function', 'Stationary states (energy eigenstates) of a quantum system', 'Ĥψ = Eψ. Solving this gives the allowed energy levels and wave functions. For the hydrogen atom, it yields the orbital structure and energy levels Eₙ = -13.6/n² eV.', 1150, 'QuantumMechanics'),
('What is the significance of Bell''s theorem?', 'No local hidden variable theory can reproduce all quantum mechanical predictions', 'Quantum mechanics is incomplete', 'Particles have definite properties before measurement', 'Quantum mechanics is equivalent to classical mechanics at large scales', 'No local hidden variable theory can reproduce all quantum mechanical predictions', 'Bell (1964) showed quantum correlations violate inequalities that any local hidden variable theory must satisfy. Experimental violations confirm: quantum mechanics is fundamentally non-local.', 1550, 'QuantumMechanics'),
('In the harmonic oscillator, what is the ground state energy?', 'ℏω/2 (the zero-point energy)', '0', 'ℏω', '2ℏω', 'ℏω/2 (the zero-point energy)', 'The quantum harmonic oscillator has energy levels Eₙ = (n+½)ℏω. The ground state (n=0) has E₀ = ℏω/2 ≠ 0. This zero-point energy is a direct consequence of the uncertainty principle.', 1300, 'QuantumMechanics');
INSERT INTO thermodynamics (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('What does the zeroth law of thermodynamics state?', 'If A is in thermal equilibrium with B and B with C, then A is in equilibrium with C', 'Energy is conserved in all processes', 'Entropy of the universe always increases', 'Absolute zero is unattainable', 'If A is in thermal equilibrium with B and B with C, then A is in equilibrium with C', 'The zeroth law defines thermal equilibrium and temperature. It is the basis for thermometers — a thermometer in equilibrium with an object reads the object''s temperature.', 720, 'Thermodynamics'),
('What is the first law of thermodynamics?', 'The total energy of an isolated system is conserved (ΔU = Q - W)', 'Entropy always increases', 'Heat flows from cold to hot spontaneously', 'Absolute zero cannot be reached', 'The total energy of an isolated system is conserved (ΔU = Q - W)', 'ΔU = Q - W: the change in internal energy equals heat added to the system minus work done by the system. This is conservation of energy for thermodynamic systems.', 720, 'Thermodynamics'),
('What is entropy a measure of?', 'The number of microscopic states consistent with a macroscopic state (disorder)', 'The total energy of a system', 'The temperature of a system', 'The heat capacity of a substance', 'The number of microscopic states consistent with a macroscopic state (disorder)', 'S = k_B ln(Ω) where Ω is the number of microstates (Boltzmann). Systems evolve toward maximum entropy (most probable macrostate). ΔS_universe ≥ 0 for all real processes.', 880, 'Thermodynamics'),
('What is the efficiency of an ideal Carnot engine?', 'η = 1 - T_cold/T_hot', 'η = T_hot/T_cold', 'η = 1 - Q_cold/Q_hot', 'η = W/Q_cold', 'η = 1 - T_cold/T_hot', 'Carnot efficiency depends only on the temperatures of the hot and cold reservoirs. No engine operating between two temperatures can be more efficient than a Carnot engine.', 950, 'Thermodynamics'),
('What is the Gibbs free energy (G) used to predict?', 'Spontaneity of a process at constant T and P', 'The rate of a reaction', 'The activation energy', 'The enthalpy of a reaction', 'Spontaneity of a process at constant T and P', 'ΔG = ΔH - TΔS. If ΔG < 0: spontaneous. ΔG > 0: non-spontaneous. ΔG = 0: equilibrium. The most useful criterion for spontaneity in chemistry/biology.', 980, 'Thermodynamics'),
('What does the equipartition theorem state?', 'Each degree of freedom contributes ½k_BT to the average energy', 'All molecules have equal energy at equilibrium', 'Energy is distributed equally among all particles', 'Temperature determines only kinetic energy', 'Each degree of freedom contributes ½k_BT to the average energy', 'Equipartition: each quadratic degree of freedom (translational, rotational, vibrational) gets ½k_BT energy on average. For monatomic ideal gas: 3 DOF → U = 3/2 nRT.', 1100, 'Thermodynamics'),
('What is a phase transition?', 'A change of state (e.g. liquid to gas) at a characteristic temperature and pressure', 'A change in chemical composition', 'A change in the number of molecules', 'A reversible temperature change', 'A change of state (e.g. liquid to gas) at a characteristic temperature and pressure', 'Phase transitions (melting, boiling, sublimation) occur when ΔG = 0 between phases. First-order transitions have latent heat; second-order (e.g. ferromagnetic) do not.', 1050, 'Thermodynamics'),
('What is the Maxwell-Boltzmann distribution?', 'The distribution of molecular speeds in an ideal gas', 'The energy distribution of photons', 'The distribution of electrons in metals', 'The distribution of pressures in a gas', 'The distribution of molecular speeds in an ideal gas', 'The MB distribution gives the probability of a molecule having a given speed at temperature T. It has a characteristic peak (most probable speed) that shifts right with increasing T.', 1150, 'Thermodynamics'),
('What does the Clausius-Clapeyron equation describe?', 'How vapour pressure changes with temperature along a phase boundary', 'The efficiency of heat engines', 'The relationship between pressure and volume', 'The rate of evaporation', 'How vapour pressure changes with temperature along a phase boundary', 'dP/dT = L/(TΔV). For liquid-vapour: ln(P₂/P₁) = -(ΔH_vap/R)(1/T₂ - 1/T₁). Used to find boiling points at different pressures.', 1250, 'Thermodynamics'),
('In statistical mechanics, what is the partition function Z?', 'The sum over all states of e^(-E/k_BT), linking microscopic states to thermodynamic properties', 'The number of accessible microstates', 'The total energy divided by k_BT', 'The number of particles in a system', 'The sum over all states of e^(-E/k_BT), linking microscopic states to thermodynamic properties', 'Z = Σ e^(-βEᵢ) where β=1/k_BT. All thermodynamic quantities follow: F=-k_BT ln Z, U=-∂ln Z/∂β, S=k_B(ln Z + βU). Z is the bridge between QM and thermodynamics.', 1500, 'Thermodynamics');
INSERT INTO calculus (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('What is the limit of (x^2 - 4)/(x - 2) as x approaches 2?', '4', '2', '0', 'undefined', '4', 'Factor the numerator: (x^2 - 4) = (x-2)(x+2), cancel (x-2), giving x+2; at x=2 this equals 4.', 710, 'Calculus'),
('Which rule states d/dx[u*v] = u''*v + u*v''?', 'Product rule', 'Quotient rule', 'Chain rule', 'Power rule', 'Product rule', 'The product rule applies when differentiating a product of two functions: d/dx[u*v] = u''v + uv''.', 720, 'Calculus'),
('What is the derivative of f(x) = sin(x)?', 'cos(x)', '-cos(x)', '-sin(x)', 'tan(x)', 'cos(x)', 'The derivative of sin(x) is cos(x), a fundamental trigonometric differentiation result.', 725, 'Calculus'),
('Evaluate the indefinite integral: integral of x^4 dx', 'x^5/5 + C', 'x^4 + C', '4x^3 + C', 'x^5 + C', 'x^5/5 + C', 'The power rule for integration states integral of x^n dx = x^(n+1)/(n+1) + C; here n=4 gives x^5/5 + C.', 730, 'Calculus'),
('What is lim(x->inf) 1/x?', '0', '1', 'infinity', 'undefined', '0', 'As x grows without bound, 1/x decreases toward 0; the limit is 0.', 715, 'Calculus'),
('What is the derivative of f(x) = cos(x)?', '-sin(x)', 'sin(x)', '-cos(x)', 'tan(x)', '-sin(x)', 'The derivative of cos(x) is -sin(x), a standard result from the definition of the derivative.', 720, 'Calculus'),
('A function f is continuous at x = a if lim(x->a) f(x) equals what?', 'f(a)', '0', 'f''(a)', '1', 'f(a)', 'Continuity at x=a requires that the limit as x approaches a equals the function value f(a).', 740, 'Calculus'),
('Evaluate the definite integral: integral from 0 to 1 of 2x dx', '1', '2', '1/2', '0', '1', 'integral of 2x dx = x^2; evaluating from 0 to 1 gives 1^2 - 0^2 = 1.', 745, 'Calculus'),
('What is the derivative of f(x) = x^n using the power rule?', 'n*x^(n-1)', 'x^(n+1)/(n+1)', '(n-1)*x^n', 'n*x^n', 'n*x^(n-1)', 'The power rule states d/dx[x^n] = n*x^(n-1) for any real n.', 722, 'Calculus'),
('What is the Fundamental Theorem of Calculus Part 2?', 'integral from a to b of f(x) dx = F(b) - F(a)', 'd/dx[integral from a to x of f(t) dt] = f(x)', 'Every continuous function has an antiderivative', 'The derivative and integral are inverses', 'integral from a to b of f(x) dx = F(b) - F(a)', 'FTC Part 2 states that if F is any antiderivative of f, then the definite integral from a to b equals F(b) - F(a).', 820, 'Calculus'),
('Use u-substitution to evaluate integral of 2x*sqrt(x^2 + 1) dx', '(2/3)(x^2+1)^(3/2) + C', '(x^2+1)^(1/2) + C', 'x*(x^2+1)^(1/2) + C', '2*(x^2+1) + C', '(2/3)(x^2+1)^(3/2) + C', 'Let u = x^2+1, du = 2x dx; the integral becomes integral of sqrt(u) du = (2/3)u^(3/2) + C = (2/3)(x^2+1)^(3/2) + C.', 960, 'Calculus'),
('What is d/dx[ln(x)]?', '1/x', 'x', 'e^x', 'ln(x)/x', '1/x', 'The derivative of the natural logarithm is d/dx[ln(x)] = 1/x for x > 0.', 780, 'Calculus'),
('Apply the chain rule: what is d/dx[cos(3x)]?', '-3*sin(3x)', 'sin(3x)', '-sin(3x)', '3*cos(3x)', '-3*sin(3x)', 'Chain rule: d/dx[cos(u)] = -sin(u)*u''; with u=3x, u''=3, giving -sin(3x)*3 = -3*sin(3x).', 840, 'Calculus'),
('Evaluate lim(x->0) (tan x)/x', '1', '0', 'infinity', 'undefined', '1', 'Since tan(x)/x = (sin x/cos x)/x = (sin x/x)*(1/cos x), and both factors approach 1 as x->0, the limit is 1.', 870, 'Calculus'),
('What is the quotient rule: d/dx[u/v]?', '(u''*v - u*v'') / v^2', '(u*v'' - u''*v) / v^2', 'u''*v'' / v', '(u'' - v'') / v', '(u''*v - u*v'') / v^2', 'The quotient rule is d/dx[u/v] = (u''v - uv'')/v^2; remember "low d-high minus high d-low over low squared."', 810, 'Calculus'),
('Find the critical points of f(x) = x^3 - 3x by setting f''(x) = 0. What are they?', 'x = 1 and x = -1', 'x = 0 and x = 3', 'x = sqrt(3) and x = -sqrt(3)', 'x = 3 only', 'x = 1 and x = -1', 'f''(x) = 3x^2 - 3 = 0 gives x^2 = 1, so x = 1 and x = -1 are the critical points.', 890, 'Calculus'),
('What does the second derivative test conclude when f''(c) = 0 and f''''(c) > 0?', 'f has a local minimum at c', 'f has a local maximum at c', 'f has an inflection point at c', 'The test is inconclusive', 'f has a local minimum at c', 'If f''(c) = 0 and f''''(c) > 0, the function is concave up at c, so f has a local minimum there.', 920, 'Calculus'),
('Evaluate lim(x->0) (e^x - 1)/x using L''Hopital''s rule', '1', '0', 'e', 'infinity', '1', 'Both numerator and denominator approach 0; applying L''Hopital''s rule, differentiate both: e^x / 1 -> 1 as x->0.', 950, 'Calculus'),
('What is the Fundamental Theorem of Calculus Part 1?', 'd/dx[integral from a to x of f(t) dt] = f(x)', 'integral from a to b of f(x) dx = F(b) - F(a)', 'f is differentiable implies f is integrable', 'The derivative of a constant is zero', 'd/dx[integral from a to x of f(t) dt] = f(x)', 'FTC Part 1 says differentiating the accumulation function returns the integrand: d/dx[integral_a^x f(t)dt] = f(x).', 860, 'Calculus'),
('Integrate by parts: integral of x*cos(x) dx', 'x*sin(x) + cos(x) + C', 'x*sin(x) - cos(x) + C', '-x*sin(x) + cos(x) + C', 'sin(x) + C', 'x*sin(x) + cos(x) + C', 'Let u=x, dv=cos(x)dx; then du=dx, v=sin(x); IBP gives x*sin(x) - integral of sin(x) dx = x*sin(x) + cos(x) + C.', 1020, 'Calculus'),
('Which convergence test uses lim(n->inf) |a_(n+1)/a_n| to determine series behavior?', 'Ratio test', 'Comparison test', 'Integral test', 'Root test', 'Ratio test', 'The ratio test evaluates L = lim|a_(n+1)/a_n|; the series converges if L < 1 and diverges if L > 1.', 1080, 'Calculus'),
('What is the Maclaurin series for sin(x)?', 'x - x^3/3! + x^5/5! - x^7/7! + ...', '1 - x^2/2! + x^4/4! - ...', '1 + x + x^2/2! + x^3/3! + ...', 'x + x^3/3! + x^5/5! + ...', 'x - x^3/3! + x^5/5! - x^7/7! + ...', 'The Maclaurin series of sin(x) is sum_(n=0)^inf (-1)^n * x^(2n+1)/(2n+1)! = x - x^3/6 + x^5/120 - ..., converging for all x.', 1150, 'Calculus'),
('Find dy/dx by implicit differentiation given x^2 + y^2 = 25', '-x/y', 'x/y', '-y/x', '2x + 2y', '-x/y', 'Differentiating both sides: 2x + 2y*(dy/dx) = 0, so dy/dx = -2x/(2y) = -x/y.', 980, 'Calculus'),
('A ladder 10 ft long slides down a wall. When the bottom is 6 ft from the wall and moving at 2 ft/s, how fast is the top sliding down?', '3/2 ft/s', '2 ft/s', '8/3 ft/s', '1/2 ft/s', '3/2 ft/s', 'By Pythagorean theorem x^2+y^2=100; differentiating: 2x(dx/dt)+2y(dy/dt)=0; at x=6,y=8: 6*2+8*(dy/dt)=0 so dy/dt = -3/2 ft/s (magnitude 3/2).', 1280, 'Calculus'),
('Evaluate the improper integral: integral from 1 to inf of 1/x^2 dx', '1', 'infinity (diverges)', '2', '1/2', '1', 'integral of x^(-2) dx = -x^(-1); evaluating from 1 to inf: lim(b->inf)[-1/b + 1/1] = 0 + 1 = 1.', 1100, 'Calculus'),
('What is the partial derivative with respect to x of f(x,y) = x^2*y + y^3?', '2x*y', '2x*y + 3y^2', 'x^2 + 3y^2', '2x + y^3', '2x*y', 'Treating y as a constant, d/dx[x^2*y + y^3] = 2x*y + 0 = 2x*y.', 1060, 'Calculus'),
('What is the gradient of f(x,y) = x^2 + y^2?', '(2x, 2y)', '(x^2, y^2)', '(2, 2)', '(x, y)', '(2x, 2y)', 'The gradient is the vector of partial derivatives: grad f = (df/dx, df/dy) = (2x, 2y).', 1090, 'Calculus'),
('Does the series sum_(n=1)^inf 1/n^2 converge or diverge?', 'Converges (p-series, p=2>1)', 'Diverges (harmonic-like)', 'Converges only conditionally', 'Diverges by ratio test', 'Converges (p-series, p=2>1)', 'A p-series sum 1/n^p converges when p > 1; here p=2 > 1, so the series converges (to pi^2/6).', 1040, 'Calculus'),
('What substitution simplifies the integral of 1/(x^2 + a^2) dx?', 'x = a*tan(theta)', 'x = a*sin(theta)', 'x = a*sec(theta)', 'x = a*cos(theta)', 'x = a*tan(theta)', 'The substitution x = a*tan(theta) converts x^2+a^2 into a^2*sec^2(theta), simplifying the integral to (1/a)*arctan(x/a) + C.', 1200, 'Calculus'),
('Use partial fractions to decompose 1/((x-1)(x+2)). What is the result?', '(1/3)/(x-1) - (1/3)/(x+2)', '(1/3)/(x-1) + (1/3)/(x+2)', '1/(x-1) - 1/(x+2)', '(1/2)/(x-1) + (1/2)/(x+2)', '(1/3)/(x-1) - (1/3)/(x+2)', 'Setting 1/((x-1)(x+2)) = A/(x-1) + B/(x+2) and solving gives A=1/3, B=-1/3.', 1180, 'Calculus'),
('Which test compares a series sum a_n to a known series sum b_n of similar magnitude?', 'Comparison test', 'Ratio test', 'Root test', 'Alternating series test', 'Comparison test', 'The direct comparison test concludes convergence or divergence of sum a_n by comparing term-by-term with a known series sum b_n.', 970, 'Calculus'),
('Evaluate the Riemann sum limit that defines the definite integral of f(x) on [a,b]', 'lim(n->inf) sum_(i=1)^n f(x_i)*Delta_x where Delta_x = (b-a)/n', 'F(b) - F(a) where F is any function', 'sum_(i=1)^n f(x_i) as n->inf', 'lim(n->inf) f(n)', 'lim(n->inf) sum_(i=1)^n f(x_i)*Delta_x where Delta_x = (b-a)/n', 'The definite integral is defined as the limit of Riemann sums: lim(n->inf) sum f(x_i)*Delta_x, partitioning [a,b] into n subintervals of width Delta_x=(b-a)/n.', 1010, 'Calculus'),
('Evaluate lim(x->inf) (3x^2 + 2x)/(x^2 - 5) by dividing by the highest power', '3', '2', '0', 'infinity', '3', 'Dividing numerator and denominator by x^2 gives (3 + 2/x)/(1 - 5/x^2); as x->inf the terms with 1/x vanish, leaving 3/1 = 3.', 840, 'Calculus'),
('What is the derivative of f(x) = arctan(x)?', '1/(1 + x^2)', 'sqrt(1 - x^2)', '1/sqrt(1 - x^2)', '1/x', '1/(1 + x^2)', 'The derivative of arctan(x) is 1/(1+x^2), derived using implicit differentiation on tan(y)=x.', 900, 'Calculus'),
('Evaluate: integral of e^(2x) dx', 'e^(2x)/2 + C', '2*e^(2x) + C', 'e^(2x) + C', 'e^x/2 + C', 'e^(2x)/2 + C', 'Using substitution u=2x, du=2dx: integral becomes (1/2)*integral of e^u du = e^(2x)/2 + C.', 780, 'Calculus'),
('Find the absolute maximum of f(x) = -x^2 + 4x on [0,3]', '4', '3', '0', '6', '4', 'f''(x) = -2x+4 = 0 gives x=2; f(2)=4, f(0)=0, f(3)=3; the absolute maximum is 4 at x=2.', 1000, 'Calculus'),
('What is the Maclaurin series for cos(x)?', '1 - x^2/2! + x^4/4! - x^6/6! + ...', 'x - x^3/3! + x^5/5! - ...', '1 + x + x^2/2! + x^3/3! + ...', '1 + x^2/2! + x^4/4! + ...', '1 - x^2/2! + x^4/4! - x^6/6! + ...', 'The Maclaurin series of cos(x) is sum_(n=0)^inf (-1)^n * x^(2n)/(2n)! = 1 - x^2/2 + x^4/24 - ..., converging for all x.', 1140, 'Calculus'),
('Apply L''Hopital''s rule to lim(x->0+) x*ln(x). Rewrite as a fraction, then evaluate.', '0', '1', '-1', 'infinity', '0', 'Rewrite x*ln(x) = ln(x)/(1/x); L''Hopital gives (1/x)/(-1/x^2) = -x -> 0 as x->0+.', 1320, 'Calculus'),
('Does the alternating series sum_(n=1)^inf (-1)^n / n converge?', 'Yes, conditionally', 'Yes, absolutely', 'No, it diverges', 'The test is inconclusive', 'Yes, conditionally', 'By the alternating series test, 1/n decreases to 0, so the series converges; but sum 1/n diverges, so it converges only conditionally.', 1130, 'Calculus'),
('If f(x,y) = e^(x*y), what is the mixed partial derivative f_xy?', 'e^(x*y)*(1 + x*y)', 'x*e^(x*y)', 'y*e^(x*y)', 'e^(x*y)', 'e^(x*y)*(1 + x*y)', 'f_x = y*e^(xy); then f_xy = d/dy[y*e^(xy)] = e^(xy) + y*x*e^(xy) = e^(xy)*(1+xy).', 1460, 'Calculus'),
('What is the radius of convergence of sum_(n=0)^inf x^n/n! (the series for e^x)?', 'infinity', '1', 'e', '0', 'infinity', 'Ratio test: lim|x^(n+1)/(n+1)! / (x^n/n!)| = |x|/(n+1) -> 0 for all x, so the radius of convergence is infinity.', 1220, 'Calculus'),
('Evaluate: integral from 0 to pi of sin(x) dx', '2', '0', '1', 'pi', '2', 'The antiderivative of sin(x) is -cos(x); evaluating from 0 to pi: -cos(pi)-(-cos(0)) = 1+1 = 2.', 760, 'Calculus'),
('What condition on a function f guarantees a global minimum on a closed interval [a,b] by the Extreme Value Theorem?', 'f is continuous on [a,b]', 'f is differentiable on [a,b]', 'f is monotone on [a,b]', 'f(a) < f(b)', 'f is continuous on [a,b]', 'The Extreme Value Theorem guarantees that a continuous function on a closed bounded interval attains both a maximum and a minimum.', 870, 'Calculus'),
('Evaluate: integral of 1/(x^2 - 1) dx using partial fractions', '(1/2)*ln|x-1| - (1/2)*ln|x+1| + C', 'ln|x^2-1| + C', '(1/2)*ln|x+1| - (1/2)*ln|x-1| + C', 'arctan(x) + C', '(1/2)*ln|x-1| - (1/2)*ln|x+1| + C', 'Decompose 1/(x^2-1) = (1/2)/(x-1) - (1/2)/(x+1); integrating term by term gives (1/2)ln|x-1| - (1/2)ln|x+1| + C.', 1250, 'Calculus'),
('A box with a square base and open top must hold 32 cm^3. What base length x minimizes surface area?', 'x = 4 cm', 'x = 2 cm', 'x = 8 cm', 'x = 32 cm', 'x = 4 cm', 'Surface area S = x^2 + 4x*h; constraint x^2*h = 32 gives h = 32/x^2; minimizing: dS/dx = 2x - 128/x^2 = 0 yields x^3 = 64, so x = 4.', 1500, 'Calculus'),
('Does the integral from 1 to inf of 1/x dx converge or diverge?', 'Diverges', 'Converges to 1', 'Converges to ln(2)', 'Converges to 2', 'Diverges', 'integral of 1/x dx = ln(x); as x->inf, ln(x)->inf, so the improper integral diverges (harmonic-type divergence).', 1015, 'Calculus'),
('What is the Taylor series of f(x) = 1/(1-x) centered at 0 (for |x| < 1)?', '1 + x + x^2 + x^3 + ...', '1 - x + x^2 - x^3 + ...', 'x + x^2/2 + x^3/3 + ...', '1 + x + x^2/2! + x^3/3! + ...', '1 + x + x^2 + x^3 + ...', 'The geometric series gives 1/(1-x) = sum_(n=0)^inf x^n = 1 + x + x^2 + x^3 + ... for |x| < 1.', 1070, 'Calculus'),
('Using the ratio test, determine convergence of sum_(n=1)^inf n!/2^n', 'Diverges (L = infinity > 1)', 'Converges (L = 1/2 < 1)', 'Converges (L = 0)', 'Inconclusive (L = 1)', 'Diverges (L = infinity > 1)', 'Ratio: |(n+1)!/2^(n+1)| / |n!/2^n| = (n+1)/2 -> infinity as n->inf; since L > 1, the series diverges.', 1380, 'Calculus'),
('Find the interval of convergence of sum_(n=1)^inf (x-2)^n / n', '[1, 3)', '(1, 3)', '[1, 3]', '(-inf, inf)', '[1, 3)', 'Ratio test gives radius R=1 centered at x=2, so x in (1,3); at x=1 the series sum (-1)^n/n converges; at x=3 sum 1/n diverges; IOC is [1,3).', 1750, 'Calculus'),
('Evaluate lim(x->0+) x^x using logarithms and L''Hopital''s rule', '1', '0', 'e', 'infinity', '1', 'Let L = lim x^x; ln L = lim x*ln(x) = lim ln(x)/(1/x); L''Hopital: (1/x)/(-1/x^2) = -x -> 0; so L = e^0 = 1.', 1800, 'Calculus');
INSERT INTO discretemath (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
INSERT INTO linearalgebra (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('What is the magnitude of the vector v = (3, 4)?', '5', '7', '12', '25', '5', 'The magnitude is sqrt(3^2 + 4^2) = sqrt(9 + 16) = sqrt(25) = 5.', 700, 'LinearAlgebra'),
('What is the dot product of u = (2, -1, 3) and v = (1, 4, 2)?', '4', '6', '-2', '10', '4', 'Dot product: 2*1 + (-1)*4 + 3*2 = 2 - 4 + 6 = 4.', 720, 'LinearAlgebra'),
('Two vectors are orthogonal if their dot product is:', '0', '1', '-1', 'undefined', '0', 'Orthogonal (perpendicular) vectors have a dot product of zero.', 710, 'LinearAlgebra'),
('What is the cross product of i = (1,0,0) and j = (0,1,0)?', 'k = (0,0,1)', '-k = (0,0,-1)', '(1,1,0)', '(0,0,0)', 'k = (0,0,1)', 'i x j = k by the right-hand rule for the standard basis cross products.', 760, 'LinearAlgebra'),
('What is the determinant of the 2x2 matrix [[3,1],[2,4]]?', '10', '14', '-10', '7', '10', 'det[[a,b],[c,d]] = ad - bc = 3*4 - 1*2 = 12 - 2 = 10.', 730, 'LinearAlgebra'),
('Which of the following sets of vectors is linearly independent?', '{(1,0),(0,1)}', '{(2,4),(1,2)}', '{(0,0),(1,2)}', '{(3,6),(1,2)}', '{(1,0),(0,1)}', 'The standard basis vectors (1,0) and (0,1) cannot be written as scalar multiples of each other, so they are linearly independent.', 780, 'LinearAlgebra'),
('The span of vectors v1 and v2 is:', 'All linear combinations c1*v1 + c2*v2', 'The dot product of v1 and v2', 'The cross product of v1 and v2', 'The set {v1, v2} only', 'All linear combinations c1*v1 + c2*v2', 'The span is the set of all vectors that can be formed as linear combinations of the given set.', 750, 'LinearAlgebra'),
('What is the transpose of the matrix [[1,2,3],[4,5,6]]?', '[[1,4],[2,5],[3,6]]', '[[4,5,6],[1,2,3]]', '[[1,2],[3,4],[5,6]]', '[[6,5,4],[3,2,1]]', '[[1,4],[2,5],[3,6]]', 'The transpose swaps rows and columns: the (i,j) entry becomes the (j,i) entry.', 740, 'LinearAlgebra'),
('A square matrix A is invertible if and only if:', 'det(A) != 0', 'det(A) = 0', 'A is symmetric', 'A has all positive entries', 'det(A) != 0', 'A matrix is invertible (non-singular) precisely when its determinant is non-zero, equivalently when its rows (or columns) are linearly independent.', 800, 'LinearAlgebra'),
('For a 3x3 matrix, what is the size of the identity matrix I that satisfies A*I = A?', '3x3', '1x1', '3x1', '1x3', '3x3', 'The identity matrix must have the same dimensions as the matrix it multiplies; for a 3x3 matrix, I is 3x3.', 710, 'LinearAlgebra'),
('What is the trace of the matrix [[4,1],[2,3]]?', '7', '10', '5', '-2', '7', 'The trace is the sum of the diagonal entries: 4 + 3 = 7.', 720, 'LinearAlgebra'),
('Gaussian elimination converts a matrix to:', 'Row echelon form', 'Column echelon form', 'Diagonal form', 'Symmetric form', 'Row echelon form', 'Gaussian elimination uses elementary row operations to produce a row echelon (upper triangular) form, from which back substitution solves the system.', 800, 'LinearAlgebra'),
('How many solutions does the system Ax = b have when A is a 3x3 matrix with det(A) = 0 and b != 0?', 'Either zero or infinitely many', 'Exactly one', 'Exactly two', 'Always zero', 'Either zero or infinitely many', 'When det(A) = 0 the matrix is singular; the system has either no solutions or infinitely many, depending on b.', 950, 'LinearAlgebra'),
('The rank of a matrix equals:', 'The number of pivots in its row echelon form', 'The number of rows', 'The number of columns', 'The determinant', 'The number of pivots in its row echelon form', 'Rank is the dimension of the column space, which equals the number of non-zero pivot positions after row reduction.', 870, 'LinearAlgebra'),
('If A is an m x n matrix, what is the rank-nullity theorem?', 'rank(A) + nullity(A) = n', 'rank(A) + nullity(A) = m', 'rank(A) * nullity(A) = m*n', 'rank(A) - nullity(A) = 0', 'rank(A) + nullity(A) = n', 'The rank-nullity theorem states that rank plus nullity equals the number of columns n of the matrix.', 1050, 'LinearAlgebra'),
('What is the nullspace of a matrix A?', 'The set of all x such that Ax = 0', 'The set of all Ax for any x', 'The set of pivot columns of A', 'The set of rows of A', 'The set of all x such that Ax = 0', 'The nullspace (kernel) consists of all vectors x that map to the zero vector under the linear transformation A.', 900, 'LinearAlgebra'),
('Which property must a subset W of a vector space V satisfy to be a subspace?', 'Closed under addition and scalar multiplication, and contains 0', 'Contains at least two vectors', 'Is finite and non-empty', 'All vectors in W are orthogonal', 'Closed under addition and scalar multiplication, and contains 0', 'A subspace must contain the zero vector and be closed under addition and scalar multiplication.', 1000, 'LinearAlgebra'),
('A basis of a vector space V is:', 'A linearly independent set that spans V', 'Any spanning set of V', 'Any linearly independent set in V', 'The set of all vectors in V', 'A linearly independent set that spans V', 'A basis is a minimal spanning set; it must be linearly independent and its span must equal the entire space.', 950, 'LinearAlgebra'),
('What is the dimension of the vector space R^4?', '4', '1', '16', 'infinite', '4', 'The dimension of R^n is n; the standard basis {e1, e2, e3, e4} has 4 vectors.', 720, 'LinearAlgebra'),
('If lambda is an eigenvalue of A, then det(A - lambda*I) equals:', '0', '1', 'lambda', 'det(A)', '0', 'Eigenvalues satisfy the characteristic equation det(A - lambda*I) = 0, which yields the characteristic polynomial.', 900, 'LinearAlgebra'),
('The characteristic polynomial of [[2,1],[0,3]] is:', '(lambda-2)(lambda-3)', '(lambda+2)(lambda+3)', 'lambda^2 - 1', 'lambda^2 - 5*lambda + 5', '(lambda-2)(lambda-3)', 'The matrix is upper triangular, so eigenvalues are diagonal entries 2 and 3; characteristic polynomial = (lambda-2)(lambda-3).', 1050, 'LinearAlgebra'),
('A matrix A is diagonalizable if:', 'It has n linearly independent eigenvectors', 'Its determinant is non-zero', 'It is symmetric', 'It has distinct entries', 'It has n linearly independent eigenvectors', 'An n x n matrix is diagonalizable if and only if it has n linearly independent eigenvectors, allowing A = P*D*P^{-1}.', 1150, 'LinearAlgebra'),
('What does it mean for a matrix to be orthogonally diagonalizable?', 'A = Q*D*Q^T where Q is orthogonal and D is diagonal', 'A = P*D*P^{-1} for some invertible P', 'A has only real eigenvalues', 'A is both symmetric and invertible', 'A = Q*D*Q^T where Q is orthogonal and D is diagonal', 'The spectral theorem states that real symmetric matrices are orthogonally diagonalizable: A = Q*D*Q^T with Q^T = Q^{-1}.', 1350, 'LinearAlgebra'),
('A linear transformation T: R^n -> R^m is represented by a matrix A. What is T(0)?', '0', 'A', 'I', 'undefined', '0', 'Every linear transformation maps the zero vector to the zero vector: T(0) = T(0*v) = 0*T(v) = 0.', 750, 'LinearAlgebra'),
('The composition of two linear transformations T: R^n -> R^m and S: R^m -> R^k corresponds to:', 'Matrix product S*T (S composed with T)', 'Matrix sum S + T', 'Matrix product T*S', 'The tensor product S⊗T', 'Matrix product S*T (S composed with T)', 'Composition (S after T) corresponds to multiplying the associated matrices in the same order: [S∘T] = [S][T].', 1100, 'LinearAlgebra'),
('The projection of vector u onto vector v is:', 'proj_v(u) = (u·v / v·v) * v', 'proj_v(u) = (u·v) * v', 'proj_v(u) = u - v', 'proj_v(u) = u x v', 'proj_v(u) = (u·v / v·v) * v', 'The orthogonal projection of u onto v is the scalar (u·v)/(v·v) times the vector v.', 1000, 'LinearAlgebra'),
('Gram-Schmidt orthogonalization takes a basis and produces:', 'An orthonormal basis spanning the same subspace', 'An orthogonal matrix with the same determinant', 'A diagonal matrix', 'A set of linearly dependent vectors', 'An orthonormal basis spanning the same subspace', 'Gram-Schmidt iteratively subtracts projections to produce an orthogonal set, which is then normalized to give an orthonormal basis.', 1200, 'LinearAlgebra'),
('A matrix Q is orthogonal if:', 'Q^T * Q = I', 'Q * Q = I', 'Q + Q^T = I', 'det(Q) = 0', 'Q^T * Q = I', 'An orthogonal matrix has Q^T = Q^{-1}, equivalently Q^T*Q = I; its columns form an orthonormal set.', 1000, 'LinearAlgebra'),
('What is the determinant of an orthogonal matrix Q?', '+1 or -1', '0', 'Any real number', 'Always +1', '+1 or -1', 'Since det(Q^T*Q) = det(I) = 1 and det(Q^T) = det(Q), we get det(Q)^2 = 1, so det(Q) = ±1.', 1150, 'LinearAlgebra'),
('For a symmetric matrix A, eigenvectors corresponding to distinct eigenvalues are:', 'Orthogonal', 'Parallel', 'Linearly dependent', 'Equal in magnitude', 'Orthogonal', 'The spectral theorem guarantees that for real symmetric A, eigenvectors for different eigenvalues are automatically orthogonal.', 1200, 'LinearAlgebra'),
('The singular value decomposition (SVD) of an m x n matrix A is:', 'A = U*Sigma*V^T', 'A = P*D*P^{-1}', 'A = L*U', 'A = Q*R', 'A = U*Sigma*V^T', 'SVD decomposes any matrix as A = U*Sigma*V^T, where U and V are orthogonal and Sigma is diagonal with non-negative singular values.', 1500, 'LinearAlgebra'),
('The singular values of A are:', 'Square roots of the eigenvalues of A^T*A', 'Eigenvalues of A', 'Diagonal entries of A', 'Square roots of the diagonal entries of A', 'Square roots of the eigenvalues of A^T*A', 'The singular values sigma_i = sqrt(lambda_i(A^T*A)); they are non-negative and characterize the "stretching" of A.', 1600, 'LinearAlgebra'),
('What is the rank of A = [[1,2,3],[2,4,6],[0,0,0]]?', '1', '2', '3', '0', '1', 'Row 2 = 2*row 1 and row 3 = 0; after row reduction there is exactly one pivot, so rank = 1.', 1000, 'LinearAlgebra'),
('A system of linear equations Ax = b is consistent if and only if:', 'b is in the column space of A', 'b is in the nullspace of A', 'det(A) = 0', 'A is square', 'b is in the column space of A', 'Ax = b is consistent precisely when b can be written as a linear combination of the columns of A, i.e., b ∈ col(A).', 1050, 'LinearAlgebra'),
('The LU decomposition of a matrix A factors it as:', 'A lower triangular matrix L times an upper triangular matrix U', 'An orthogonal matrix Q times a triangular matrix R', 'A diagonal matrix D times an orthogonal matrix', 'A product of elementary matrices only', 'A lower triangular matrix L times an upper triangular matrix U', 'LU decomposition factors A = L*U where L is lower triangular with 1s on the diagonal and U is upper triangular; it facilitates solving Ax = b efficiently.', 1200, 'LinearAlgebra'),
('What is the inverse of a 2x2 matrix [[a,b],[c,d]]?', '(1/(ad-bc)) * [[d,-b],[-c,a]]', '(1/(ad-bc)) * [[a,b],[c,d]]', '[[d,b],[c,a]] / (ad+bc)', '[[a,-b],[-c,d]] / (ad-bc)', '(1/(ad-bc)) * [[d,-b],[-c,a]]', 'The inverse of [[a,b],[c,d]] is (1/det)*[[d,-b],[-c,a]], where det = ad - bc.', 900, 'LinearAlgebra'),
('The column space of a matrix A is:', 'The span of the columns of A', 'The span of the rows of A', 'The set of solutions to Ax = 0', 'The set of diagonal entries of A', 'The span of the columns of A', 'The column space (image) of A is {Ax : x in R^n}, which is exactly the span of the columns of A.', 900, 'LinearAlgebra'),
('For a 4x4 matrix with eigenvalues 1, 2, 2, 3, what is the trace?', '8', '6', '12', '7', '8', 'The trace equals the sum of all eigenvalues: 1 + 2 + 2 + 3 = 8.', 1050, 'LinearAlgebra'),
('For a 4x4 matrix with eigenvalues 1, 2, 2, 3, what is the determinant?', '12', '8', '6', '24', '12', 'The determinant equals the product of all eigenvalues: 1 * 2 * 2 * 3 = 12.', 1100, 'LinearAlgebra'),
('Which matrix operation is NOT always commutative?', 'Matrix multiplication', 'Matrix addition', 'Scalar multiplication', 'Transposition of a sum', 'Matrix multiplication', 'In general A*B != B*A for matrix multiplication; the other operations (addition, scalar multiplication) are commutative.', 780, 'LinearAlgebra'),
('The Cayley-Hamilton theorem states that:', 'Every matrix satisfies its own characteristic polynomial', 'Every matrix has n distinct eigenvalues', 'Eigenvalues equal diagonal entries', 'det(A - lambda*I) = det(A)', 'Every matrix satisfies its own characteristic polynomial', 'Cayley-Hamilton: if p(lambda) = det(A - lambda*I) is the characteristic polynomial, then p(A) = 0 (the zero matrix).', 1500, 'LinearAlgebra'),
('If A is a 5x3 matrix, what is the maximum possible rank of A?', '3', '5', '8', '15', '3', 'Rank is at most min(m, n) = min(5, 3) = 3; it cannot exceed the number of columns or rows.', 870, 'LinearAlgebra'),
('What is the formula for the angle theta between two nonzero vectors u and v?', 'cos(theta) = (u·v) / (|u|*|v|)', 'cos(theta) = |u x v| / (|u|*|v|)', 'theta = u·v', 'sin(theta) = (u·v) / (|u|*|v|)', 'cos(theta) = (u·v) / (|u|*|v|)', 'The angle between vectors is given by the dot product formula: u·v = |u||v|cos(theta), so cos(theta) = (u·v)/(|u||v|).', 820, 'LinearAlgebra'),
('A matrix is positive definite if:', 'All its eigenvalues are strictly positive', 'Its determinant is positive', 'It is symmetric with positive entries', 'It has positive trace', 'All its eigenvalues are strictly positive', 'A real symmetric matrix is positive definite if and only if all its eigenvalues are strictly positive, equivalently if x^T*A*x > 0 for all nonzero x.', 1400, 'LinearAlgebra'),
('What is the geometric multiplicity of an eigenvalue lambda_0?', 'The dimension of the eigenspace ker(A - lambda_0*I)', 'The multiplicity of lambda_0 as a root of the characteristic polynomial', 'The trace of (A - lambda_0*I)', 'The rank of (A - lambda_0*I)', 'The dimension of the eigenspace ker(A - lambda_0*I)', 'Geometric multiplicity is the dimension of the nullspace of (A - lambda_0*I), i.e., the number of linearly independent eigenvectors for that eigenvalue.', 1350, 'LinearAlgebra'),
('The QR decomposition writes A as:', 'An orthogonal matrix Q times an upper triangular matrix R', 'A lower triangular L times upper triangular U', 'A diagonal D times an orthogonal Q', 'A permutation P times an invertible matrix', 'An orthogonal matrix Q times an upper triangular matrix R', 'QR decomposition factors A = Q*R where Q has orthonormal columns (Q^T*Q = I) and R is upper triangular; it arises from Gram-Schmidt.', 1300, 'LinearAlgebra'),
('The pseudoinverse (Moore-Penrose inverse) A^+ of a matrix A satisfies:', 'A*A^+*A = A', 'A^+*A = I always', '(A^+)^T = A', 'A^+*A^+ = A', 'A*A^+*A = A', 'The pseudoinverse satisfies four Moore-Penrose conditions; the key one is A*A^+*A = A, generalizing the inverse to non-square/singular matrices.', 1800, 'LinearAlgebra'),
('If A is an n x n matrix with n linearly independent eigenvectors P = [v1,...,vn], then A = ?', 'P*D*P^{-1} where D is diagonal with eigenvalues', 'P^{-1}*D*P where D has eigenvectors', 'D*P where D is diagonal', 'P*P^T', 'P*D*P^{-1} where D is diagonal with eigenvalues', 'Diagonalization gives A = P*D*P^{-1} where columns of P are eigenvectors and D has corresponding eigenvalues on its diagonal.', 1250, 'LinearAlgebra'),
('What is the best (least-squares) solution x* to the inconsistent system Ax = b?', 'x* = (A^T*A)^{-1}*A^T*b (when A^T*A is invertible)', 'x* = A^{-1}*b', 'x* = A^T*b', 'x* = (A*A^T)^{-1}*b', 'x* = (A^T*A)^{-1}*A^T*b (when A^T*A is invertible)', 'The least-squares solution minimizes ||Ax - b||^2 and satisfies the normal equations A^T*A*x = A^T*b, giving x* = (A^T*A)^{-1}*A^T*b.', 1600, 'LinearAlgebra'),
('The four fundamental subspaces of an m x n matrix A are:', 'col(A), null(A), col(A^T), null(A^T)', 'row(A), col(A), diag(A), null(A)', 'span(A), kernel(A), image(A), coimage(A)', 'col(A), null(A), eigenspace(A), trace(A)', 'col(A), null(A), col(A^T), null(A^T)', 'The four fundamental subspaces are the column space, nullspace, row space (= col(A^T)), and left nullspace (= null(A^T)), which come in orthogonal complement pairs.', 1700, 'LinearAlgebra');
INSERT INTO statistics (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
INSERT INTO anatomy (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
INSERT INTO microbiology (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
INSERT INTO molecularbiology (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('Which enzyme synthesizes a new DNA strand during replication?', 'DNA polymerase', 'RNA polymerase', 'Helicase', 'Ligase', 'DNA polymerase', 'DNA polymerase adds nucleotides to the growing strand in the 5-prime to 3-prime direction.', 740, 'MolecularBiology'),
('What type of bond holds the two strands of a DNA double helix together?', 'Hydrogen bonds', 'Covalent bonds', 'Ionic bonds', 'Peptide bonds', 'Hydrogen bonds', 'The complementary bases adenine-thymine and guanine-cytosine are held together by hydrogen bonds between the two strands.', 750, 'MolecularBiology'),
('Which nitrogenous base is found in RNA but NOT in DNA?', 'Uracil', 'Thymine', 'Cytosine', 'Adenine', 'Uracil', 'RNA contains uracil instead of thymine; uracil pairs with adenine just as thymine does in DNA.', 700, 'MolecularBiology'),
('What is the term for the RNA sequence that encodes one amino acid during translation?', 'Codon', 'Anticodon', 'Intron', 'Promoter', 'Codon', 'A codon is a three-nucleotide sequence on mRNA that specifies a particular amino acid or a stop signal.', 710, 'MolecularBiology'),
('Which of the following is the start codon in eukaryotic translation?', 'AUG', 'UAA', 'UGA', 'UAG', 'AUG', 'AUG encodes methionine and serves as the universal start codon, signalling the ribosome to begin translation.', 720, 'MolecularBiology'),
('What is the name of the short RNA primer required for DNA replication?', 'Primase-synthesized RNA primer', 'Okazaki fragment', 'Telomeric repeat', 'Small nuclear RNA', 'Primase-synthesized RNA primer', 'Primase synthesizes a short RNA primer that provides the free 3-prime hydroxyl group needed by DNA polymerase to begin synthesis.', 1370, 'MolecularBiology'),
('Which enzyme unwinds the DNA double helix ahead of the replication fork?', 'Helicase', 'Topoisomerase', 'DNA polymerase I', 'Primase', 'Helicase', 'Helicase breaks the hydrogen bonds between base pairs to separate the two strands and expose the template for replication.', 980, 'MolecularBiology'),
('What are Okazaki fragments?', 'Short DNA segments synthesized discontinuously on the lagging strand', 'Long continuous segments on the leading strand', 'RNA primers removed after replication', 'Telomeric repeat units', 'Short DNA segments synthesized discontinuously on the lagging strand', 'Because DNA polymerase can only synthesize 5-prime to 3-prime, the lagging strand is made in short discontinuous pieces called Okazaki fragments.', 1420, 'MolecularBiology'),
('Which type of mutation converts a codon encoding one amino acid into a stop codon?', 'Nonsense mutation', 'Missense mutation', 'Silent mutation', 'Frameshift mutation', 'Nonsense mutation', 'A nonsense mutation introduces a premature stop codon, causing translation to terminate early and producing a truncated protein.', 950, 'MolecularBiology'),
('What is the role of the TATA box in eukaryotic transcription?', 'It is a core promoter element that positions RNA polymerase II', 'It codes for the first amino acid of the protein', 'It marks the polyadenylation site', 'It is the splice donor site of introns', 'It is a core promoter element that positions RNA polymerase II', 'The TATA box, located about 25-30 bp upstream of the transcription start site, recruits TFIID and helps position RNA polymerase II correctly.', 1100, 'MolecularBiology'),
('Which enzyme adds a poly-A tail to eukaryotic pre-mRNA?', 'Poly-A polymerase', 'RNA polymerase II', 'Spliceosomes', 'Ribonuclease H', 'Poly-A polymerase', 'After cleavage at the polyadenylation signal, poly-A polymerase adds approximately 200 adenine residues to protect the mRNA and aid export.', 1050, 'MolecularBiology'),
('In the lac operon, which molecule acts as the inducer?', 'Allolactose', 'Lactose', 'Glucose', 'cAMP', 'Allolactose', 'Allolactose, a metabolite of lactose, binds the lac repressor and causes it to dissociate from the operator, allowing transcription.', 1200, 'MolecularBiology'),
('Which component of the spliceosome recognizes the 5-prime splice site?', 'U1 snRNP', 'U2 snRNP', 'U4 snRNP', 'U6 snRNP', 'U1 snRNP', 'U1 snRNP base-pairs with the 5-prime splice site consensus sequence, initiating the assembly of the spliceosome complex.', 1300, 'MolecularBiology'),
('What type of mutation results in the insertion or deletion of nucleotides that shifts the reading frame?', 'Frameshift mutation', 'Missense mutation', 'Nonsense mutation', 'Silent mutation', 'Frameshift mutation', 'Insertion or deletion of a number of nucleotides not divisible by three shifts the triplet reading frame, altering all downstream codons.', 1380, 'MolecularBiology'),
('In PCR, what is the purpose of the denaturation step?', 'To separate the two DNA strands so primers can anneal', 'To allow primers to bind to the template', 'To extend new DNA strands from the primers', 'To release the newly synthesized product', 'To separate the two DNA strands so primers can anneal', 'Heating to approximately 94-98 degrees Celsius breaks the hydrogen bonds between complementary bases, producing single-stranded templates.', 1020, 'MolecularBiology'),
('Which technique uses restriction enzymes and gel electrophoresis to detect specific DNA sequences after transfer to a membrane?', 'Southern blotting', 'Northern blotting', 'Western blotting', 'Eastern blotting', 'Southern blotting', 'Southern blotting detects specific DNA sequences; the DNA is digested, separated by gel electrophoresis, transferred to a membrane, and hybridized with a labeled probe.', 1390, 'MolecularBiology'),
('How many hydrogen bonds hold a guanine-cytosine base pair together?', 'Three', 'Two', 'One', 'Four', 'Three', 'G-C base pairs are held by three hydrogen bonds, whereas A-T pairs are held by only two, making G-C-rich regions of DNA more thermally stable.', 780, 'MolecularBiology'),
('Which ribosomal site holds the tRNA carrying the growing polypeptide chain?', 'P site (peptidyl site)', 'A site (aminoacyl site)', 'E site (exit site)', 'mRNA entry site', 'P site (peptidyl site)', 'The P site holds the peptidyl-tRNA bearing the elongating polypeptide, while the A site accepts the incoming aminoacyl-tRNA.', 980, 'MolecularBiology'),
('What is the anticodon of a tRNA that recognizes the codon 5-prime-GGC-3-prime?', '5-prime-GCC-3-prime', '5-prime-CCG-3-prime', '5-prime-CGG-3-prime', '5-prime-GGC-3-prime', '5-prime-GCC-3-prime', 'The anticodon is complementary and antiparallel to the codon; the anticodon for 5-prime-GGC-3-prime is 3-prime-CCG-5-prime, written 5-prime-GCC-3-prime.', 1400, 'MolecularBiology'),
('Which of the following correctly describes a missense mutation?', 'A base substitution that changes one amino acid to a different amino acid', 'A substitution that introduces a premature stop codon', 'A substitution that does not change the amino acid', 'An insertion that shifts the reading frame', 'A base substitution that changes one amino acid to a different amino acid', 'A missense mutation alters a single nucleotide such that the codon now specifies a different amino acid, potentially affecting protein function.', 880, 'MolecularBiology'),
('In CRISPR-Cas9 gene editing, what directs the Cas9 nuclease to the correct genomic location?', 'Single guide RNA (sgRNA)', 'A restriction enzyme recognition site', 'A short interfering RNA (siRNA)', 'A primer pair', 'Single guide RNA (sgRNA)', 'The sgRNA contains a 20-nucleotide spacer complementary to the target DNA, guiding Cas9 to cut within 3 bp upstream of a PAM sequence.', 1050, 'MolecularBiology'),
('Which enzyme removes RNA primers and replaces them with DNA during replication in prokaryotes?', 'DNA polymerase I', 'DNA polymerase III', 'Ligase', 'RNase H', 'DNA polymerase I', 'E. coli DNA polymerase I uses its 5-prime to 3-prime exonuclease activity to remove the RNA primer and fill the gap with DNA.', 1250, 'MolecularBiology'),
('What is the name of the protein complex that uncoats mRNA caps and initiates translation in eukaryotes?', 'eIF4F complex', 'Ribosome recycling factor', 'Signal recognition particle', 'Peptidyl transferase center', 'eIF4F complex', 'The eIF4F complex, consisting of eIF4E, eIF4G, and eIF4A, binds the 5-prime cap and helps recruit the 43S pre-initiation complex to the mRNA.', 1550, 'MolecularBiology'),
('Which class of RNA molecule carries amino acids to the ribosome during translation?', 'Transfer RNA (tRNA)', 'Messenger RNA (mRNA)', 'Ribosomal RNA (rRNA)', 'Small nuclear RNA (snRNA)', 'Transfer RNA (tRNA)', 'tRNA molecules are adaptor molecules that each carry a specific amino acid and recognize the corresponding codon on mRNA via their anticodon loop.', 710, 'MolecularBiology'),
('What is the Shine-Dalgarno sequence?', 'A ribosome-binding site on prokaryotic mRNA', 'The sequence at the 5-prime cap of eukaryotic mRNA', 'The polyadenylation signal in mRNA', 'The promoter consensus sequence in prokaryotes', 'A ribosome-binding site on prokaryotic mRNA', 'The Shine-Dalgarno sequence, located 5-10 nt upstream of the start codon, base-pairs with the 16S rRNA of the 30S subunit to position the ribosome.', 1100, 'MolecularBiology'),
('During transcription, which strand of DNA serves as the template?', 'The antisense (template) strand read 3-prime to 5-prime', 'The sense (coding) strand read 5-prime to 3-prime', 'Both strands are read simultaneously', 'Either strand, depending on the cell cycle stage', 'The antisense (template) strand read 3-prime to 5-prime', 'RNA polymerase reads the template strand 3-prime to 5-prime and synthesizes the RNA transcript in the 5-prime to 3-prime direction, matching the coding strand.', 1000, 'MolecularBiology'),
('Which of the following is an example of epigenetic regulation?', 'Histone methylation silencing gene expression', 'A point mutation in the coding sequence', 'Alternative splicing of pre-mRNA', 'Codon degeneracy in the genetic code', 'Histone methylation silencing gene expression', 'Epigenetic regulation involves heritable changes in gene expression without altering the DNA sequence; histone methylation can compact chromatin and repress transcription.', 1300, 'MolecularBiology'),
('What is the purpose of gel electrophoresis in molecular biology?', 'To separate molecules by size through a porous gel using an electric field', 'To amplify specific DNA sequences exponentially', 'To cut DNA at specific recognition sequences', 'To transfer DNA from gel to a membrane', 'To separate molecules by size through a porous gel using an electric field', 'In gel electrophoresis, negatively charged nucleic acids migrate toward the positive electrode, with smaller fragments moving faster through the gel matrix.', 750, 'MolecularBiology'),
('Which enzyme joins Okazaki fragments on the lagging strand?', 'DNA ligase', 'DNA polymerase III', 'Primase', 'Topoisomerase II', 'DNA ligase', 'DNA ligase seals the nick between adjacent Okazaki fragments by forming a phosphodiester bond between the 3-prime hydroxyl and 5-prime phosphate ends.', 1360, 'MolecularBiology'),
('What is a restriction enzyme?', 'An endonuclease that cleaves DNA at specific recognition sequences', 'An enzyme that ligates DNA fragments together', 'An enzyme that methylates cytosine residues', 'A polymerase that copies single-stranded DNA', 'An endonuclease that cleaves DNA at specific recognition sequences', 'Restriction endonucleases recognize specific palindromic sequences (typically 4-8 bp) and cut the DNA at or near that site, producing defined fragments.', 1430, 'MolecularBiology'),
('In eukaryotes, what must be removed from pre-mRNA before it can be translated?', 'Introns', 'Exons', 'The 5-prime cap', 'The poly-A tail', 'Introns', 'Introns are non-coding intervening sequences that are excised from the pre-mRNA by the spliceosome; the remaining exons are joined to form mature mRNA.', 760, 'MolecularBiology'),
('Which of the following best describes a silent mutation?', 'A nucleotide change that does not alter the amino acid sequence due to codon degeneracy', 'A mutation with no effect on the organism''s phenotype regardless of the protein change', 'A mutation occurring outside the coding region', 'A deletion of a complete codon', 'A nucleotide change that does not alter the amino acid sequence due to codon degeneracy', 'Silent (synonymous) mutations change a codon to a synonymous codon encoding the same amino acid, owing to the redundancy of the genetic code.', 950, 'MolecularBiology'),
('Which protein assists newly synthesized polypeptides in achieving their correct three-dimensional structure?', 'Molecular chaperone (e.g., Hsp70)', 'Ubiquitin ligase', 'Proteasome', 'Signal recognition particle', 'Molecular chaperone (e.g., Hsp70)', 'Molecular chaperones like Hsp70 bind to exposed hydrophobic regions of unfolded polypeptides, preventing aggregation and facilitating correct folding.', 1050, 'MolecularBiology'),
('What is the role of topoisomerase during DNA replication?', 'Relieves torsional strain ahead of the replication fork by cutting and rejoining DNA', 'Synthesizes the RNA primer', 'Joins newly synthesized DNA fragments', 'Uncoats histones from the chromatin template', 'Relieves torsional strain ahead of the replication fork by cutting and rejoining DNA', 'As helicase unwinds the double helix, positive supercoils accumulate ahead; topoisomerase I or II cuts and re-ligates DNA to relieve this torsional stress.', 1350, 'MolecularBiology'),
('Which technique is used to detect specific proteins separated by gel electrophoresis after transfer to a membrane?', 'Western blotting', 'Southern blotting', 'Northern blotting', 'ELISA', 'Western blotting', 'Western blotting involves SDS-PAGE separation of proteins, transfer to a membrane, and detection with a specific antibody, allowing identification by molecular weight.', 1410, 'MolecularBiology'),
('What is the genetic code said to be when multiple codons can specify the same amino acid?', 'Degenerate', 'Unambiguous', 'Non-overlapping', 'Universal', 'Degenerate', 'The genetic code is degenerate (redundant) because most amino acids are encoded by more than one codon, especially differing at the third (wobble) position.', 980, 'MolecularBiology'),
('Which of the following describes the leading strand during DNA replication?', 'Synthesized continuously in the 5-prime to 3-prime direction toward the replication fork', 'Synthesized discontinuously away from the replication fork', 'Synthesized using only RNA primers without DNA polymerase extension', 'Replicated only after the lagging strand is complete', 'Synthesized continuously in the 5-prime to 3-prime direction toward the replication fork', 'The leading strand is synthesized continuously in the 5-prime to 3-prime direction because it runs toward the open replication fork, requiring only one primer.', 950, 'MolecularBiology'),
('Which RNA polymerase transcribes protein-coding genes in eukaryotes?', 'RNA polymerase II', 'RNA polymerase I', 'RNA polymerase III', 'RNA polymerase IV', 'RNA polymerase II', 'RNA polymerase II transcribes mRNA precursors (pre-mRNA) in the eukaryotic nucleus; RNA Pol I makes rRNA and Pol III makes tRNA and 5S rRNA.', 870, 'MolecularBiology'),
('What is the function of the signal recognition particle (SRP) during translation?', 'Directs ribosomes translating signal-peptide-containing proteins to the ER membrane', 'Degrades misfolded proteins in the cytoplasm', 'Adds the poly-A tail to mature mRNA', 'Caps the 5-prime end of mRNA after transcription', 'Directs ribosomes translating signal-peptide-containing proteins to the ER membrane', 'SRP recognizes the hydrophobic N-terminal signal peptide as it emerges from the ribosome and docks the ribosome-mRNA complex at the SRP receptor on the ER.', 1450, 'MolecularBiology'),
('In Sanger (dideoxy chain-termination) sequencing, what causes chain termination?', 'Incorporation of a dideoxynucleotide lacking a 3-prime hydroxyl group', 'Binding of a complementary probe to the template', 'Denaturation of the DNA at a specific temperature', 'Restriction enzyme cleavage at a specific site', 'Incorporation of a dideoxynucleotide lacking a 3-prime hydroxyl group', 'Dideoxynucleotides (ddNTPs) lack the 3-prime OH required for phosphodiester bond formation, so incorporation terminates strand extension at that position.', 1250, 'MolecularBiology'),
('Which of the following is the correct base-pairing rule in double-stranded DNA?', 'Adenine pairs with thymine; guanine pairs with cytosine', 'Adenine pairs with cytosine; guanine pairs with thymine', 'Adenine pairs with uracil; guanine pairs with cytosine', 'Adenine pairs with guanine; thymine pairs with cytosine', 'Adenine pairs with thymine; guanine pairs with cytosine', 'Watson-Crick base pairing specifies A-T (two hydrogen bonds) and G-C (three hydrogen bonds) complementarity in double-stranded DNA.', 700, 'MolecularBiology'),
('What is the end-replication problem?', 'Linear chromosomes shorten with each replication cycle because the lagging strand cannot be fully replicated at the 5-prime end', 'Circular chromosomes cannot be replicated without introducing strand breaks', 'RNA polymerase cannot initiate replication without a free 3-prime OH', 'Topoisomerases fail to relieve supercoiling near telomeres', 'Linear chromosomes shorten with each replication cycle because the lagging strand cannot be fully replicated at the 5-prime end', 'After removal of the terminal RNA primer on the lagging strand, no upstream primer exists to fill the gap, so each round of replication shortens the chromosome end.', 1500, 'MolecularBiology'),
('Which of the following is a direct consequence of DNA methylation at CpG islands in promoter regions?', 'Transcriptional silencing of the associated gene', 'Enhanced binding of RNA polymerase II', 'Increased rate of mRNA splicing', 'Stabilization of the mRNA transcript', 'Transcriptional silencing of the associated gene', 'Methylation of cytosine at CpG islands recruits methyl-binding proteins and histone deacetylases, compacting chromatin and repressing gene transcription.', 1400, 'MolecularBiology'),
('What type of RNA carries the genetic information from the nucleus to the ribosome for translation?', 'Messenger RNA (mRNA)', 'Transfer RNA (tRNA)', 'Ribosomal RNA (rRNA)', 'MicroRNA (miRNA)', 'Messenger RNA (mRNA)', 'mRNA is transcribed from the DNA template, processed in the nucleus, exported to the cytoplasm, and decoded by ribosomes to produce a polypeptide.', 700, 'MolecularBiology'),
('Which nucleotide is the precursor for the 5-prime cap added to eukaryotic mRNA?', '7-methylguanosine (m7G)', 'Adenosine', 'Cytidine', 'Inosine', '7-methylguanosine (m7G)', 'The 5-prime cap consists of a 7-methylguanosine linked by an unusual 5-prime to 5-prime triphosphate bond, added co-transcriptionally to protect mRNA and aid translation initiation.', 1350, 'MolecularBiology'),
('What distinguishes type II restriction enzymes from types I and III?', 'They cut DNA within or close to their recognition sequence, not remotely', 'They require ATP hydrolysis for DNA cleavage', 'They recognize non-palindromic sequences of 2-3 bp', 'They methylate DNA rather than cutting it', 'They cut DNA within or close to their recognition sequence, not remotely', 'Type II restriction enzymes cleave at fixed positions within or adjacent to their palindromic recognition site, making them the standard tool for molecular cloning.', 1600, 'MolecularBiology'),
('Which of the following best describes the wobble hypothesis?', 'The third position of the codon allows non-Watson-Crick base pairing with the anticodon', 'The ribosome can read codons in two different frames', 'A single tRNA can recognize only one codon', 'Stop codons pair with tRNA anticodons via wobble interactions', 'The third position of the codon allows non-Watson-Crick base pairing with the anticodon', 'Crick''s wobble hypothesis proposes that the first anticodon base (position 34) can form non-standard pairs with the third codon base, allowing one tRNA to decode multiple synonymous codons.', 1700, 'MolecularBiology'),
('What is the primary function of chaperonins such as GroEL/GroES in E. coli?', 'Provide an isolated chamber for correct protein folding by preventing aggregation', 'Degrade misfolded proteins via proteolysis', 'Methylate newly synthesized polypeptides', 'Facilitate co-translational signal peptide cleavage', 'Provide an isolated chamber for correct protein folding by preventing aggregation', 'GroEL forms a barrel-shaped cavity where unfolded proteins are encapsulated by the GroES co-chaperonin lid, creating an environment that promotes correct folding in an ATP-dependent manner.', 1800, 'MolecularBiology');
INSERT INTO physiology (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
INSERT INTO analyticalchemistry (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score) VALUES
INSERT INTO biochemistry (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
INSERT INTO inorganicchemistry (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('Which group of the periodic table contains the alkali metals?', 'Group 1', 'Group 2', 'Group 17', 'Group 18', 'Group 1', 'Group 1 elements (Li, Na, K, Rb, Cs, Fr) are the alkali metals, each with one valence electron and highly reactive.', 720, 'InorganicChemistry'),
('Which periodic trend correctly describes atomic radius across a period (left to right)?', 'Atomic radius increases', 'Atomic radius decreases', 'Atomic radius remains constant', 'Atomic radius first increases then decreases', 'Atomic radius decreases', 'Across a period, increasing nuclear charge with the same shielding pulls electrons closer, reducing the atomic radius.', 800, 'InorganicChemistry'),
('Which element has the electron configuration [Ar] 3d5 4s1?', 'Mn', 'Cr', 'Fe', 'V', 'Cr', 'Chromium adopts [Ar] 3d5 4s1 rather than [Ar] 3d4 4s2 because a half-filled d subshell provides extra stability.', 1200, 'InorganicChemistry'),
('What is the oxidation state of sulfur in H2SO4?', '+4', '+6', '+2', '-2', '+6', 'In H2SO4, assigning +1 to H and -2 to O gives 2(+1) + S + 4(-2) = 0, so S = +6.', 850, 'InorganicChemistry'),
('Which geometry does a molecule with four bonding pairs and no lone pairs adopt according to VSEPR?', 'Square planar', 'Trigonal pyramidal', 'Tetrahedral', 'Bent', 'Tetrahedral', 'Four bonding pairs and zero lone pairs around a central atom produce a tetrahedral geometry with bond angles of 109.5 degrees.', 730, 'InorganicChemistry'),
('What hybridization is adopted by the carbon atoms in ethyne (acetylene, C2H2)?', 'sp^3', 'sp^2', 'sp', 'sp^3d', 'sp', 'Each carbon in ethyne forms one sigma bond to H and one sigma bond to the other carbon; the remaining two p orbitals form two pi bonds, requiring sp hybridization.', 900, 'InorganicChemistry'),
('Which of the following is a Lewis acid?', 'NH3', 'OH-', 'BF3', 'H2O', 'BF3', 'BF3 has an empty p orbital on boron and can accept an electron pair, making it a Lewis acid.', 1050, 'InorganicChemistry'),
('In the coordination compound [Co(NH3)6]3+, what is the coordination number of cobalt?', '3', '4', '6', '9', '6', 'Coordination number equals the number of ligand donor atoms directly bonded to the metal; six NH3 ligands each donate one electron pair, giving coordination number 6.', 780, 'InorganicChemistry'),
('What is the IUPAC name of [Fe(CN)6]3-?', 'Hexacyanoferrate(II)', 'Hexacyanoferrate(III)', 'Hexaisocyanoiron(III)', 'Hexacyanocobaltate(III)', 'Hexacyanoferrate(III)', 'Anionic complexes use the suffix -ate; six CN- ligands (hexacyano) on Fe3+ (iron in oxidation state +3) gives hexacyanoferrate(III).', 1400, 'InorganicChemistry'),
('According to crystal field theory, which set of d orbitals is raised in energy in an octahedral field?', 't2g set (dxy, dxz, dyz)', 'eg set (dx^2-y^2, dz^2)', 'All five d orbitals equally', 'Only dz^2', 'eg set (dx^2-y^2, dz^2)', 'In an octahedral crystal field, the dx^2-y^2 and dz^2 orbitals (eg) point directly at ligands and experience greater repulsion, raising their energy above the t2g set.', 1500, 'InorganicChemistry'),
('Which of the following ligands is a bidentate chelate?', 'Cl-', 'NH3', 'ethylenediamine (en)', 'H2O', 'ethylenediamine (en)', 'Ethylenediamine (en) has two nitrogen donor atoms and can coordinate to a metal through both simultaneously, making it bidentate.', 1100, 'InorganicChemistry'),
('What is the oxidation state of manganese in KMnO4?', '+5', '+6', '+7', '+4', '+7', 'In KMnO4, K = +1 and each O = -2; so +1 + Mn + 4(-2) = 0 gives Mn = +7.', 900, 'InorganicChemistry'),
('Which quantum number describes the shape of an atomic orbital?', 'Principal quantum number (n)', 'Azimuthal quantum number (l)', 'Magnetic quantum number (ml)', 'Spin quantum number (ms)', 'Azimuthal quantum number (l)', 'The azimuthal (angular momentum) quantum number l defines the subshell and shape: l=0 is s, l=1 is p, l=2 is d, l=3 is f.', 820, 'InorganicChemistry'),
('What is the lattice energy trend for ionic compounds as ionic charge increases?', 'Lattice energy decreases', 'Lattice energy increases', 'Lattice energy is unaffected by charge', 'Lattice energy first increases then decreases', 'Lattice energy increases', 'Lattice energy is proportional to the product of ion charges (Madelung-law); higher charges increase electrostatic attraction and thus lattice energy.', 980, 'InorganicChemistry'),
('In the Born-Haber cycle for NaCl, which step represents the first ionization energy of sodium?', 'Na(s) -> Na(g)', 'Na(g) -> Na+(g) + e-', 'Cl2(g) -> 2 Cl(g)', 'Cl(g) + e- -> Cl-(g)', 'Na(g) -> Na+(g) + e-', 'The first ionization energy is defined as the energy required to remove one electron from a gaseous atom: Na(g) -> Na+(g) + e-.', 1050, 'InorganicChemistry'),
('Which noble gas configuration is correct for the chloride ion Cl-?', 'He core', 'Ne core', 'Ar core', 'Kr core', 'Ar core', 'Cl has 17 electrons; gaining one electron gives 18 electrons, identical to argon''s electron configuration [Ar].', 750, 'InorganicChemistry'),
('What is the molecular geometry of SF6?', 'Trigonal bipyramidal', 'Octahedral', 'Square pyramidal', 'Pentagonal bipyramidal', 'Octahedral', 'SF6 has six bonding pairs and zero lone pairs around sulfur, giving an octahedral geometry with F-S-F angles of 90 degrees.', 860, 'InorganicChemistry'),
('Which of the following oxides is amphoteric?', 'Na2O', 'SO3', 'Al2O3', 'CaO', 'Al2O3', 'Al2O3 can react with both acids and bases; it reacts with HCl to form AlCl3 and with NaOH to form aluminate, hence it is amphoteric.', 1150, 'InorganicChemistry'),
('What is the bond order in the O2 molecule according to molecular orbital theory?', '1', '1.5', '2', '3', '2', 'O2 has 12 valence electrons; filling MOs gives (sigma2s)2(sigma*2s)2(sigma2p)2(pi2p)4(pi*2p)2, bond order = (8-4)/2 = 2.', 1300, 'InorganicChemistry'),
('Which transition metal complex is expected to be high-spin in an octahedral field with weak-field ligands?', '[Fe(CN)6]3-', '[Co(NH3)6]3+', '[FeCl6]3-', '[Cr(CO)6]', '[FeCl6]3-', 'Cl- is a weak-field ligand producing a small crystal field splitting, insufficient to force electron pairing; Fe3+ (d5) adopts a high-spin configuration with five unpaired electrons.', 1600, 'InorganicChemistry'),
('What is the formal charge on nitrogen in the nitrate ion NO3-?', '0', '+1', '-1', '+2', '+1', 'In NO3-, N forms one double bond and two single bonds; formal charge = 5 - 0 - 4 = +1 (with one N=O and two N-O single bonds accounting for 8 bonding electrons/2 = 4 to N).', 1350, 'InorganicChemistry'),
('Which element has the highest electronegativity on the Pauling scale?', 'Oxygen', 'Chlorine', 'Nitrogen', 'Fluorine', 'Fluorine', 'Fluorine (electronegativity 3.98) is the most electronegative element because of its small size and high nuclear charge relative to its electron count.', 700, 'InorganicChemistry'),
('What type of solid is NaCl?', 'Molecular solid', 'Metallic solid', 'Covalent network solid', 'Ionic solid', 'Ionic solid', 'NaCl consists of Na+ and Cl- ions held together by electrostatic attractions in a face-centred cubic lattice, classifying it as an ionic solid.', 710, 'InorganicChemistry'),
('What is the coordination geometry around the central metal in a square planar complex?', 'Four ligands at corners of a tetrahedron', 'Four ligands in a plane at 90 degrees', 'Six ligands in an octahedron', 'Two ligands linearly opposed', 'Four ligands in a plane at 90 degrees', 'Square planar complexes have four ligands arranged in a plane around the metal at 90-degree angles, common for d8 metal ions such as Pt2+ and Pd2+.', 1000, 'InorganicChemistry'),
('Which of the following is the correct Lewis structure description of CO2?', 'O=C=O with two double bonds', 'O-C=O with one single and one double bond', 'O-C-O with two single bonds', 'O:::C:::O with two triple bonds', 'O=C=O with two double bonds', 'Carbon forms two double bonds (one with each oxygen) to satisfy the octet rule for all atoms, giving a linear molecule with zero lone pairs on carbon.', 790, 'InorganicChemistry'),
('In a period, ionization energy generally increases from left to right. Which element anomalously has a lower first ionization energy than expected based on this trend?', 'Carbon (C)', 'Nitrogen (N)', 'Oxygen (O)', 'Fluorine (F)', 'Oxygen (O)', 'Oxygen''s first ionization energy is lower than nitrogen''s because pairing electrons in the 2p subshell introduces extra electron-electron repulsion, making one easier to remove.', 1250, 'InorganicChemistry'),
('What is the name of the process by which an ionic compound dissolves and its ions interact with water molecules?', 'Hydrolysis', 'Hydration', 'Solvation by a non-polar solvent', 'Sublimation', 'Hydration', 'Hydration refers specifically to the exothermic process where water molecules surround and stabilise the dissolved ions via ion-dipole interactions.', 870, 'InorganicChemistry'),
('Which of the following best describes a sigma (sigma) bond?', 'Sideways overlap of two p orbitals', 'End-to-end orbital overlap along the internuclear axis', 'Overlap involving only s orbitals', 'Electrostatic attraction between ions', 'End-to-end orbital overlap along the internuclear axis', 'A sigma bond is formed by end-to-end (head-on) overlap of orbitals along the bond axis, allowing free rotation and being present in all single bonds.', 920, 'InorganicChemistry'),
('What is the electron geometry of PCl5?', 'Trigonal planar', 'Tetrahedral', 'Trigonal bipyramidal', 'Octahedral', 'Trigonal bipyramidal', 'PCl5 has five bonding pairs and no lone pairs; VSEPR predicts trigonal bipyramidal geometry with axial angles of 180 degrees and equatorial angles of 120 degrees.', 830, 'InorganicChemistry'),
('Which crystal structure do most alkali metal halides adopt at room temperature?', 'Zinc blende (sphalerite)', 'Wurtzite', 'Rock salt (NaCl type)', 'Fluorite', 'Rock salt (NaCl type)', 'Most alkali metal halides crystallise in the rock salt structure, where each ion is octahedrally coordinated by six oppositely charged ions.', 1050, 'InorganicChemistry'),
('What is the oxidation state of iron in Fe3O4?', '+2 and +3 (mixed)', '+3 only', '+2 only', '+4', '+2 and +3 (mixed)', 'Fe3O4 (magnetite) is a mixed-oxide containing both Fe2+ and Fe3+ in a 1:2 ratio; it can be written as FeO·Fe2O3.', 1200, 'InorganicChemistry'),
('Which of the following correctly describes the trans effect in square planar complexes?', 'A ligand stabilises the ligand cis to it', 'A strong trans-directing ligand labilises the ligand opposite to it', 'All ligands are equally labile regardless of position', 'The trans effect applies only to octahedral complexes', 'A strong trans-directing ligand labilises the ligand opposite to it', 'The trans effect is the ability of a ligand to weaken and labilise the metal-ligand bond trans to it, important in the synthesis of Pt(II) complexes.', 1800, 'InorganicChemistry'),
('Which of the following sets of quantum numbers is NOT allowed for an electron?', 'n=2, l=1, ml=0, ms=+1/2', 'n=3, l=2, ml=-2, ms=-1/2', 'n=2, l=2, ml=1, ms=+1/2', 'n=4, l=0, ml=0, ms=-1/2', 'n=2, l=2, ml=1, ms=+1/2', 'For n=2, l can only be 0 or 1; l=2 is not permitted when n=2 because l must be less than n.', 1100, 'InorganicChemistry'),
('What is the VSEPR shape of the XeF4 molecule?', 'Tetrahedral', 'See-saw', 'Square planar', 'Trigonal pyramidal', 'Square planar', 'XeF4 has four bonding pairs and two lone pairs in an octahedral electron geometry; the two lone pairs occupy axial positions, giving a square planar molecular shape.', 1350, 'InorganicChemistry'),
('Which of the following best defines a Bronsted-Lowry acid?', 'A species that accepts an electron pair', 'A species that donates a proton (H+)', 'A species that produces OH- in water', 'A species that gains electrons', 'A species that donates a proton (H+)', 'In Bronsted-Lowry theory, an acid is defined as a proton donor, transferring H+ to a base to form its conjugate base.', 740, 'InorganicChemistry'),
('What is the crystal field splitting parameter (delta_o) for an octahedral complex compared to a tetrahedral complex with the same ligands and metal?', 'delta_o = 4/9 delta_t', 'delta_o is smaller than delta_t', 'delta_o = delta_t', 'delta_o = 9/4 delta_t', 'delta_o = 9/4 delta_t', 'Octahedral splitting is approximately 9/4 (or 2.25) times larger than tetrahedral splitting because octahedral complexes have more ligands interacting along axes aligned with d orbitals.', 1700, 'InorganicChemistry'),
('Which main-group element can expand its octet and accommodate more than 8 electrons in its valence shell?', 'Carbon', 'Nitrogen', 'Phosphorus', 'Oxygen', 'Phosphorus', 'Phosphorus (period 3) can use its available 3d orbitals to accommodate more than eight electrons, as seen in PCl5 and H3PO4.', 1000, 'InorganicChemistry'),
('What is the general formula for a polydentate ligand called EDTA?', 'Monodentate with one donor', 'Bidentate with two donors', 'Tetradentate with four donors', 'Hexadentate with six donors', 'Hexadentate with six donors', 'EDTA (ethylenediaminetetraacetate) has two nitrogen and four carboxylate oxygen donor atoms, making it a hexadentate ligand that can completely wrap around a metal.', 1150, 'InorganicChemistry'),
('When balancing a redox reaction in acidic solution, which species are added to balance oxygen atoms?', 'OH- ions', 'H2O molecules', 'O2 gas', 'CO2 molecules', 'H2O molecules', 'In acidic solution, oxygen atoms are balanced by adding H2O to the side that needs oxygen, then balancing the resulting hydrogen imbalance with H+.', 960, 'InorganicChemistry'),
('What is the standard oxidation state of hydrogen in most compounds?', '-1', '0', '+1', '+2', '+1', 'Hydrogen is assigned +1 in most compounds (e.g., HCl, H2O); it is -1 only in metal hydrides such as NaH.', 700, 'InorganicChemistry'),
('Which of the following describes the effective nuclear charge (Zeff) trend across a period?', 'Zeff decreases across a period', 'Zeff increases across a period', 'Zeff remains constant across a period', 'Zeff increases then decreases across a period', 'Zeff increases across a period', 'As electrons are added to the same shell across a period, shielding is relatively constant but nuclear charge (Z) increases, so Zeff = Z - S increases steadily.', 1050, 'InorganicChemistry'),
('What is the geometry around nitrogen in NH3 according to VSEPR?', 'Trigonal planar', 'Trigonal pyramidal', 'Tetrahedral', 'T-shaped', 'Trigonal pyramidal', 'NH3 has three bonding pairs and one lone pair on nitrogen; the lone pair compresses bond angles to about 107 degrees, giving a trigonal pyramidal shape.', 760, 'InorganicChemistry'),
('Which of the following pairs represents an example of a redox reaction?', 'HCl + NaOH -> NaCl + H2O', 'AgNO3 + NaCl -> AgCl + NaNO3', 'Zn + CuSO4 -> ZnSO4 + Cu', 'CO2 + H2O -> H2CO3', 'Zn + CuSO4 -> ZnSO4 + Cu', 'In this reaction, Zn is oxidised (0 to +2) and Cu2+ is reduced (+2 to 0), making it a classic single-displacement redox reaction.', 810, 'InorganicChemistry'),
('Which of the following correctly describes the relationship between ionization energy and atomic radius?', 'Larger atoms have higher ionization energies', 'Smaller atoms tend to have higher ionization energies', 'Ionization energy is independent of atomic radius', 'Ionization energy and atomic radius both increase together', 'Smaller atoms tend to have higher ionization energies', 'Smaller atoms have higher nuclear charge relative to atomic size, so the outermost electrons are held more tightly and require more energy to remove.', 890, 'InorganicChemistry'),
('In a face-centred cubic (FCC) unit cell, how many atoms per unit cell are there in total?', '1', '2', '3', '4', '4', 'An FCC cell has 8 corner atoms (each shared by 8 cells, contributing 1/8) and 6 face atoms (each shared by 2 cells, contributing 1/2): 8*(1/8) + 6*(1/2) = 4 atoms per unit cell.', 1300, 'InorganicChemistry'),
('Which of the following ligands is a strong-field ligand that causes large crystal field splitting?', 'I-', 'Br-', 'CO', 'F-', 'CO', 'CO is a strong sigma-donor and pi-acceptor (pi-back bonding) ligand that produces large delta_o, placing it near the top of the spectrochemical series.', 1250, 'InorganicChemistry'),
('What is the formula of the complex formed when six water molecules coordinate to Fe3+?', '[Fe(H2O)6]2+', '[Fe(H2O)6]3+', '[Fe(H2O)3]3+', '[Fe(H2O)4]3+', '[Fe(H2O)6]3+', 'Fe3+ in aqueous solution is surrounded by six water molecule ligands in an octahedral arrangement, forming the hexaaquairon(III) cation [Fe(H2O)6]3+.', 950, 'InorganicChemistry'),
('Which of the following correctly ranks the bond lengths in CO, CO2, and CO3^2-?', 'CO < CO2 < CO3^2-', 'CO3^2- < CO2 < CO', 'CO2 < CO < CO3^2-', 'CO < CO3^2- < CO2', 'CO < CO2 < CO3^2-', 'Higher bond order corresponds to shorter bond length: CO (bond order 3) < CO2 (bond order 2) < CO3^2- (bond order 4/3 due to resonance).', 1550, 'InorganicChemistry'),
('Which of the following statements about the halogens (Group 17) is correct?', 'Fluorine is the weakest oxidising agent of the halogens', 'Fluorine is the strongest oxidising agent of the halogens', 'Iodine has higher electronegativity than fluorine', 'Chlorine can oxidise fluoride ions in solution', 'Fluorine is the strongest oxidising agent of the halogens', 'Fluorine''s high electronegativity and small size give it the greatest tendency to gain electrons, making it the strongest oxidising agent among the halogens.', 820, 'InorganicChemistry'),
('What is the correct electron configuration for the Cu2+ ion?', '[Ar] 3d10', '[Ar] 3d9', '[Ar] 3d8 4s1', '[Ar] 3d7 4s2', '[Ar] 3d9', 'Neutral Cu is [Ar] 3d10 4s1; losing two electrons removes the 4s1 electron and one 3d electron, giving Cu2+ the configuration [Ar] 3d9.', 1400, 'InorganicChemistry'),
('Which of the following describes the geometry and bond angles in BF3?', 'Trigonal pyramidal, ~107 degrees', 'Trigonal planar, 120 degrees', 'T-shaped, ~87 degrees', 'Tetrahedral, 109.5 degrees', 'Trigonal planar, 120 degrees', 'BF3 has three bonding pairs and no lone pairs on boron (only 6 electrons), giving a trigonal planar geometry with F-B-F angles of exactly 120 degrees.', 780, 'InorganicChemistry');
INSERT INTO organicchemistry (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('What functional group is characteristic of an aldehyde?', 'A terminal carbonyl (-CHO)', 'A hydroxyl (-OH)', 'A carboxyl (-COOH)', 'An amino (-NH2)', 'A terminal carbonyl (-CHO)', 'Aldehydes have a carbonyl carbon bonded to at least one hydrogen at the end of the chain (-CHO).', 740, 'OrganicChemistry'),
('Which hybridization state is found in the carbon atoms of ethene (CH2=CH2)?', 'sp^2', 'sp^3', 'sp', 'sp^3d', 'sp^2', 'Each carbon in ethene forms one pi bond and two sigma bonds to other atoms, requiring sp^2 hybridization and leaving one unhybridized p orbital for the pi bond.', 720, 'OrganicChemistry'),
('What is the IUPAC name for CH3-CH2-CH2-CH3?', 'Butane', 'Propane', 'Pentane', 'Isobutane', 'Butane', 'A straight-chain alkane with four carbons is named butane according to IUPAC rules.', 710, 'OrganicChemistry'),
('Which reagent selectively oxidizes a primary alcohol to an aldehyde without further oxidation to a carboxylic acid?', 'PCC (pyridinium chlorochromate)', 'KMnO4', 'LiAlH4', 'NaBH4', 'PCC (pyridinium chlorochromate)', 'PCC is a mild oxidant that stops oxidation at the aldehyde stage, unlike stronger reagents such as KMnO4 which can over-oxidize to carboxylic acid.', 1020, 'OrganicChemistry'),
('What does Markovnikov''s rule predict about the addition of HBr to propene?', '2-bromopropane is the major product', '1-bromopropane is the major product', 'Equal amounts of both products form', 'No reaction occurs', '2-bromopropane is the major product', 'Markovnikov''s rule states that the proton adds to the carbon bearing more hydrogens, placing the halide on the more substituted carbon to give the more stable carbocation intermediate.', 980, 'OrganicChemistry'),
('In an SN2 reaction, the nucleophile attacks from which direction relative to the leaving group?', '180 degrees (back-side attack)', '90 degrees', '0 degrees (front-side attack)', '45 degrees', '180 degrees (back-side attack)', 'SN2 proceeds via back-side attack, resulting in inversion of configuration (Walden inversion) at the stereogenic center.', 1050, 'OrganicChemistry'),
('Which of the following compounds exhibits optical activity (chirality)?', '2-bromobutane', 'Bromoethane', '1-bromobutane', 'Dibromomethane', '2-bromobutane', '2-bromobutane has four different substituents on C-2 (H, Br, CH3, CH2CH3), making it a chiral center capable of optical activity.', 1100, 'OrganicChemistry'),
('What is the major product of the dehydration of 2-methylbutan-2-ol?', '2-methylbut-2-ene', '2-methylbut-1-ene', '3-methylbut-1-ene', '1-methylbut-2-ene', '2-methylbut-2-ene', 'Zaitsev''s rule predicts formation of the most substituted (most stable) alkene; dehydration of 2-methylbutan-2-ol gives 2-methylbut-2-ene as the major product.', 1180, 'OrganicChemistry'),
('Which of the following is an aromatic compound according to Huckel''s rule?', 'Benzene (6 pi electrons)', 'Cyclobutadiene (4 pi electrons)', 'Cyclooctatetraene (8 pi electrons)', '1,3-butadiene (4 pi electrons)', 'Benzene (6 pi electrons)', 'Huckel''s rule requires 4n+2 pi electrons in a planar, fully conjugated cyclic system; benzene has 6 pi electrons (n=1), satisfying this criterion.', 1060, 'OrganicChemistry'),
('A Grignard reagent (RMgX) reacts with formaldehyde (HCHO) to give, after workup, which product?', 'A primary alcohol', 'A secondary alcohol', 'A tertiary alcohol', 'A carboxylic acid', 'A primary alcohol', 'Grignard reagents add to formaldehyde to place the R group on the carbonyl carbon; hydrolysis gives a primary alcohol (RCH2OH).', 1150, 'OrganicChemistry'),
('What is the relationship between (R)-lactic acid and (S)-lactic acid?', 'Enantiomers', 'Diastereomers', 'Constitutional isomers', 'Identical compounds', 'Enantiomers', 'Enantiomers are non-superimposable mirror images differing only in the spatial arrangement at every stereocenter; R and S lactic acid are a classic pair.', 1080, 'OrganicChemistry'),
('In electrophilic aromatic substitution (EAS), which group is an ortho/para director?', '-OH (hydroxyl)', '-NO2 (nitro)', '-CF3 (trifluoromethyl)', '-COOH (carboxyl)', '-OH (hydroxyl)', 'Electron-donating groups such as -OH activate the ring and direct incoming electrophiles to the ortho and para positions via resonance donation.', 1200, 'OrganicChemistry'),
('Which spectroscopic method is best for identifying a carbonyl group (C=O) in an unknown organic compound?', 'IR spectroscopy (strong absorption ~1700 cm-1)', 'UV-Vis spectroscopy', 'Mass spectrometry', '1H NMR spectroscopy', 'IR spectroscopy (strong absorption ~1700 cm-1)', 'The C=O stretching vibration gives a strong, characteristic IR absorption near 1700 cm-1, making IR the primary tool for carbonyl identification.', 900, 'OrganicChemistry'),
('What is the product when an alkene undergoes ozonolysis followed by reductive workup (Zn/H2O)?', 'Two carbonyl compounds (aldehydes or ketones)', 'Two carboxylic acids', 'An epoxide and a ketone', 'A diol', 'Two carbonyl compounds (aldehydes or ketones)', 'Ozonolysis cleaves the C=C double bond; reductive workup with Zn/H2O gives aldehydes or ketones, while oxidative workup (H2O2) gives carboxylic acids.', 1250, 'OrganicChemistry'),
('Which of the following alkenes undergoes the Diels-Alder reaction as the dienophile most readily?', 'Maleic anhydride', 'Ethene', '1,3-butadiene', 'Propene', 'Maleic anhydride', 'Electron-poor dienophiles react most readily in the Diels-Alder [4+2] cycloaddition; maleic anhydride bears two electron-withdrawing carbonyl groups that lower LUMO energy.', 1450, 'OrganicChemistry'),
('What is the IUPAC name for the compound CH3CH2OH?', 'Ethanol', 'Methanol', 'Propan-1-ol', 'Ethanal', 'Ethanol', 'Ethanol (ethyl alcohol) is a two-carbon chain with a hydroxyl group at carbon 1, named systematically as ethanol.', 700, 'OrganicChemistry'),
('In the E2 elimination reaction, what is the required geometric relationship between the leaving group and the beta-hydrogen?', 'Anti-periplanar (180 degrees)', 'Syn-periplanar (0 degrees)', 'Gauche (60 degrees)', 'Any orientation', 'Anti-periplanar (180 degrees)', 'E2 requires a concerted, one-step mechanism in which the base removes a beta-H that is anti-periplanar to the leaving group, enabling overlap of the developing pi bond.', 1380, 'OrganicChemistry'),
('Which reagent reduces a ketone to a secondary alcohol?', 'NaBH4', 'PCC', 'KMnO4', 'SOCl2', 'NaBH4', 'Sodium borohydride (NaBH4) is a mild hydride reducing agent that reduces ketones and aldehydes to alcohols but does not reduce esters or carboxylic acids under mild conditions.', 820, 'OrganicChemistry'),
('What term describes two compounds that are constitutional isomers?', 'Same molecular formula but different connectivity', 'Non-superimposable mirror images', 'Identical compounds', 'Differ only in rotation about a single bond', 'Same molecular formula but different connectivity', 'Constitutional (structural) isomers share the same molecular formula but have different atom connectivity, distinguishing them from stereoisomers.', 760, 'OrganicChemistry'),
('Which carbon hybridization gives a linear molecular geometry with bond angles of 180 degrees?', 'sp', 'sp^2', 'sp^3', 'sp^3d', 'sp', 'An sp-hybridized carbon forms two sigma bonds and two pi bonds (as in alkynes), adopting linear geometry with 180-degree bond angles.', 820, 'OrganicChemistry'),
('What is the general formula for a straight-chain alkane with n carbons?', 'CnH(2n+2)', 'CnH(2n)', 'CnH(2n-2)', 'CnHn', 'CnH(2n+2)', 'Saturated acyclic alkanes follow the general formula CnH(2n+2), derived by counting two hydrogens per carbon plus two terminal hydrogens.', 730, 'OrganicChemistry'),
('During nucleophilic addition of HCN to acetaldehyde (CH3CHO), the nucleophile is:', 'CN- (cyanide ion)', 'H+ (proton)', 'CH3- (methyl anion)', 'OH- (hydroxide)', 'CN- (cyanide ion)', 'In nucleophilic addition to carbonyl groups, the nucleophilic species (CN-) attacks the electrophilic carbonyl carbon, and the proton is added in a subsequent step.', 1160, 'OrganicChemistry'),
('What is the major product of treating 1-methylcyclohexanol with concentrated H2SO4 at elevated temperature?', '1-methylcyclohex-1-ene', 'Cyclohexanone', 'Methylenecyclohexane', '1-methylcyclohexyl sulfate', '1-methylcyclohex-1-ene', 'Acid-catalyzed dehydration follows Zaitsev''s rule, favoring the more substituted endocyclic alkene, 1-methylcyclohex-1-ene, over the less substituted exocyclic product.', 1320, 'OrganicChemistry'),
('Which term describes molecules that are non-superimposable mirror images of each other?', 'Enantiomers', 'Diastereomers', 'Meso compounds', 'Conformational isomers', 'Enantiomers', 'Enantiomers are the two non-superimposable mirror-image forms of a chiral molecule; they rotate plane-polarized light in equal but opposite directions.', 830, 'OrganicChemistry'),
('Identify the type of reaction when Br2 adds across the double bond of cyclohexene:', 'Electrophilic addition', 'Nucleophilic addition', 'Electrophilic substitution', 'Free-radical substitution', 'Electrophilic addition', 'Bromine (Br2) is an electrophile that adds across the pi bond of alkenes via a bromonium-ion intermediate, classifying the reaction as electrophilic addition.', 950, 'OrganicChemistry'),
('What does the term "resonance" describe in organic chemistry?', 'Delocalization of electrons across a conjugated system represented by multiple Lewis structures', 'The vibration frequency of a C=O bond', 'Rotation around a single bond', 'A type of isomerism involving ring vs. chain forms', 'Delocalization of electrons across a conjugated system represented by multiple Lewis structures', 'Resonance structures are alternative Lewis representations of the same molecule; the true electronic structure is a hybrid showing delocalized electron density.', 980, 'OrganicChemistry'),
('In NMR spectroscopy, what does chemical shift (delta, ppm) measure?', 'The resonance frequency of a nucleus relative to a reference standard (TMS)', 'The number of hydrogen atoms attached to a carbon', 'The spin multiplicity of a proton signal', 'The intensity of an IR absorption band', 'The resonance frequency of a nucleus relative to a reference standard (TMS)', 'Chemical shift in NMR reports how far a proton (or carbon) resonates from the TMS reference signal, reflecting the electronic environment of that nucleus.', 1050, 'OrganicChemistry'),
('Which of the following is a meso compound?', 'meso-Tartaric acid (2R,3S-tartaric acid)', '(R,R)-tartaric acid', '(S,S)-tartaric acid', '(R)-lactic acid', 'meso-Tartaric acid (2R,3S-tartaric acid)', 'A meso compound has stereocenters but is achiral overall because an internal plane of symmetry makes the two halves mirror images; 2R,3S-tartaric acid is the classic example.', 1400, 'OrganicChemistry'),
('What is the product of the complete combustion of a hydrocarbon?', 'CO2 and H2O', 'CO and H2O', 'CO2 and H2', 'C and H2O', 'CO2 and H2O', 'Complete combustion of any hydrocarbon in excess oxygen produces only carbon dioxide and water as products.', 700, 'OrganicChemistry'),
('Which mechanism operates in the solvolysis of a tertiary alkyl halide in aqueous ethanol?', 'SN1', 'SN2', 'E2', 'Free-radical substitution', 'SN1', 'Tertiary substrates form stable carbocations readily; solvolysis in polar protic solvents proceeds via a two-step SN1 mechanism through a planar carbocation intermediate.', 1100, 'OrganicChemistry'),
('What is the IUPAC name for (CH3)3C-OH?', '2-methylpropan-2-ol', '2-butanol', '1-butanol', 'tert-butyl ether', '2-methylpropan-2-ol', 'The compound has a four-carbon chain with a hydroxyl on the central carbon bearing three methyl groups; systematic IUPAC nomenclature gives 2-methylpropan-2-ol.', 960, 'OrganicChemistry'),
('Which reagent converts an alkene to an epoxide (oxirane)?', 'mCPBA (meta-chloroperoxybenzoic acid)', 'Br2 in CCl4', 'H2/Pd', 'OsO4', 'mCPBA (meta-chloroperoxybenzoic acid)', 'Peracids such as mCPBA deliver an oxygen atom to the alkene pi bond in a concerted syn-facial fashion to give an epoxide.', 1280, 'OrganicChemistry'),
('In the Diels-Alder reaction, the diene must adopt which conformation to react?', 's-cis conformation', 's-trans conformation', 'Boat conformation', 'Chair conformation', 's-cis conformation', 'The [4+2] cycloaddition requires the diene''s two double bonds to be in the s-cis conformation so that both terminal carbons can overlap with the dienophile simultaneously.', 1520, 'OrganicChemistry'),
('What is the term for the activation of the benzene ring toward EAS by electron-donating groups?', 'Ring activation (ring is more reactive than benzene)', 'Ring deactivation', 'Meta-direction', 'Aromaticity', 'Ring activation (ring is more reactive than benzene)', 'Electron-donating groups increase electron density on the aromatic ring, lowering the activation energy for electrophilic aromatic substitution and making the ring more reactive than unsubstituted benzene.', 1080, 'OrganicChemistry'),
('Which of the following carboxylic acid derivatives is the most reactive toward nucleophilic acyl substitution?', 'Acid chloride (acyl chloride)', 'Ester', 'Amide', 'Carboxylate anion', 'Acid chloride (acyl chloride)', 'Acid chlorides have the best leaving group (Cl-) and are therefore the most electrophilic and reactive carboxylic acid derivatives in nucleophilic acyl substitution.', 1350, 'OrganicChemistry'),
('What is the degree of unsaturation (index of hydrogen deficiency) for C6H6 (benzene)?', '4', '1', '3', '6', '4', 'The degree of unsaturation = (2*6 + 2 - 6)/2 = (14-6)/2 = 4; benzene has three double bonds and one ring, totaling 4 degrees of unsaturation.', 1200, 'OrganicChemistry'),
('In 1H NMR, what does signal splitting (n+1 rule) indicate?', 'The number of equivalent neighboring protons', 'The chemical shift of the proton', 'The number of carbons adjacent to the proton', 'The mass of the molecule', 'The number of equivalent neighboring protons', 'The n+1 multiplicity rule states that a proton with n equivalent neighboring protons splits into n+1 peaks (doublet, triplet, etc.) due to spin-spin coupling.', 1150, 'OrganicChemistry'),
('Which of the following correctly describes cis-2-butene vs. trans-2-butene?', 'They are geometric (cis/trans) stereoisomers (diastereomers)', 'They are enantiomers', 'They are constitutional isomers', 'They are the same compound', 'They are geometric (cis/trans) stereoisomers (diastereomers)', 'cis- and trans-2-butene differ in the spatial arrangement of substituents across the C=C double bond; they are diastereomers (specifically geometric isomers) because they are not mirror images.', 1020, 'OrganicChemistry'),
('Which test distinguishes an aldehyde from a ketone using a mild oxidizing agent?', 'Tollens'' test (silver mirror test)', 'Lucas test', 'Baeyer test', 'Iodoform test', 'Tollens'' test (silver mirror test)', 'Tollens'' reagent (Ag(NH3)2+) oxidizes aldehydes to carboxylate ions and deposits a silver mirror; ketones do not react because they lack the aldehyde hydrogen.', 1100, 'OrganicChemistry'),
('What is LiAlH4 commonly used for in organic synthesis?', 'Reducing esters, carboxylic acids, and amides to alcohols or amines', 'Oxidizing primary alcohols to aldehydes', 'Brominating aromatic rings', 'Hydrogenating alkenes', 'Reducing esters, carboxylic acids, and amides to alcohols or amines', 'Lithium aluminum hydride is a powerful hydride reductant capable of reducing all carbonyl-containing functional groups including esters, acids, and amides, unlike the milder NaBH4.', 1180, 'OrganicChemistry'),
('What is the correct assignment of configuration using the R/S system when the lowest-priority group (4) is pointing away from you?', 'Clockwise arrangement of groups 1->2->3 = R', 'Clockwise arrangement of groups 1->2->3 = S', 'Counterclockwise = R', 'Priority is unrelated to R/S assignment', 'Clockwise arrangement of groups 1->2->3 = R', 'With the lowest-priority group (4) pointing away, if priorities 1->2->3 trace a clockwise arc the center is R (rectus); counterclockwise is S (sinister).', 1380, 'OrganicChemistry'),
('Which compound is more acidic: acetic acid (pKa ~4.75) or ethanol (pKa ~16)?', 'Acetic acid', 'Ethanol', 'They are equally acidic', 'Neither is acidic', 'Acetic acid', 'Acetic acid is far more acidic than ethanol because its conjugate base (acetate) is stabilized by resonance delocalization of the negative charge across two oxygen atoms.', 1060, 'OrganicChemistry'),
('What product forms when propan-1-amine reacts with excess methyl iodide (CH3I)?', 'A quaternary ammonium salt', 'A primary amine', 'An amide', 'An imine', 'A quaternary ammonium salt', 'Repeated N-alkylation with excess alkyl halide converts a primary amine through secondary and tertiary amine stages to a quaternary ammonium salt.', 1480, 'OrganicChemistry'),
('What is the characteristic IR absorption for an O-H stretch in an alcohol?', 'Broad absorption around 3200-3550 cm-1', 'Sharp absorption around 1700 cm-1', 'Absorption around 2100 cm-1', 'Absorption around 1600 cm-1', 'Broad absorption around 3200-3550 cm-1', 'The O-H stretch in alcohols appears as a broad, strong band between 3200-3550 cm-1 due to hydrogen bonding, distinguishing it from C-H stretches.', 870, 'OrganicChemistry'),
('Which type of isomerism arises from restricted rotation about a C=C double bond?', 'Geometric (cis/trans) isomerism', 'Conformational isomerism', 'Constitutional isomerism', 'Tautomerism', 'Geometric (cis/trans) isomerism', 'The rigidity of the pi bond prevents rotation around C=C, giving rise to distinct cis (same side) and trans (opposite side) geometric isomers.', 830, 'OrganicChemistry'),
('Which reagent converts a terminal alkyne to a methyl ketone via Markovnikov hydration?', 'Hg2+/H2SO4/H2O (mercuric ion-catalyzed hydration)', 'R2BH then H2O2/NaOH (hydroboration-oxidation)', 'H2/Lindlar catalyst', 'O3 then Zn/H2O', 'Hg2+/H2SO4/H2O (mercuric ion-catalyzed hydration)', 'Mercuric-ion-catalyzed (Markovnikov) hydration of a terminal alkyne gives an enol that tautomerizes to a methyl ketone; the anti-Markovnikov aldehyde instead requires hydroboration-oxidation (R2BH then H2O2/NaOH).', 1600, 'OrganicChemistry'),
('Which of the following best explains why meta-directors in EAS are electron-withdrawing groups?', 'They destabilize the arenium ion intermediates at ortho/para positions more than at meta', 'They donate electrons to ortho/para positions', 'They form stable intermediates at the ortho position', 'They increase electron density at the meta position', 'They destabilize the arenium ion intermediates at ortho/para positions more than at meta', 'Electron-withdrawing groups bear a positive charge or partial positive charge adjacent to ortho/para carbons, destabilizing arenium ions at those positions more than at meta, so meta attack predominates.', 1700, 'OrganicChemistry'),
('What is the product when a carboxylic acid reacts with an alcohol in the presence of an acid catalyst?', 'An ester and water (Fischer esterification)', 'An amide and water', 'An aldehyde and water', 'A ketone and water', 'An ester and water (Fischer esterification)', 'Fischer esterification is the acid-catalyzed condensation of a carboxylic acid and alcohol to give an ester and water; the reaction is reversible and shifted by removing water or using excess alcohol.', 920, 'OrganicChemistry'),
('What is the IUPAC name for CH3-CO-CH2-CH3?', 'Butan-2-one', 'Butanal', 'Pentan-2-one', '2-butanol', 'Butan-2-one', 'The compound is a four-carbon ketone with the carbonyl at C-2; IUPAC nomenclature gives the name butan-2-one (also known as methyl ethyl ketone, MEK).', 960, 'OrganicChemistry'),
('Which reaction type converts benzene to nitrobenzene?', 'Electrophilic aromatic substitution using HNO3/H2SO4', 'Nucleophilic aromatic substitution', 'Free-radical halogenation', 'Diels-Alder cycloaddition', 'Electrophilic aromatic substitution using HNO3/H2SO4', 'Nitration of benzene is an EAS reaction in which H2SO4 protonates HNO3 to generate the nitronium ion (NO2+), which is the electrophile that substitutes one ring hydrogen.', 870, 'OrganicChemistry'),
('What distinguishes a primary, secondary, and tertiary carbon in an organic molecule?', 'The number of other carbon atoms directly attached to it (1, 2, or 3)', 'The number of hydrogen atoms attached to it', 'Whether the carbon is sp, sp^2, or sp^3 hybridized', 'The oxidation state of the carbon', 'The number of other carbon atoms directly attached to it (1, 2, or 3)', 'A primary carbon is bonded to one other carbon, a secondary to two, and a tertiary to three; this classification affects reactivity in substitution and elimination reactions.', 760, 'OrganicChemistry');
INSERT INTO astrophysics (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('Which type of star occupies the lower-left region of the Hertzsprung-Russell diagram?', 'Red giants', 'White dwarfs', 'Main-sequence O stars', 'Supergiants', 'White dwarfs', 'The lower-left corner corresponds to high temperature but low luminosity, characteristic of hot, small white dwarfs.', 720, 'Astrophysics'),
('What process powers a main-sequence star like the Sun?', 'Nuclear fission of uranium', 'Hydrogen fusion into helium', 'Gravitational contraction only', 'Helium fusion into carbon', 'Hydrogen fusion into helium', 'Main-sequence stars fuse hydrogen into helium in their cores via the proton-proton chain or CNO cycle.', 700, 'Astrophysics'),
('Wien''s displacement law relates a blackbody''s peak wavelength to which quantity?', 'Its luminosity', 'Its radius', 'Its temperature', 'Its mass', 'Its temperature', 'Wien''s law states the peak wavelength is inversely proportional to absolute temperature.', 760, 'Astrophysics'),
('The Stefan-Boltzmann law states that a blackbody''s radiated power per unit area scales as which power of temperature?', 'T', 'T squared', 'T cubed', 'T to the fourth', 'T to the fourth', 'The Stefan-Boltzmann law gives flux proportional to the fourth power of absolute temperature.', 820, 'Astrophysics'),
('What is the approximate value of the Chandrasekhar limit, the maximum mass of a white dwarf?', '0.5 solar masses', '1.4 solar masses', '3.0 solar masses', '8.0 solar masses', '1.4 solar masses', 'Above about 1.4 solar masses, electron degeneracy pressure cannot support a white dwarf, leading to collapse.', 900, 'Astrophysics'),
('Stellar parallax is used to measure what property of a star?', 'Its temperature', 'Its distance', 'Its chemical composition', 'Its rotation rate', 'Its distance', 'Parallax measures the apparent shift of a nearby star against background stars, giving its distance via trigonometry.', 740, 'Astrophysics'),
('A star with a parallax angle of 0.1 arcseconds is at what distance?', '1 parsec', '10 parsecs', '100 parsecs', '0.1 parsecs', '10 parsecs', 'Distance in parsecs equals the reciprocal of the parallax angle in arcseconds, so 1/0.1 = 10 pc.', 880, 'Astrophysics'),
('Kepler''s third law relates a planet''s orbital period to which orbital quantity?', 'Its eccentricity', 'Its semi-major axis', 'Its inclination', 'Its mass', 'Its semi-major axis', 'Kepler''s third law states the square of the period is proportional to the cube of the semi-major axis.', 800, 'Astrophysics'),
('In which direction are spectral lines shifted for an object moving away from the observer?', 'Toward the blue', 'Toward the red', 'No shift occurs', 'Toward the ultraviolet', 'Toward the red', 'Recession stretches the observed wavelengths, shifting spectral lines toward longer (redder) wavelengths.', 730, 'Astrophysics'),
('Hubble''s law expresses a linear relationship between a galaxy''s recession velocity and its what?', 'Mass', 'Distance', 'Temperature', 'Luminosity', 'Distance', 'Hubble''s law states recession velocity equals the Hubble constant times distance.', 770, 'Astrophysics'),
('The cosmic microwave background radiation has a blackbody temperature of approximately what value?', '2.7 K', '27 K', '270 K', '0.27 K', '2.7 K', 'The CMB is a near-perfect blackbody at about 2.725 K, the relic radiation from the early universe.', 850, 'Astrophysics'),
('What remnant is left after a massive star (above about 25 solar masses) undergoes core collapse?', 'A white dwarf', 'A neutron star', 'A black hole', 'A brown dwarf', 'A black hole', 'The most massive stellar cores exceed the neutron-star limit and collapse into black holes.', 920, 'Astrophysics'),
('The apparent magnitude scale is defined such that a difference of 5 magnitudes corresponds to what brightness ratio?', 'A factor of 5', 'A factor of 10', 'A factor of 100', 'A factor of 1000', 'A factor of 100', 'The magnitude system is logarithmic: 5 magnitudes corresponds to a brightness factor of exactly 100.', 950, 'Astrophysics'),
('Which series of hydrogen spectral lines lies in the visible part of the spectrum?', 'Lyman series', 'Balmer series', 'Paschen series', 'Brackett series', 'Balmer series', 'The Balmer series, with transitions ending on n=2, produces visible-wavelength hydrogen lines.', 870, 'Astrophysics'),
('What is the dominant source of pressure that supports a neutron star against gravity?', 'Thermal gas pressure', 'Radiation pressure', 'Neutron degeneracy pressure', 'Magnetic pressure', 'Neutron degeneracy pressure', 'Neutron stars are supported by neutron degeneracy pressure, a quantum effect from the Pauli exclusion principle.', 980, 'Astrophysics'),
('Spectral type O stars are characterized by being what compared to type M stars?', 'Cooler and redder', 'Hotter and bluer', 'Larger but cooler', 'Identical in temperature', 'Hotter and bluer', 'In the OBAFGKM sequence, O stars are the hottest and bluest, while M stars are the coolest and reddest.', 750, 'Astrophysics'),
('The flux received from a star decreases with distance according to which law?', 'Linearly with distance', 'Inverse-square with distance', 'Inverse-cube with distance', 'Exponentially with distance', 'Inverse-square with distance', 'Flux equals luminosity divided by the area of a sphere, giving an inverse-square dependence on distance.', 830, 'Astrophysics'),
('Approximately what fraction of the universe''s total energy density is attributed to dark energy?', 'About 5 percent', 'About 27 percent', 'About 68 percent', 'About 95 percent', 'About 68 percent', 'Current cosmological measurements assign roughly 68 percent of the energy density to dark energy.', 940, 'Astrophysics'),
('What is the escape velocity from the surface of a body of mass M and radius R proportional to?', 'The square root of M divided by R', 'M divided by R squared', 'M times R', 'The square root of R divided by M', 'The square root of M divided by R', 'Escape velocity equals the square root of 2GM/R, so it scales as the square root of M over R.', 1010, 'Astrophysics'),
('A type Ia supernova is used as a standard candle because it has a nearly constant what?', 'Color', 'Peak luminosity', 'Spectral type', 'Orbital period', 'Peak luminosity', 'Type Ia supernovae result from white dwarfs reaching the Chandrasekhar mass, giving a consistent peak luminosity.', 1060, 'Astrophysics'),
('The Schwarzschild radius of a black hole is proportional to which quantity?', 'The square of its mass', 'Its mass', 'The square root of its mass', 'The inverse of its mass', 'Its mass', 'The Schwarzschild radius equals 2GM/c squared, which is directly proportional to the mass.', 1080, 'Astrophysics'),
('What is the approximate surface temperature of the Sun''s photosphere?', '500 K', '5800 K', '58000 K', '580000 K', '5800 K', 'The Sun''s photosphere has an effective temperature of about 5800 K, giving its yellow-white color.', 720, 'Astrophysics'),
('Which observational evidence most directly supports the existence of dark matter in galaxies?', 'Flat galactic rotation curves', 'Redshift of distant quasars', 'The blackbody CMB spectrum', 'Solar neutrino flux', 'Flat galactic rotation curves', 'Rotation curves that stay flat at large radii imply unseen mass, attributed to dark matter halos.', 1120, 'Astrophysics'),
('In a Hertzsprung-Russell diagram, where do most stars spend the majority of their lives?', 'The white-dwarf region', 'The red-giant branch', 'The main sequence', 'The instability strip', 'The main sequence', 'Stars spend about 90 percent of their lifetimes on the main sequence fusing hydrogen in their cores.', 760, 'Astrophysics'),
('The redshift z of a distant galaxy is defined as the change in wavelength divided by what?', 'The observed wavelength', 'The rest (emitted) wavelength', 'The frequency', 'The speed of light', 'The rest (emitted) wavelength', 'Redshift z equals the observed minus emitted wavelength, divided by the emitted (rest) wavelength.', 890, 'Astrophysics'),
('What dimensionless quantity determines whether the universe is open, flat, or closed?', 'The Hubble constant', 'The density parameter Omega', 'The redshift', 'The cosmological redshift limit', 'The density parameter Omega', 'The density parameter Omega, the ratio of actual density to critical density, sets the geometry of the universe.', 1180, 'Astrophysics'),
('Helioseismology studies the Sun by analyzing what?', 'Solar neutrinos', 'Oscillations on the Sun''s surface', 'Sunspot colors', 'Coronal mass ejections', 'Oscillations on the Sun''s surface', 'Helioseismology uses acoustic oscillations of the solar surface to probe the Sun''s internal structure.', 1000, 'Astrophysics'),
('For two stars of equal radius, doubling the temperature changes the total luminosity by what factor?', 'A factor of 2', 'A factor of 4', 'A factor of 8', 'A factor of 16', 'A factor of 16', 'Luminosity scales as the fourth power of temperature, so doubling T multiplies luminosity by 2 to the fourth, or 16.', 1240, 'Astrophysics'),
('The proton-proton chain in the Sun ultimately converts four protons into one of what?', 'A carbon nucleus', 'A helium-4 nucleus', 'An iron nucleus', 'A deuterium nucleus', 'A helium-4 nucleus', 'The net result of the proton-proton chain is the fusion of four protons into a single helium-4 nucleus.', 870, 'Astrophysics'),
('What is the primary reason iron is the heaviest element produced by fusion in stellar cores?', 'Iron has the highest melting point', 'Iron has the highest binding energy per nucleon', 'Iron is the most abundant element', 'Iron resists gravitational collapse', 'Iron has the highest binding energy per nucleon', 'Fusion past iron consumes rather than releases energy because iron has the maximum binding energy per nucleon.', 1150, 'Astrophysics'),
('A Cepheid variable star is useful as a distance indicator because of which relationship?', 'A mass-radius relation', 'A period-luminosity relation', 'A color-temperature relation', 'A metallicity-age relation', 'A period-luminosity relation', 'Cepheids obey a tight period-luminosity relation, so their pulsation period reveals their intrinsic luminosity.', 1040, 'Astrophysics'),
('What is the approximate age of the universe according to standard cosmology?', '4.6 billion years', '13.8 billion years', '46 billion years', '1.38 billion years', '13.8 billion years', 'Measurements of the CMB and expansion rate give a universe age of about 13.8 billion years.', 750, 'Astrophysics'),
('Which star will have a shorter main-sequence lifetime?', 'A low-mass red dwarf', 'A high-mass blue star', 'A Sun-like star', 'A brown dwarf', 'A high-mass blue star', 'Massive stars burn fuel far faster than their gravitational binding supplies, giving very short main-sequence lifetimes.', 830, 'Astrophysics'),
('The luminosity of a main-sequence star scales approximately as which power of its mass?', 'The first power', 'The square', 'The cube', 'About the 3.5 power', 'About the 3.5 power', 'The mass-luminosity relation for main-sequence stars gives luminosity roughly proportional to mass to the 3.5 power.', 1130, 'Astrophysics'),
('What phenomenon causes the 21-cm radio line emitted by neutral hydrogen?', 'Electron orbital transitions', 'Hyperfine spin-flip of the electron', 'Vibrational molecular modes', 'Nuclear gamma decay', 'Hyperfine spin-flip of the electron', 'The 21-cm line arises from the hyperfine transition when the electron spin flips relative to the proton spin.', 1220, 'Astrophysics'),
('A star has an absolute magnitude of 5 and an apparent magnitude of 10. What is its distance modulus?', '15', '5', '2', '50', '5', 'The distance modulus is apparent minus absolute magnitude, so 10 minus 5 equals 5.', 990, 'Astrophysics'),
('Using the distance modulus of 5, what is the distance to the star?', '10 parsecs', '100 parsecs', '1000 parsecs', '5 parsecs', '100 parsecs', 'A distance modulus of 5 corresponds to 10 to the power (5/5 + 1) = 10 to the 2 = 100 parsecs.', 1360, 'Astrophysics'),
('What distinguishes an active galactic nucleus from a normal galactic center?', 'It contains only old stars', 'It emits enormous luminosity from a compact region', 'It lacks a central black hole', 'It is always blueshifted', 'It emits enormous luminosity from a compact region', 'An AGN releases huge luminosity from a tiny central region, powered by accretion onto a supermassive black hole.', 1190, 'Astrophysics'),
('The Roche limit defines the distance within which what happens to an orbiting body?', 'It is captured into a stable orbit', 'It is tidally disrupted', 'It gains angular momentum', 'It reaches escape velocity', 'It is tidally disrupted', 'Inside the Roche limit, tidal forces exceed the body''s self-gravity, tearing it apart.', 1080, 'Astrophysics'),
('What is the approximate peak wavelength of the Sun''s emission given its surface temperature?', '50 nanometers', '500 nanometers', '5000 nanometers', '5 nanometers', '500 nanometers', 'Applying Wien''s law to about 5800 K gives a peak near 500 nm, in the visible green region.', 1280, 'Astrophysics'),
('Which fundamental observation provides direct evidence for the Big Bang nucleosynthesis model?', 'The observed abundance of light elements', 'The rotation of spiral galaxies', 'The existence of pulsars', 'The solar wind composition', 'The observed abundance of light elements', 'The predicted primordial abundances of hydrogen, helium, and lithium match observations, supporting Big Bang nucleosynthesis.', 1310, 'Astrophysics'),
('A spectral absorption line observed at 660 nm has a rest wavelength of 656 nm. What is the redshift z?', 'About 0.006', 'About 0.06', 'About 0.6', 'About 6', 'About 0.006', 'Redshift z equals (660 minus 656) divided by 656, which is about 0.006.', 1340, 'Astrophysics'),
('What is the dominant energy-transport mechanism in the outer layers of a Sun-like star?', 'Radiation', 'Convection', 'Conduction', 'Neutrino emission', 'Convection', 'The cooler, more opaque outer envelope of a Sun-like star transports energy primarily by convection.', 940, 'Astrophysics'),
('The critical density of the universe depends most directly on which quantity?', 'The CMB temperature', 'The Hubble constant', 'The redshift of the most distant galaxy', 'The mass of the Milky Way', 'The Hubble constant', 'The critical density is proportional to the square of the Hubble constant, divided by the gravitational constant.', 1290, 'Astrophysics'),
('Gravitational lensing of distant light by intervening mass is a prediction of which theory?', 'Newtonian gravity', 'General relativity', 'Quantum electrodynamics', 'Special relativity alone', 'General relativity', 'General relativity predicts that mass curves spacetime, bending the paths of passing light rays.', 990, 'Astrophysics'),
('During the red-giant phase, what is happening in the core of a low-mass star like the Sun?', 'Hydrogen fuses in the core', 'The inert helium core contracts while hydrogen burns in a shell', 'Iron is being produced', 'The core has become a black hole', 'The inert helium core contracts while hydrogen burns in a shell', 'In the red-giant phase the helium core is inert and contracting while hydrogen fuses in a surrounding shell.', 1170, 'Astrophysics'),
('Two stars have the same temperature, but star A is 100 times more luminous than star B. How do their radii compare?', 'A is 100 times larger', 'A is 10 times larger', 'A is the same size', 'A is 10000 times larger', 'A is 10 times larger', 'At fixed temperature luminosity scales as radius squared, so a factor of 100 in luminosity means a factor of 10 in radius.', 1420, 'Astrophysics'),
('What is the main observational signature used to detect a stellar-mass black hole in a binary system?', 'Direct imaging of the black hole', 'X-rays from an accretion disk and orbital motion of the companion', 'Strong optical emission lines from the hole', 'Periodic radio pulses from the hole', 'X-rays from an accretion disk and orbital motion of the companion', 'Matter from a companion forms a hot accretion disk emitting X-rays, while the companion''s orbit reveals the unseen mass.', 1500, 'Astrophysics'),
('A galaxy recedes at 7000 km/s. Using a Hubble constant of 70 km/s per Mpc, what is its distance?', '10 Mpc', '100 Mpc', '1000 Mpc', '7 Mpc', '100 Mpc', 'Distance equals velocity divided by the Hubble constant, so 7000 divided by 70 equals 100 Mpc.', 1380, 'Astrophysics'),
('Compute the Schwarzschild radius of a 10-solar-mass black hole, given that one solar mass gives about 3 km.', 'About 3 km', 'About 30 km', 'About 300 km', 'About 0.3 km', 'About 30 km', 'The Schwarzschild radius scales linearly with mass, so 10 solar masses gives about 10 times 3 km, or roughly 30 km.', 1640, 'Astrophysics');
INSERT INTO electromagnetics (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('What is the SI unit of electric charge?', 'Coulomb', 'Ampere', 'Volt', 'Farad', 'Coulomb', 'Electric charge is measured in coulombs (C) in the SI system.', 710, 'Electromagnetics'),
('Coulomb''s law states that the electrostatic force between two charges is proportional to what?', 'The product of the charges divided by the square of their separation', 'The sum of the charges', 'The square of the separation', 'The product of the charges times the separation', 'The product of the charges divided by the square of their separation', 'Coulomb''s law gives F = k*q1*q2/r^2, an inverse-square relationship.', 880, 'Electromagnetics'),
('What is the SI unit of electric field strength?', 'Volt per meter', 'Newton per coulomb squared', 'Tesla', 'Weber', 'Volt per meter', 'Electric field is volts per meter (V/m), equivalent to newtons per coulomb.', 750, 'Electromagnetics'),
('Gauss''s law relates the electric flux through a closed surface to what?', 'The enclosed charge divided by the permittivity', 'The surface area', 'The electric potential', 'The enclosed current', 'The enclosed charge divided by the permittivity', 'Gauss''s law states the net flux equals Q_enclosed divided by epsilon-zero.', 1050, 'Electromagnetics'),
('The electric field inside an ideal conductor in electrostatic equilibrium is?', 'Zero', 'Uniform and nonzero', 'Equal to the surface field', 'Infinite', 'Zero', 'Charges rearrange until the interior field is zero in electrostatic equilibrium.', 920, 'Electromagnetics'),
('What is the approximate value of the permittivity of free space epsilon-zero?', '8.85e-12 F/m', '8.99e9 F/m', '1.26e-6 F/m', '6.63e-34 F/m', '8.85e-12 F/m', 'The permittivity of free space is about 8.85 x 10^-12 farads per meter.', 980, 'Electromagnetics'),
('The electric potential energy of a charge q at potential V is given by?', 'qV', 'q/V', 'V/q', 'q^2*V', 'qV', 'Potential energy equals charge times potential, U = qV.', 820, 'Electromagnetics'),
('What is the capacitance of a parallel-plate capacitor?', 'epsilon*A/d', 'epsilon*d/A', 'A/(epsilon*d)', 'd/(epsilon*A)', 'epsilon*A/d', 'For parallel plates C = epsilon*A/d, with area A and separation d.', 1120, 'Electromagnetics'),
('Inserting a dielectric of constant k between capacitor plates does what to capacitance?', 'Increases it by a factor of k', 'Decreases it by a factor of k', 'Leaves it unchanged', 'Makes it zero', 'Increases it by a factor of k', 'A dielectric of constant k raises capacitance to C = k*C0.', 1080, 'Electromagnetics'),
('The energy stored in a capacitor of capacitance C charged to voltage V is?', '0.5*C*V^2', 'C*V', '0.5*C*V', 'C*V^2', '0.5*C*V^2', 'The stored energy is U = (1/2)CV^2.', 1010, 'Electromagnetics'),
('Ohm''s law relating voltage, current, and resistance is?', 'V = IR', 'V = I/R', 'V = R/I', 'I = VR', 'V = IR', 'Ohm''s law states voltage equals current times resistance, V = IR.', 700, 'Electromagnetics'),
('Electrical power dissipated in a resistor can be written as?', 'I^2*R', 'I*R^2', 'I/R', 'R/I^2', 'I^2*R', 'Power dissipated is P = I^2*R, also equal to VI or V^2/R.', 860, 'Electromagnetics'),
('The resistance of a wire is proportional to its length and inversely proportional to what?', 'Cross-sectional area', 'Resistivity', 'Temperature', 'Voltage', 'Cross-sectional area', 'Resistance R = rho*L/A, inversely proportional to area A.', 900, 'Electromagnetics'),
('What is the SI unit of magnetic flux density?', 'Tesla', 'Weber', 'Henry', 'Gauss', 'Tesla', 'Magnetic flux density (B field) is measured in teslas (T).', 740, 'Electromagnetics'),
('The Lorentz force on a charge q moving with velocity v in field B is?', 'qv x B', 'qB/v', 'q(v dot B)', 'qvB^2', 'qv x B', 'The magnetic force is F = qv x B, perpendicular to both v and B.', 1090, 'Electromagnetics'),
('The Biot-Savart law is used to compute what?', 'The magnetic field from a current element', 'The electric field from a charge', 'The capacitance of a plate', 'The resistance of a wire', 'The magnetic field from a current element', 'The Biot-Savart law gives dB from a current element I*dl.', 1180, 'Electromagnetics'),
('Ampere''s law relates the line integral of B around a closed loop to what?', 'The enclosed current times mu-zero', 'The enclosed charge', 'The magnetic flux', 'The electric potential', 'The enclosed current times mu-zero', 'Ampere''s law states the closed line integral of B equals mu-zero times I_enclosed.', 1220, 'Electromagnetics'),
('The magnetic field at the center of a long solenoid with n turns per meter and current I is?', 'mu-zero*n*I', 'mu-zero*I/n', 'mu-zero*n/I', 'n*I/mu-zero', 'mu-zero*n*I', 'Inside an ideal solenoid B = mu-zero*n*I, uniform and axial.', 1310, 'Electromagnetics'),
('Faraday''s law of induction states that the induced EMF equals what?', 'The negative rate of change of magnetic flux', 'The magnetic flux itself', 'The rate of change of current', 'The product of B and area', 'The negative rate of change of magnetic flux', 'Faraday''s law gives EMF = -d(flux)/dt.', 1150, 'Electromagnetics'),
('Lenz''s law determines what about an induced current?', 'Its direction opposes the change in flux', 'Its magnitude only', 'Its frequency', 'That it is always zero', 'Its direction opposes the change in flux', 'Lenz''s law states the induced current opposes the flux change that caused it.', 1130, 'Electromagnetics'),
('What is the SI unit of inductance?', 'Henry', 'Farad', 'Tesla', 'Weber', 'Henry', 'Inductance is measured in henries (H).', 720, 'Electromagnetics'),
('The energy stored in an inductor carrying current I is?', '0.5*L*I^2', 'L*I', '0.5*L*I', 'L*I^2', '0.5*L*I^2', 'The magnetic energy stored is U = (1/2)L*I^2.', 1020, 'Electromagnetics'),
('How many equations comprise Maxwell''s equations?', 'Four', 'Two', 'Three', 'Five', 'Four', 'Maxwell''s equations are a set of four fundamental equations.', 760, 'Electromagnetics'),
('Which Maxwell equation states that there are no magnetic monopoles?', 'Divergence of B equals zero', 'Divergence of E equals rho over epsilon', 'Curl of E equals minus dB/dt', 'Curl of B equals mu*J', 'Divergence of B equals zero', 'The law div B = 0 means magnetic field lines have no sources or sinks.', 1280, 'Electromagnetics'),
('The displacement current term was added by Maxwell to which law?', 'Ampere''s law', 'Faraday''s law', 'Gauss''s law for electricity', 'Coulomb''s law', 'Ampere''s law', 'Maxwell added the displacement current epsilon*dE/dt to Ampere''s law.', 1420, 'Electromagnetics'),
('In differential form, Faraday''s law is written as?', 'curl E = -dB/dt', 'div E = rho/epsilon', 'curl B = mu*J', 'div B = 0', 'curl E = -dB/dt', 'Faraday''s law in differential form is curl E = -partial B / partial t.', 1390, 'Electromagnetics'),
('The speed of electromagnetic waves in vacuum is given by?', '1/sqrt(mu-zero*epsilon-zero)', 'sqrt(mu-zero*epsilon-zero)', 'mu-zero*epsilon-zero', '1/(mu-zero*epsilon-zero)', '1/sqrt(mu-zero*epsilon-zero)', 'The wave speed c = 1/sqrt(mu0*eps0) equals about 3 x 10^8 m/s.', 1450, 'Electromagnetics'),
('In an electromagnetic wave in vacuum, the ratio of the electric field to the magnetic field magnitude is?', 'The speed of light c', 'Unity', 'The permittivity', 'The frequency', 'The speed of light c', 'For an EM wave in vacuum E/B = c.', 1370, 'Electromagnetics'),
('The Poynting vector represents what physical quantity?', 'Energy flux per unit area', 'Electric charge density', 'Magnetic flux', 'Electric potential', 'Energy flux per unit area', 'The Poynting vector S = E x B / mu0 gives power per unit area of an EM wave.', 1480, 'Electromagnetics'),
('In an electromagnetic plane wave the E and B fields are oriented how relative to each other?', 'Mutually perpendicular and both transverse to propagation', 'Parallel to each other', 'Antiparallel', 'Both along the propagation direction', 'Mutually perpendicular and both transverse to propagation', 'In a plane EM wave E, B, and the propagation direction are mutually perpendicular.', 1340, 'Electromagnetics'),
('Polarization of light refers to what property?', 'The orientation of the electric field oscillations', 'The frequency of the wave', 'The intensity of the wave', 'The speed of the wave', 'The orientation of the electric field oscillations', 'Polarization describes the direction in which the electric field oscillates.', 1160, 'Electromagnetics'),
('In an RC circuit, the time constant is given by?', 'RC', 'R/C', 'C/R', '1/(RC)', 'RC', 'The RC time constant tau = R*C governs charging and discharging.', 940, 'Electromagnetics'),
('In an RL circuit, the time constant is given by?', 'L/R', 'RL', 'R/L', '1/(RL)', 'L/R', 'The RL time constant tau = L/R sets the current rise time.', 1070, 'Electromagnetics'),
('The resonant angular frequency of an LC circuit is?', '1/sqrt(LC)', 'sqrt(LC)', 'LC', '1/(LC)', '1/sqrt(LC)', 'An LC circuit resonates at omega = 1/sqrt(L*C).', 1290, 'Electromagnetics'),
('The capacitive reactance of a capacitor at angular frequency omega is?', '1/(omega*C)', 'omega*C', 'omega/C', 'omega*C^2', '1/(omega*C)', 'Capacitive reactance Xc = 1/(omega*C) decreases with frequency.', 1240, 'Electromagnetics'),
('The inductive reactance of an inductor at angular frequency omega is?', 'omega*L', '1/(omega*L)', 'L/omega', 'omega/L', 'omega*L', 'Inductive reactance XL = omega*L increases with frequency.', 1210, 'Electromagnetics'),
('Two point charges of +2 microcoulombs and +3 microcoulombs are 1 meter apart. The force between them is approximately?', '0.054 N', '0.027 N', '0.108 N', '5.4 N', '0.054 N', 'F = k*q1*q2/r^2 = 9e9 * 2e-6 * 3e-6 / 1 = 0.054 N.', 1560, 'Electromagnetics'),
('A 10 microfarad capacitor is charged to 100 volts. The stored energy is?', '0.05 J', '0.5 J', '0.005 J', '1.0 J', '0.05 J', 'U = 0.5*C*V^2 = 0.5*10e-6*100^2 = 0.05 J.', 1520, 'Electromagnetics'),
('A solenoid has 1000 turns per meter and carries 2 A. The interior field is approximately?', '2.5e-3 T', '2.5e-6 T', '0.25 T', '2.5 T', '2.5e-3 T', 'B = mu0*n*I = 4pi e-7 * 1000 * 2 ~ 2.5e-3 T.', 1640, 'Electromagnetics'),
('A circular loop of area 0.1 m^2 in a field changing at 0.5 T/s has an induced EMF of?', '0.05 V', '0.5 V', '0.005 V', '5 V', '0.05 V', 'EMF = -A*dB/dt = 0.1 * 0.5 = 0.05 V in magnitude.', 1580, 'Electromagnetics'),
('The work done to move a 2 C charge through a potential difference of 12 V is?', '24 J', '6 J', '14 J', '0.17 J', '24 J', 'W = q*V = 2 * 12 = 24 joules.', 1310, 'Electromagnetics'),
('A 5 ohm and a 10 ohm resistor in parallel have an equivalent resistance of?', '3.33 ohms', '15 ohms', '7.5 ohms', '2 ohms', '3.33 ohms', 'For parallel resistors 1/R = 1/5 + 1/10, giving R = 10/3 ~ 3.33 ohms.', 1350, 'Electromagnetics'),
('A proton moving at 1e6 m/s perpendicular to a 0.5 T field feels a force of about?', '8.0e-14 N', '8.0e-13 N', '1.6e-19 N', '5.0e5 N', '8.0e-14 N', 'F = qvB = 1.6e-19 * 1e6 * 0.5 = 8.0e-14 N.', 1720, 'Electromagnetics'),
('A long straight wire carries 10 A. The magnetic field 0.05 m away is approximately?', '4.0e-5 T', '4.0e-4 T', '2.0e-5 T', '4.0e-6 T', '4.0e-5 T', 'B = mu0*I/(2*pi*r) = 2e-7 * 10 / 0.05 = 4.0e-5 T.', 1780, 'Electromagnetics'),
('An EM wave has a peak electric field of 300 V/m. Its peak magnetic field is approximately?', '1.0e-6 T', '1.0e-3 T', '9.0e10 T', '300 T', '1.0e-6 T', 'B = E/c = 300 / 3e8 = 1.0e-6 T.', 1690, 'Electromagnetics'),
('The average intensity of an EM wave equals the time-averaged magnitude of which quantity?', 'The Poynting vector', 'The electric field', 'The magnetic flux', 'The displacement current', 'The Poynting vector', 'Wave intensity is the time-averaged Poynting vector magnitude.', 1430, 'Electromagnetics'),
('Gauss''s law in differential form is written as?', 'div E = rho/epsilon-zero', 'curl E = -dB/dt', 'div B = 0', 'curl B = mu*J', 'div E = rho/epsilon-zero', 'In differential form Gauss''s law reads div E = rho/epsilon-zero.', 1400, 'Electromagnetics'),
('A series RLC circuit is driven at resonance. At resonance the impedance is?', 'Purely resistive and minimum', 'Purely capacitive', 'Purely inductive', 'Maximum and infinite', 'Purely resistive and minimum', 'At resonance XL equals XC, so the impedance is purely resistive and minimal.', 1660, 'Electromagnetics'),
('The magnetic dipole moment of a current loop equals?', 'Current times loop area', 'Current divided by area', 'Charge times velocity', 'Area divided by current', 'Current times loop area', 'A current loop has magnetic moment m = I*A.', 1470, 'Electromagnetics'),
('Three equal capacitors C in series give a total capacitance of?', 'C/3', '3C', 'C', '9C', 'C/3', 'For series capacitors 1/C_total = 3/C, so C_total = C/3.', 1850, 'Electromagnetics');
INSERT INTO quantummechanics (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('Which experiment first demonstrated the particle nature of light by ejecting electrons from a metal surface?', 'Double-slit experiment', 'Photoelectric effect', 'Compton scattering', 'Stern-Gerlach experiment', 'Photoelectric effect', 'The photoelectric effect showed light delivers energy in discrete quanta (photons) that eject electrons.', 720, 'QuantumMechanics'),
('What is the approximate value of Planck''s constant h?', '6.63 x 10^-34 J*s', '3.00 x 10^8 J*s', '1.60 x 10^-19 J*s', '9.11 x 10^-31 J*s', '6.63 x 10^-34 J*s', 'Planck''s constant h is approximately 6.626 x 10^-34 joule-seconds.', 700, 'QuantumMechanics'),
('The de Broglie wavelength of a particle is given by which relation?', 'lambda = h/p', 'lambda = hp', 'lambda = p/h', 'lambda = h*c/p', 'lambda = h/p', 'The de Broglie wavelength equals Planck''s constant divided by momentum, lambda = h/p.', 760, 'QuantumMechanics'),
('In the Bohr model, the angular momentum of an electron is quantized in units of what?', 'h-bar', 'h', 'h^2', 'kT', 'h-bar', 'Bohr postulated angular momentum is quantized as L = n*h-bar (h/2pi).', 820, 'QuantumMechanics'),
('What does the square of the magnitude of the wavefunction, |psi|^2, represent?', 'Probability density', 'Total energy', 'Momentum', 'Phase velocity', 'Probability density', '|psi|^2 gives the probability density of finding the particle at a given position.', 780, 'QuantumMechanics'),
('Which principle states that the position and momentum of a particle cannot both be known with arbitrary precision?', 'Pauli exclusion principle', 'Heisenberg''s uncertainty principle', 'Correspondence principle', 'Aufbau principle', 'Heisenberg''s uncertainty principle', 'Heisenberg''s uncertainty principle limits simultaneous precision of position and momentum.', 800, 'QuantumMechanics'),
('What type of operator must correspond to a physical observable in quantum mechanics?', 'Hermitian', 'Unitary', 'Skew-symmetric', 'Singular', 'Hermitian', 'Observables are represented by Hermitian operators because their eigenvalues are real.', 980, 'QuantumMechanics'),
('The Pauli exclusion principle states that no two identical fermions can occupy the same what?', 'Quantum state', 'Orbital shape', 'Energy band', 'Spin axis', 'Quantum state', 'Two identical fermions cannot share the same set of quantum numbers (same quantum state).', 760, 'QuantumMechanics'),
('What is the spin quantum number of an electron?', '1/2', '0', '1', '3/2', '1/2', 'Electrons are spin-1/2 fermions, with spin quantum number s = 1/2.', 740, 'QuantumMechanics'),
('Blackbody radiation could not be explained classically due to which paradox?', 'Ultraviolet catastrophe', 'Twin paradox', 'EPR paradox', 'Olbers'' paradox', 'Ultraviolet catastrophe', 'Classical theory predicted infinite energy at short wavelengths, the ultraviolet catastrophe, resolved by Planck.', 900, 'QuantumMechanics'),
('For a particle in a 1D infinite square well, the energy levels scale as which power of the quantum number n?', 'n^2', 'n', '1/n', 'n^3', 'n^2', 'Particle-in-a-box energies are E_n = n^2 pi^2 h-bar^2 / (2mL^2), proportional to n^2.', 1100, 'QuantumMechanics'),
('What is the ground-state energy of the quantum harmonic oscillator?', '(1/2) h-bar omega', 'h-bar omega', '0', '(3/2) h-bar omega', '(1/2) h-bar omega', 'The harmonic oscillator has zero-point energy E_0 = (1/2) h-bar omega.', 1150, 'QuantumMechanics'),
('The phenomenon where a particle passes through a potential barrier it classically could not surmount is called what?', 'Quantum tunneling', 'Resonance', 'Diffraction', 'Annihilation', 'Quantum tunneling', 'Quantum tunneling allows a particle to penetrate and cross a classically forbidden barrier.', 950, 'QuantumMechanics'),
('Which quantum number determines the shape of an atomic orbital?', 'Azimuthal (l)', 'Principal (n)', 'Magnetic (m_l)', 'Spin (m_s)', 'Azimuthal (l)', 'The azimuthal (angular momentum) quantum number l determines orbital shape (s, p, d, f).', 880, 'QuantumMechanics'),
('The commutator [x, p] of position and momentum operators equals what?', 'i*h-bar', '0', 'h-bar', '-i*h-bar', 'i*h-bar', 'The canonical commutation relation is [x, p] = i*h-bar.', 1200, 'QuantumMechanics'),
('Which equation describes the time evolution of a quantum state?', 'Time-dependent Schrodinger equation', 'Maxwell''s equations', 'Navier-Stokes equation', 'Dirac''s field equation', 'Time-dependent Schrodinger equation', 'The time-dependent Schrodinger equation governs how a quantum state evolves in time.', 860, 'QuantumMechanics'),
('Normalization of a wavefunction requires that the integral of |psi|^2 over all space equals what?', '1', '0', 'infinity', 'h-bar', '1', 'Normalization ensures total probability is 1: the integral of |psi|^2 over all space equals 1.', 940, 'QuantumMechanics'),
('What is the energy of a photon with frequency f?', 'E = h*f', 'E = h/f', 'E = f/h', 'E = h*f^2', 'E = h*f', 'Photon energy is E = h*f, Planck''s constant times frequency.', 720, 'QuantumMechanics'),
('In Dirac notation, the inner product of states is written as which expression?', '<phi|psi>', '|psi><phi|', '|psi>', '<psi|', '<phi|psi>', 'The bra-ket <phi|psi> denotes the inner product (overlap) of two states.', 1000, 'QuantumMechanics'),
('Two observables can be measured simultaneously with arbitrary precision only if their operators do what?', 'Commute', 'Anticommute', 'Are unitary', 'Are degenerate', 'Commute', 'Compatible observables have commuting operators ([A,B]=0) and share eigenstates.', 1250, 'QuantumMechanics'),
('What does the principal quantum number n primarily determine for a hydrogen atom?', 'Energy level', 'Orbital orientation', 'Spin direction', 'Number of nodes only', 'Energy level', 'For hydrogen, the principal quantum number n sets the energy E_n = -13.6 eV / n^2.', 900, 'QuantumMechanics'),
('The ground-state energy of the hydrogen atom is approximately what?', '-13.6 eV', '-3.4 eV', '+13.6 eV', '-1.5 eV', '-13.6 eV', 'Hydrogen''s ground state (n=1) has energy -13.6 eV.', 1000, 'QuantumMechanics'),
('Superposition in quantum mechanics means a system can exist as what?', 'A linear combination of eigenstates', 'A single fixed state only', 'A classical mixture', 'A point particle only', 'A linear combination of eigenstates', 'A quantum state can be a linear superposition of multiple eigenstates until measured.', 1050, 'QuantumMechanics'),
('When a measurement is made, the wavefunction is said to do what?', 'Collapse to an eigenstate', 'Double in amplitude', 'Become time-independent', 'Lose all energy', 'Collapse to an eigenstate', 'Measurement collapses the superposition onto an eigenstate of the measured observable.', 1100, 'QuantumMechanics'),
('Which scientist proposed that matter exhibits wave-like properties?', 'Louis de Broglie', 'Isaac Newton', 'James Clerk Maxwell', 'Ernest Rutherford', 'Louis de Broglie', 'Louis de Broglie proposed matter waves, assigning a wavelength to particles.', 780, 'QuantumMechanics'),
('The eigenvalues of a Hermitian operator are always what?', 'Real', 'Imaginary', 'Negative', 'Complex with nonzero imaginary part', 'Real', 'Hermitian operators have real eigenvalues, matching measurable physical quantities.', 1150, 'QuantumMechanics'),
('What is the expectation value of position for a symmetric wavefunction centered at the origin?', '0', 'L/2', 'infinity', 'h-bar', '0', 'For a wavefunction symmetric about the origin, the expectation value of x is 0.', 1300, 'QuantumMechanics'),
('The number of allowed m_l values for a given azimuthal quantum number l is what?', '2l + 1', 'l', 'l^2', 'n^2', '2l + 1', 'The magnetic quantum number m_l ranges from -l to +l, giving 2l+1 values.', 1200, 'QuantumMechanics'),
('Compton scattering provides evidence for what property of photons?', 'Momentum', 'Zero mass only', 'Negative charge', 'Spin zero', 'Momentum', 'Compton scattering shows photons carry momentum p = h/lambda, shifting X-ray wavelengths.', 1050, 'QuantumMechanics'),
('In the time-independent Schrodinger equation H*psi = E*psi, E represents what?', 'Energy eigenvalue', 'Momentum operator', 'Time', 'Probability', 'Energy eigenvalue', 'The time-independent Schrodinger equation is an eigenvalue equation with E the energy eigenvalue.', 1100, 'QuantumMechanics'),
('A node in a wavefunction is a location where the probability density is what?', 'Zero', 'Maximum', 'Negative', 'Constant', 'Zero', 'At a node the wavefunction is zero, so the probability density |psi|^2 vanishes there.', 920, 'QuantumMechanics'),
('What is the de Broglie wavelength of an electron with momentum 6.63 x 10^-24 kg*m/s?', '1.0 x 10^-10 m', '1.0 x 10^-34 m', '6.63 x 10^-24 m', '3.0 x 10^8 m', '1.0 x 10^-10 m', 'lambda = h/p = 6.63e-34 / 6.63e-24 = 1.0 x 10^-10 m.', 1450, 'QuantumMechanics'),
('Which set of operators describes the raising and lowering of harmonic oscillator states?', 'Ladder (creation/annihilation) operators', 'Pauli matrices', 'Rotation operators', 'Projection operators', 'Ladder (creation/annihilation) operators', 'Creation and annihilation (ladder) operators raise and lower harmonic oscillator energy levels.', 1500, 'QuantumMechanics'),
('The Heisenberg uncertainty relation is most often written as which inequality?', 'delta_x * delta_p >= h-bar/2', 'delta_x * delta_p <= h-bar/2', 'delta_x + delta_p >= h-bar', 'delta_x / delta_p >= h-bar', 'delta_x * delta_p >= h-bar/2', 'The uncertainty principle states delta_x * delta_p >= h-bar/2.', 1250, 'QuantumMechanics'),
('For the hydrogen atom, the energy of the n=2 level is approximately what?', '-3.4 eV', '-13.6 eV', '-6.8 eV', '-1.5 eV', '-3.4 eV', 'E_2 = -13.6 / 2^2 = -3.4 eV.', 1350, 'QuantumMechanics'),
('What is the maximum number of electrons in a shell with principal quantum number n?', '2n^2', 'n^2', '2n', '4n', '2n^2', 'A shell holds at most 2n^2 electrons, accounting for orbitals and spin.', 1200, 'QuantumMechanics'),
('A free particle is best represented by which type of wavefunction?', 'Plane wave', 'Gaussian fixed in place', 'Delta function', 'Constant zero', 'Plane wave', 'A free particle of definite momentum is described by a plane wave e^(ikx).', 1300, 'QuantumMechanics'),
('Which particles are subject to the Pauli exclusion principle?', 'Fermions', 'Bosons', 'Photons', 'Phonons', 'Fermions', 'The Pauli exclusion principle applies to fermions (half-integer spin particles).', 950, 'QuantumMechanics'),
('The expectation value of an observable A in state psi is given by which expression?', '<psi|A|psi>', 'A|psi>', '<psi|psi>', 'A^2', '<psi|A|psi>', 'The expectation value is <A> = <psi|A|psi> for a normalized state.', 1250, 'QuantumMechanics'),
('What is the energy spacing between adjacent levels of a quantum harmonic oscillator?', 'h-bar omega', '(1/2) h-bar omega', '2 h-bar omega', 'depends on n', 'h-bar omega', 'Harmonic oscillator levels are equally spaced by h-bar omega.', 1300, 'QuantumMechanics'),
('The probability current is associated with the flow of what quantity?', 'Probability', 'Charge only', 'Mass only', 'Heat', 'Probability', 'The probability current describes the flow of probability density, satisfying continuity.', 1400, 'QuantumMechanics'),
('For an infinite square well of width L, what is the ground-state (n=1) energy proportional to?', '1/L^2', 'L^2', '1/L', 'L', '1/L^2', 'E_1 = pi^2 h-bar^2 / (2mL^2), proportional to 1/L^2.', 1400, 'QuantumMechanics'),
('In the Stern-Gerlach experiment, a beam of silver atoms splits into how many components, demonstrating spin quantization?', 'Two', 'One', 'Three', 'A continuous band', 'Two', 'The beam splits into two, revealing the two spin-1/2 states (m_s = +1/2, -1/2).', 1200, 'QuantumMechanics'),
('Which quantity is conserved and corresponds to the magnetic quantum number m_l?', 'z-component of orbital angular momentum', 'Total energy', 'Spin magnitude', 'Radial momentum', 'z-component of orbital angular momentum', 'The magnetic quantum number m_l specifies the z-component of orbital angular momentum (m_l*h-bar).', 1350, 'QuantumMechanics'),
('The total angular momentum quantum number combining orbital and spin is denoted by what symbol?', 'j', 'l', 'n', 's', 'j', 'The total angular momentum quantum number j combines orbital l and spin s.', 1100, 'QuantumMechanics'),
('What happens to tunneling probability as the barrier width increases?', 'It decreases exponentially', 'It increases linearly', 'It stays constant', 'It increases exponentially', 'It decreases exponentially', 'Tunneling probability falls off exponentially with increasing barrier width.', 1500, 'QuantumMechanics'),
('What is the magnitude of orbital angular momentum for quantum number l?', 'sqrt(l(l+1)) h-bar', 'l*h-bar', 'l^2 h-bar', '(2l+1) h-bar', 'sqrt(l(l+1)) h-bar', 'The magnitude of orbital angular momentum is sqrt(l(l+1)) times h-bar.', 1600, 'QuantumMechanics'),
('A photon of wavelength 500 nm has approximately what energy? (use E = hc/lambda)', '2.48 eV', '12.4 eV', '0.5 eV', '24.8 eV', '2.48 eV', 'E = 1240 eV*nm / 500 nm = 2.48 eV.', 1650, 'QuantumMechanics'),
('In which type of system are the energy eigenstates Hermite polynomials times a Gaussian?', 'Quantum harmonic oscillator', 'Infinite square well', 'Hydrogen atom', 'Free particle', 'Quantum harmonic oscillator', 'Harmonic oscillator eigenstates are Hermite polynomials multiplied by a Gaussian envelope.', 1700, 'QuantumMechanics'),
('Using Bohr''s model, the radius of the n-th orbit scales as which power of n?', 'n^2', 'n', '1/n', 'n^3', 'n^2', 'The Bohr radius for level n scales as r_n = n^2 a_0, proportional to n^2.', 1850, 'QuantumMechanics');
INSERT INTO thermodynamics (question, answer1, answer2, answer3, answer4, correctanswer, feedback, score, subject) VALUES
('What does the zeroth law of thermodynamics establish?', 'Conservation of energy', 'The existence of temperature and thermal equilibrium', 'Entropy always increases', 'Absolute zero is unreachable', 'The existence of temperature and thermal equilibrium', 'The zeroth law states that two systems each in thermal equilibrium with a third are in equilibrium with each other, defining temperature.', 720, 'Thermodynamics'),
('Which temperature scale has its zero point at absolute zero?', 'Celsius', 'Fahrenheit', 'Kelvin', 'Rankine only', 'Kelvin', 'The Kelvin scale is an absolute scale whose zero is absolute zero, the point of minimum thermal energy.', 700, 'Thermodynamics'),
('What is the value of absolute zero on the Celsius scale?', '0 C', '-273.15 C', '-100 C', '273.15 C', '-273.15 C', 'Absolute zero corresponds to -273.15 C, which is 0 K.', 760, 'Thermodynamics'),
('The ideal gas law is written as:', 'PV = nRT', 'PV = mRT', 'P/V = nRT', 'PVT = nR', 'PV = nRT', 'The ideal gas law relates pressure, volume, moles, and temperature through the gas constant R.', 740, 'Thermodynamics'),
('In the ideal gas law, what does R represent?', 'The Rydberg constant', 'The universal gas constant', 'The molar mass', 'The Boltzmann constant', 'The universal gas constant', 'R is the universal gas constant, approximately 8.314 J/(mol K).', 770, 'Thermodynamics'),
('According to kinetic theory, the temperature of an ideal gas is proportional to:', 'The average pressure', 'The average kinetic energy of its molecules', 'The total volume', 'The number of molecules', 'The average kinetic energy of its molecules', 'Absolute temperature is directly proportional to the average translational kinetic energy of the gas molecules.', 900, 'Thermodynamics'),
('Boyle''s law states that at constant temperature:', 'P is proportional to V', 'P is proportional to 1/V', 'V is proportional to T', 'P is proportional to T', 'P is proportional to 1/V', 'Boyle''s law states that pressure and volume are inversely proportional at constant temperature.', 820, 'Thermodynamics'),
('Charles''s law relates which two quantities at constant pressure?', 'Pressure and volume', 'Volume and temperature', 'Pressure and temperature', 'Moles and volume', 'Volume and temperature', 'Charles''s law states that volume is directly proportional to absolute temperature at constant pressure.', 840, 'Thermodynamics'),
('The first law of thermodynamics is a statement of:', 'Entropy increase', 'Conservation of energy', 'Conservation of momentum', 'Maximum efficiency', 'Conservation of energy', 'The first law expresses conservation of energy: energy is neither created nor destroyed, only transferred.', 730, 'Thermodynamics'),
('The first law is often written as dU = Q - W. What is U?', 'Work done', 'Heat added', 'Internal energy', 'Enthalpy', 'Internal energy', 'U is the internal energy of the system, a state function whose change equals heat added minus work done by the system.', 800, 'Thermodynamics'),
('For a system that does 200 J of work while absorbing 500 J of heat, the change in internal energy is:', '700 J', '300 J', '-300 J', '0 J', '300 J', 'Using dU = Q - W = 500 - 200 = 300 J.', 980, 'Thermodynamics'),
('Enthalpy H is defined as:', 'U + PV', 'U - PV', 'U + TS', 'U - TS', 'U + PV', 'Enthalpy is defined as H = U + PV and is convenient for processes at constant pressure.', 950, 'Thermodynamics'),
('At constant pressure, the heat added to a system equals the change in:', 'Internal energy', 'Enthalpy', 'Entropy', 'Gibbs free energy', 'Enthalpy', 'At constant pressure, Q equals the change in enthalpy because the PV work is accounted for in H.', 1020, 'Thermodynamics'),
('The specific heat capacity of a substance is the energy required to:', 'Melt one mole', 'Raise the temperature of one unit mass by one degree', 'Boil one kilogram', 'Change phase at constant temperature', 'Raise the temperature of one unit mass by one degree', 'Specific heat capacity is the heat needed to raise the temperature of a unit mass by one degree.', 780, 'Thermodynamics'),
('How much heat is needed to raise 2 kg of water by 10 C (c = 4186 J/kg K)?', '8372 J', '41860 J', '83720 J', '20930 J', '83720 J', 'Q = mcdeltaT = 2 x 4186 x 10 = 83720 J.', 1080, 'Thermodynamics'),
('For an ideal gas, the relationship between molar heat capacities is:', 'Cp - Cv = R', 'Cp + Cv = R', 'Cp = Cv', 'Cv - Cp = R', 'Cp - Cv = R', 'Mayer''s relation states that for an ideal gas Cp - Cv = R.', 1150, 'Thermodynamics'),
('The ratio gamma = Cp/Cv for a monatomic ideal gas is:', '5/3', '7/5', '4/3', '1', '5/3', 'For a monatomic ideal gas Cv = 3R/2 and Cp = 5R/2, so gamma = 5/3.', 1280, 'Thermodynamics'),
('An isothermal process is one that occurs at constant:', 'Pressure', 'Volume', 'Temperature', 'Entropy', 'Temperature', 'An isothermal process takes place at constant temperature.', 760, 'Thermodynamics'),
('An adiabatic process is one in which:', 'Temperature is constant', 'No heat is exchanged with surroundings', 'Pressure is constant', 'Volume is constant', 'No heat is exchanged with surroundings', 'In an adiabatic process Q = 0, so no heat flows in or out of the system.', 820, 'Thermodynamics'),
('An isobaric process occurs at constant:', 'Temperature', 'Volume', 'Pressure', 'Internal energy', 'Pressure', 'An isobaric process is carried out at constant pressure.', 740, 'Thermodynamics'),
('An isochoric (isovolumetric) process occurs at constant:', 'Pressure', 'Volume', 'Temperature', 'Enthalpy', 'Volume', 'An isochoric process occurs at constant volume, so the gas does no work.', 760, 'Thermodynamics'),
('In an isochoric process, the work done by the gas is:', 'Equal to the heat added', 'Zero', 'Equal to PV', 'Negative', 'Zero', 'Since volume does not change, W = PdV = 0 for an isochoric process.', 900, 'Thermodynamics'),
('On a PV diagram, the work done by a gas equals:', 'The slope of the curve', 'The area under the curve', 'The y-intercept', 'The length of the curve', 'The area under the curve', 'Work done by a gas is the integral of P dV, represented by the area under the process curve on a PV diagram.', 990, 'Thermodynamics'),
('For an isothermal expansion of an ideal gas, the work done by the gas is:', 'nRT ln(V2/V1)', 'nR(T2 - T1)', 'PdeltaV', 'Zero', 'nRT ln(V2/V1)', 'For isothermal expansion W = nRT ln(V2/V1), derived by integrating P = nRT/V.', 1450, 'Thermodynamics'),
('In an adiabatic process for an ideal gas, which relation holds?', 'PV = constant', 'PV^gamma = constant', 'P/V = constant', 'V/T = constant', 'PV^gamma = constant', 'For a reversible adiabatic process, PV^gamma is constant where gamma is the heat capacity ratio.', 1380, 'Thermodynamics'),
('Two moles of an ideal gas expand isothermally at 300 K from 1 L to 2 L. The work done (R = 8.314) is approximately:', '1729 J', '3458 J', '865 J', '5000 J', '3458 J', 'W = nRT ln(V2/V1) = 2 x 8.314 x 300 x ln(2) = 3458 J.', 1620, 'Thermodynamics'),
('The second law of thermodynamics, in the Clausius statement, says heat cannot spontaneously flow from:', 'Hot to cold', 'Cold to hot', 'High to low pressure', 'Gas to liquid', 'Cold to hot', 'The Clausius statement says heat cannot flow spontaneously from a colder body to a hotter body.', 900, 'Thermodynamics'),
('Entropy is a measure of:', 'Total energy', 'Disorder or number of microstates', 'Temperature', 'Pressure', 'Disorder or number of microstates', 'Entropy quantifies the disorder of a system, related to the number of accessible microstates.', 850, 'Thermodynamics'),
('For a reversible process, the change in entropy is defined as:', 'dS = Q/T', 'dS = integral of dQ_rev/T', 'dS = W/T', 'dS = U/T', 'dS = integral of dQ_rev/T', 'Entropy change for a reversible process is the integral of dQ_rev divided by absolute temperature.', 1200, 'Thermodynamics'),
('In any spontaneous process in an isolated system, the total entropy:', 'Decreases', 'Stays constant', 'Increases', 'Becomes zero', 'Increases', 'The second law requires that the total entropy of an isolated system increases for spontaneous (irreversible) processes.', 880, 'Thermodynamics'),
('What is the entropy change when 1 kg of ice melts at 0 C? (latent heat = 334000 J/kg)', '1223 J/K', '334000 J/K', '273 J/K', '0 J/K', '1223 J/K', 'deltaS = Q/T = 334000 / 273.15 = 1223 J/K, since melting occurs at constant temperature.', 1700, 'Thermodynamics'),
('A heat engine takes in heat Qh and rejects Qc. Its efficiency is:', '1 - Qc/Qh', 'Qc/Qh', '1 - Qh/Qc', 'Qh/Qc', '1 - Qc/Qh', 'Thermal efficiency is the net work divided by heat input, equal to 1 - Qc/Qh.', 1100, 'Thermodynamics'),
('The efficiency of a Carnot engine operating between temperatures Th and Tc is:', '1 - Tc/Th', 'Tc/Th', '1 - Th/Tc', 'Th/Tc', '1 - Tc/Th', 'The Carnot efficiency depends only on the absolute temperatures: eta = 1 - Tc/Th.', 1250, 'Thermodynamics'),
('A Carnot engine operates between 600 K and 300 K. Its maximum efficiency is:', '25%', '50%', '75%', '100%', '50%', 'eta = 1 - Tc/Th = 1 - 300/600 = 0.50, or 50%.', 1300, 'Thermodynamics'),
('Why is no real heat engine 100% efficient?', 'Energy is destroyed', 'Some heat must be rejected to a cold reservoir', 'Work is created from nothing', 'Friction adds energy', 'Some heat must be rejected to a cold reservoir', 'The second law requires that some heat be rejected to a cold reservoir, so efficiency is always below 100%.', 980, 'Thermodynamics'),
('The coefficient of performance (COP) of a refrigerator is defined as:', 'Qc/W', 'W/Qc', 'Qh/W', 'W/Qh', 'Qc/W', 'A refrigerator''s COP is the heat removed from the cold space divided by the work input, Qc/W.', 1180, 'Thermodynamics'),
('A refrigerator removes 600 J from its interior using 150 J of work. Its COP is:', '4', '0.25', '5', '3', '4', 'COP = Qc/W = 600/150 = 4.', 1350, 'Thermodynamics'),
('A Carnot refrigerator operates between 250 K and 300 K. Its maximum COP is:', '5', '6', '4', '0.2', '5', 'COP_carnot = Tc/(Th - Tc) = 250/(300-250) = 5.', 1750, 'Thermodynamics'),
('The third law of thermodynamics states that as temperature approaches absolute zero:', 'Pressure approaches zero', 'Entropy approaches a constant minimum (zero for a perfect crystal)', 'Volume approaches infinity', 'Internal energy approaches infinity', 'Entropy approaches a constant minimum (zero for a perfect crystal)', 'The third law states that the entropy of a perfect crystal approaches zero as temperature approaches absolute zero.', 1050, 'Thermodynamics'),
('During a phase transition at constant pressure, the temperature of the substance:', 'Rises steadily', 'Falls steadily', 'Remains constant', 'Oscillates', 'Remains constant', 'During a phase change the temperature stays constant while latent heat is absorbed or released.', 820, 'Thermodynamics'),
('Latent heat of vaporization is the energy required to:', 'Raise temperature by one degree', 'Convert a unit mass from liquid to gas at constant temperature', 'Melt a unit mass of solid', 'Ionize a gas', 'Convert a unit mass from liquid to gas at constant temperature', 'Latent heat of vaporization is the heat needed to convert a unit mass of liquid to vapor at constant temperature.', 880, 'Thermodynamics'),
('How much heat is needed to boil 0.5 kg of water already at 100 C? (Lv = 2260000 J/kg)', '1130000 J', '2260000 J', '565000 J', '4520000 J', '1130000 J', 'Q = mLv = 0.5 x 2260000 = 1130000 J.', 1250, 'Thermodynamics'),
('Heat transfer through direct contact within a solid, without bulk motion, is called:', 'Convection', 'Radiation', 'Conduction', 'Advection', 'Conduction', 'Conduction transfers heat through a material by molecular collisions without bulk movement of matter.', 720, 'Thermodynamics'),
('Heat transfer by the bulk movement of a fluid is called:', 'Conduction', 'Convection', 'Radiation', 'Diffusion', 'Convection', 'Convection transfers heat through the bulk motion of fluids carrying thermal energy.', 740, 'Thermodynamics'),
('Heat transfer that requires no medium and travels via electromagnetic waves is:', 'Conduction', 'Convection', 'Radiation', 'Conduction and convection', 'Radiation', 'Radiation transfers energy through electromagnetic waves and requires no material medium.', 760, 'Thermodynamics'),
('The Stefan-Boltzmann law states that radiated power is proportional to:', 'T', 'T squared', 'T to the fourth power', 'T cubed', 'T to the fourth power', 'The Stefan-Boltzmann law states that radiated power per unit area is proportional to the fourth power of absolute temperature.', 1300, 'Thermodynamics'),
('The rate of conductive heat flow through a slab is proportional to:', 'The thickness of the slab', 'The temperature difference across it', 'The fourth power of temperature', 'The inverse of area', 'The temperature difference across it', 'Fourier''s law gives conductive heat flow proportional to area and temperature gradient, hence the temperature difference.', 1150, 'Thermodynamics'),
('The Gibbs free energy is defined as:', 'G = H - TS', 'G = U - TS', 'G = H + TS', 'G = U + PV', 'G = H - TS', 'Gibbs free energy is G = H - TS and determines spontaneity at constant temperature and pressure.', 1200, 'Thermodynamics'),
('A process at constant temperature and pressure is spontaneous when:', 'deltaG > 0', 'deltaG = 0', 'deltaG < 0', 'deltaH < 0 only', 'deltaG < 0', 'A negative change in Gibbs free energy indicates a spontaneous process at constant T and P.', 1280, 'Thermodynamics'),
('The Helmholtz free energy A = U - TS determines spontaneity at constant temperature and constant:', 'Pressure', 'Volume', 'Enthalpy', 'Entropy', 'Volume', 'Helmholtz free energy A = U - TS governs spontaneity for processes at constant temperature and volume.', 1900, 'Thermodynamics');
